CREATE OR REPLACE FUNCTION public.ajuste_inventario(p_codigo text, p_tipo text, p_cantidad numeric, p_costo numeric, p_motivo text, p_detalle text, p_sucursal_id uuid DEFAULT NULL::uuid, p_sucursal_nombre text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- refrimar_envuelta
begin
    if p_cantidad is not null and (p_cantidad < 0 or p_cantidad > 1000000000) then raise exception 'El valor de cantidad no es válido'; end if;
    return ajuste_inventario_base(p_codigo => p_codigo, p_tipo => p_tipo, p_cantidad => p_cantidad, p_costo => p_costo, p_motivo => p_motivo, p_detalle => p_detalle, p_sucursal_id => p_sucursal_id, p_sucursal_nombre => p_sucursal_nombre, p_usuario => p_usuario);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ajuste_inventario_base(p_codigo text, p_tipo text, p_cantidad numeric, p_costo numeric, p_motivo text, p_detalle text, p_sucursal_id uuid DEFAULT NULL::uuid, p_sucursal_nombre text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_motivos text[] := array['Merma', 'Daño', 'Robo o pérdida', 'Vencido', 'Error de conteo', 'Uso interno', 'Devolución a proveedor', 'Entrada sin factura', 'Otro'];
    v_desc text; v_costo numeric; v_valor numeric; v_umbral numeric; v_res jsonb; v_id uuid;
begin
    if p_motivo is null or not (p_motivo = any (v_motivos)) then raise exception 'Elige el motivo del ajuste'; end if;
    if p_motivo = 'Otro' and nullif(trim(coalesce(p_detalle, '')), '') is null then raise exception 'Explica el motivo del ajuste'; end if;
    if p_tipo not in ('entrada', 'salida') then raise exception 'Tipo debe ser entrada o salida'; end if;
    if coalesce(p_cantidad, 0) <= 0 then raise exception 'La cantidad debe ser mayor a cero'; end if;
    select descripcion, coalesce(costo, 0) into v_desc, v_costo from productos where codigo = p_codigo;
    if not found then raise exception 'Producto % no existe', p_codigo; end if;
    v_valor := round(p_cantidad * coalesce(nullif(p_costo, 0), v_costo), 2);
    select coalesce(nullif(opciones ->> 'ajuste_aprobacion_usd', '')::numeric, 100) into v_umbral from configuracion limit 1;
    v_umbral := coalesce(v_umbral, 100);
    if v_umbral > 0 and v_valor > v_umbral and not refrimar_puede_aprobar(p_usuario) then
        insert into ajustes_solicitudes (producto_codigo, producto_descripcion, tipo, cantidad, costo_unitario, valor_usd, motivo, detalle, sucursal_id, sucursal_nombre, solicitado_por)
        values (p_codigo, v_desc, p_tipo, p_cantidad, coalesce(p_costo, 0), v_valor, p_motivo, p_detalle, p_sucursal_id, p_sucursal_nombre, p_usuario)
        returning id into v_id;
        return jsonb_build_object('ok', true, 'pendiente', true, 'id', v_id, 'valor_usd', v_valor, 'umbral', v_umbral);
    end if;
    v_res := kardex_ajuste(p_codigo, p_tipo, p_cantidad, coalesce(p_costo, 0),
        'Ajuste · ' || p_motivo || coalesce(' · ' || nullif(trim(p_detalle), ''), ''), p_sucursal_id, p_usuario);
    return v_res || jsonb_build_object('pendiente', false);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ajuste_resolver_base(p_id uuid, p_aprobar boolean, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s ajustes_solicitudes; v_res jsonb := '{}'::jsonb;
begin
    if not refrimar_puede_aprobar(p_usuario) then raise exception 'Tu usuario no puede aprobar ajustes'; end if;
    select * into s from ajustes_solicitudes where id = p_id for update;
    if not found then raise exception 'Solicitud no encontrada'; end if;
    if s.estado <> 'pendiente' then raise exception 'Esta solicitud ya fue %', s.estado; end if;
    if p_aprobar then
        v_res := kardex_ajuste(s.producto_codigo, s.tipo, s.cantidad, s.costo_unitario,
            'Ajuste · ' || s.motivo || coalesce(' · ' || nullif(trim(s.detalle), ''), '') || ' · aprobado por ' || coalesce(p_usuario, ''), s.sucursal_id, s.solicitado_por);
    end if;
    update ajustes_solicitudes set estado = case when p_aprobar then 'aprobado' else 'rechazado' end, resuelto_por = p_usuario, resuelto_at = now() where id = p_id;
    return jsonb_build_object('ok', true) || v_res;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.anular_venta(p_venta_id uuid, p_usuario text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
    v_venta record;
    v_det record;
begin
    select * into v_venta from ventas where id = p_venta_id for update;

    if not found then
        raise exception 'Venta no encontrada';
    end if;

    if v_venta.estado = 'anulada' then
        raise exception 'La venta ya está anulada';
    end if;

    for v_det in
        select * from detalle_venta where venta_id = p_venta_id
    loop
        if v_venta.sucursal_id is null or v_venta.sucursal_id = v_casa then
            update productos set stock = stock + v_det.cantidad
            where codigo = v_det.producto_codigo;
        else
            insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
            values (v_venta.sucursal_id, v_det.producto_codigo, v_det.descripcion, v_det.cantidad)
            on conflict (sucursal_id, producto_codigo)
            do update set stock = sucursal_stock.stock + excluded.stock, updated_at = now();
        end if;
    end loop;

    if v_venta.metodo_pago != 'credito' then
        insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre, metodo_pago)
        values (
            'egreso',
            'Anulación de venta ' || coalesce(v_venta.numero, '') || ' - ' || coalesce(v_venta.cliente_nombre, ''),
            coalesce(v_venta.total_usd, 0),
            coalesce(v_venta.total_bs, 0),
            v_venta.sucursal_id,
            coalesce(p_usuario, 'Sistema'),
            v_venta.metodo_pago
        );
    end if;

    if v_venta.metodo_pago = 'credito' then
        update clientes set saldo_pendiente = greatest(coalesce(saldo_pendiente, 0) - coalesce(v_venta.total_usd, 0), 0)
        where rif = v_venta.cliente_rif;
    elsif v_venta.metodo_pago = 'pago_movil' then
        delete from pagos_moviles where venta_numero = v_venta.numero;
    end if;

    update ventas set estado = 'anulada' where id = p_venta_id;

    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.anular_venta_motivo(p_venta_id uuid, p_usuario text, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_motivo text := nullif(trim(coalesce(p_motivo, '')), '');
    v_res jsonb; v_doc text;
begin
    if v_motivo is null or length(v_motivo) < 5 then
        raise exception 'Escribe el motivo de la anulación (mínimo 5 letras)';
    end if;
    v_res := anular_venta(p_venta_id, p_usuario);
    v_doc := documento_numero_siguiente('nota_credito', now());
    update ventas set anulacion_motivo = v_motivo, anulada_por = coalesce(nullif(trim(coalesce(p_usuario, '')), ''), 'Sistema'),
                      anulada_at = now(), anulacion_doc = v_doc
    where id = p_venta_id;
    return coalesce(v_res, '{}'::jsonb) || jsonb_build_object('ok', true, 'nota_credito', v_doc, 'motivo', v_motivo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.aplicar_abono_cxp(p_compra_id uuid, p_monto numeric, p_fecha date, p_sucursal_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
    v_sucursal uuid;
    v_saldo numeric;
begin
    if p_monto is null or p_monto <= 0 then
        return jsonb_build_object('ok', false, 'error', 'El monto del abono debe ser mayor a 0');
    end if;

    select id, coalesce(sucursal_id, '00000000-0000-0000-0000-000000000001')
    into v_id, v_sucursal
    from compras_proveedores where id = p_compra_id for update;

    if v_id is null then
        return jsonb_build_object('ok', false, 'error', 'Factura no encontrada');
    end if;

    if p_sucursal_id is not null and v_sucursal <> p_sucursal_id then
        return jsonb_build_object('ok', false, 'error', 'La factura pertenece a otra sucursal');
    end if;

    insert into abonos_compras (compra_proveedor_id, monto, fecha, sucursal_id)
    values (p_compra_id, p_monto, coalesce(p_fecha, current_date), v_sucursal);

    select greatest(coalesce(monto_usd, 0) - (coalesce(monto_abonado, 0) + p_monto), 0)
    into v_saldo
    from compras_proveedores
    where id = p_compra_id;

    update compras_proveedores
    set monto_abonado = coalesce(monto_abonado, 0) + p_monto,
        saldo_pendiente = v_saldo,
        fecha_pago = case when v_saldo <= 0.005 then coalesce(fecha_pago, p_fecha) else fecha_pago end,
        estado = case when v_saldo <= 0.005 then 'Pagada' else 'Pendiente' end
    where id = p_compra_id;

    return jsonb_build_object('ok', true, 'saldo_pendiente', v_saldo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.asistencia_ajustar(p_usuario_id uuid, p_fecha date, p_datos jsonb, p_editor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u record; v_id uuid;
begin
    select id, nombre into u from usuarios where id = p_usuario_id;
    if not found then raise exception 'Ese colaborador no existe.'; end if;
    insert into asistencias (usuario_id, usuario_nombre, fecha, sucursal_id, sucursal_nombre)
    values (u.id, u.nombre, p_fecha, coalesce((select sucursal_id from horario_personas where usuario_id = u.id), '00000000-0000-0000-0000-000000000001'), null)
    on conflict (usuario_id, fecha) do nothing;
    update asistencias set
        entrada_at      = case when p_datos ? 'entrada'      then (p_fecha + nullif(p_datos ->> 'entrada', '')::time) at time zone 'America/Caracas' else entrada_at end,
        almuerzo_ini_at = case when p_datos ? 'almuerzo_ini' then (p_fecha + nullif(p_datos ->> 'almuerzo_ini', '')::time) at time zone 'America/Caracas' else almuerzo_ini_at end,
        almuerzo_fin_at = case when p_datos ? 'almuerzo_fin' then (p_fecha + nullif(p_datos ->> 'almuerzo_fin', '')::time) at time zone 'America/Caracas' else almuerzo_fin_at end,
        salida_at       = case when p_datos ? 'salida'       then (p_fecha + nullif(p_datos ->> 'salida', '')::time) at time zone 'America/Caracas' else salida_at end,
        notas           = case when p_datos ? 'notas'        then nullif(trim(p_datos ->> 'notas'), '') else notas end,
        sucursal_nombre = coalesce(sucursal_nombre, case when sucursal_id = '00000000-0000-0000-0000-000000000001' then 'Casa Matriz' else (select nombre from sucursales where id = sucursal_id) end),
        editado_por = p_editor, editado_at = now()
    where usuario_id = u.id and fecha = p_fecha returning id into v_id;
    return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.asistencia_marcar(p_nombre text, p_pin text, p_tipo text, p_sucursal_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_clave text := 'asis:' || lower(trim(coalesce(p_nombre, '')));
    li login_intentos; u record; a asistencias; v_hoy date := (now() at time zone 'America/Caracas')::date;
    v_tipo text := lower(coalesce(p_tipo, 'auto')); v_suc uuid; v_suc_nombre text; v_hora text;
begin
    select * into li from login_intentos where clave = v_clave;
    if found and li.bloqueado_hasta is not null and li.bloqueado_hasta > now() then
        return jsonb_build_object('ok', false, 'error', 'Demasiados intentos. Espera unos minutos.');
    end if;
    select * into u from usuarios where nombre = p_nombre and activo is not false limit 1;
    if not found or u.pin is null or u.pin <> coalesce(p_pin, '') then
        insert into login_intentos (clave, fallos, actualizado_at) values (v_clave, 1, now())
        on conflict (clave) do update set
            fallos = case when login_intentos.actualizado_at < now() - interval '30 minutes' then 1 else login_intentos.fallos + 1 end,
            actualizado_at = now()
        returning * into li;
        if li.fallos >= 5 and li.fallos % 5 = 0 then
            update login_intentos set bloqueado_hasta = now() + interval '5 minutes' where clave = v_clave;
        end if;
        return jsonb_build_object('ok', false, 'error', 'PIN incorrecto');
    end if;
    delete from login_intentos where clave = v_clave;

    v_suc := coalesce(p_sucursal_id, (select sucursal_id from horario_personas where usuario_id = u.id), '00000000-0000-0000-0000-000000000001');
    v_suc_nombre := case when v_suc = '00000000-0000-0000-0000-000000000001' then 'Casa Matriz' else (select nombre from sucursales where id = v_suc) end;

    select * into a from asistencias where usuario_id = u.id and fecha = v_hoy;
    if v_tipo = 'auto' then
        v_tipo := case when a.id is null or a.entrada_at is null then 'entrada'
                       when a.salida_at is not null then 'ya'
                       when a.almuerzo_ini_at is null then 'almuerzo'
                       when a.almuerzo_fin_at is null then 'regreso'
                       else 'salida' end;
    end if;
    if v_tipo = 'ya' then
        return jsonb_build_object('ok', false, 'error', u.nombre || ', ya marcaste tu salida de hoy a las ' || to_char(a.salida_at at time zone 'America/Caracas', 'HH12:MI AM') || '.');
    end if;

    if a.id is null then
        if v_tipo <> 'entrada' then return jsonb_build_object('ok', false, 'error', 'Primero marca tu entrada.'); end if;
        insert into asistencias (usuario_id, usuario_nombre, sucursal_id, sucursal_nombre, fecha, entrada_at)
        values (u.id, u.nombre, v_suc, v_suc_nombre, v_hoy, now()) returning * into a;
    else
        if v_tipo = 'entrada' then
            if a.entrada_at is not null then return jsonb_build_object('ok', false, 'error', 'Ya marcaste tu entrada hoy a las ' || to_char(a.entrada_at at time zone 'America/Caracas', 'HH12:MI AM') || '.'); end if;
            update asistencias set entrada_at = now() where id = a.id returning * into a;
        elsif v_tipo = 'almuerzo' then
            if a.almuerzo_ini_at is not null then return jsonb_build_object('ok', false, 'error', 'Ya marcaste tu salida a almorzar.'); end if;
            if a.salida_at is not null then return jsonb_build_object('ok', false, 'error', 'Ya marcaste tu salida de hoy.'); end if;
            update asistencias set almuerzo_ini_at = now() where id = a.id returning * into a;
        elsif v_tipo = 'regreso' then
            if a.almuerzo_ini_at is null then return jsonb_build_object('ok', false, 'error', 'No has marcado la salida a almorzar.'); end if;
            if a.almuerzo_fin_at is not null then return jsonb_build_object('ok', false, 'error', 'Ya marcaste tu regreso del almuerzo.'); end if;
            update asistencias set almuerzo_fin_at = now() where id = a.id returning * into a;
        elsif v_tipo = 'salida' then
            if a.salida_at is not null then return jsonb_build_object('ok', false, 'error', 'Ya marcaste tu salida de hoy.'); end if;
            update asistencias set salida_at = now(), almuerzo_fin_at = case when almuerzo_ini_at is not null and almuerzo_fin_at is null then now() else almuerzo_fin_at end
            where id = a.id returning * into a;
        else
            raise exception 'Tipo de marca inválido';
        end if;
    end if;
    v_hora := to_char(now() at time zone 'America/Caracas', 'HH12:MI AM');
    return jsonb_build_object('ok', true, 'nombre', u.nombre, 'tipo', v_tipo, 'hora', v_hora, 'tienda', v_suc_nombre,
        'mensaje', case v_tipo when 'entrada' then '¡Buen día, ' || u.nombre || '! Entrada a las ' || v_hora
                               when 'almuerzo' then 'Buen provecho, ' || u.nombre || '. Salida a almorzar a las ' || v_hora
                               when 'regreso' then 'Bienvenido de vuelta, ' || u.nombre || '. Regreso a las ' || v_hora
                               else 'Hasta mañana, ' || u.nombre || '. Salida a las ' || v_hora end);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.auditoria_listar(p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date, p_tabla text DEFAULT NULL::text, p_texto text DEFAULT NULL::text, p_limite integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid; v_ok boolean := true;
begin
    begin
        execute 'select refrimar_sesion_uid(0)' into v_uid;
        execute 'select refrimar_tiene_permiso($1, ''configuracion'') or refrimar_tiene_permiso($1, ''ver_equipo'')' into v_ok using v_uid;
        if v_uid is null then v_ok := (select coalesce(modo, 'aviso') = 'aviso' from seguridad_config where id = 1); end if;
    exception when others then v_ok := true;
    end;
    if not coalesce(v_ok, false) then raise exception 'Solo el dueño o administración pueden ver la bitácora'; end if;
    return coalesce((select jsonb_agg(a order by a.fecha desc) from (
        select id, fecha, tabla, accion, registro, usuario_nombre, cambios from auditoria
        where (p_desde is null or fecha >= p_desde) and (p_hasta is null or fecha < p_hasta + 1)
          and (p_tabla is null or p_tabla = '' or tabla = p_tabla)
          and (p_texto is null or p_texto = '' or registro ilike '%' || p_texto || '%' or usuario_nombre ilike '%' || p_texto || '%' or cambios::text ilike '%' || p_texto || '%')
        order by fecha desc limit least(greatest(coalesce(p_limite, 300), 1), 2000)) a), '[]'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.auditoria_registrar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_old jsonb := case when tg_op <> 'INSERT' then to_jsonb(old) else '{}'::jsonb end;
    v_new jsonb := case when tg_op <> 'DELETE' then to_jsonb(new) else '{}'::jsonb end;
    v_ign text[] := array['updated_at', 'created_at', 'pin', 'stock', 'ultimo_aviso', 'ultima_conexion', 'saldo_pendiente', 'monto_abonado'];
    v_cambios jsonb := '{}'::jsonb; k text; v_quien jsonb; v_reg text;
begin
    if tg_op = 'UPDATE' then
        for k in select key from jsonb_each(v_new) loop
            if k = any (v_ign) then continue; end if;
            if (v_old -> k) is distinct from (v_new -> k) then
                v_cambios := v_cambios || jsonb_build_object(k, jsonb_build_array(v_old -> k, v_new -> k));
            end if;
        end loop;
        if v_cambios = '{}'::jsonb then return new; end if;     -- solo cambió el stock u otro campo automático
    elsif tg_op = 'INSERT' then
        v_cambios := v_new - v_ign;
    else
        v_cambios := v_old - v_ign;
    end if;
    v_reg := coalesce(v_new ->> 'codigo', v_old ->> 'codigo', v_new ->> 'numero', v_old ->> 'numero', v_new ->> 'rif', v_old ->> 'rif',
                      v_new ->> 'nombre', v_old ->> 'nombre', v_new ->> 'id', v_old ->> 'id');
    v_quien := refrimar_quien();
    insert into auditoria (tabla, accion, registro, usuario_id, usuario_nombre, cambios)
    values (tg_table_name, case tg_op when 'INSERT' then 'crear' when 'UPDATE' then 'editar' else 'borrar' end,
            left(v_reg, 120), nullif(v_quien ->> 'id', '')::uuid, v_quien ->> 'nombre', v_cambios);
    return coalesce(new, old);
exception when others then
    return coalesce(new, old);    -- la bitácora nunca bloquea una operación
end;
$function$
;

CREATE OR REPLACE FUNCTION public.caja_registrar_movimiento(p_tipo text, p_concepto text, p_monto_usd numeric, p_monto_bs numeric, p_sucursal_id uuid, p_usuario text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- refrimar_envuelta
begin
    if p_monto_usd is not null and (p_monto_usd < 0 or p_monto_usd > 1000000000) then raise exception 'El valor de monto usd no es válido'; end if;
    return caja_registrar_movimiento_base(p_tipo => p_tipo, p_concepto => p_concepto, p_monto_usd => p_monto_usd, p_monto_bs => p_monto_bs, p_sucursal_id => p_sucursal_id, p_usuario => p_usuario);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.caja_registrar_movimiento_base(p_tipo text, p_concepto text, p_monto_usd numeric, p_monto_bs numeric, p_sucursal_id uuid, p_usuario text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.caja_movimientos (
    tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre
  ) VALUES (
    p_tipo, p_concepto, p_monto_usd, p_monto_bs, p_sucursal_id, p_usuario
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cierre_diario_auto(p_fecha date DEFAULT NULL::date, p_sucursal_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
    v_f date := coalesce(p_fecha, (now() at time zone 'America/Caracas')::date);
    v_s uuid := coalesce(p_sucursal_id, v_casa);
    v_ini timestamptz := (v_f::timestamp at time zone 'America/Caracas');
    v_fin timestamptz := ((v_f + 1)::timestamp at time zone 'America/Caracas');
    m record; v_vtas int := 0; v_cajeros text := ''; v_turnos int := 0; v_dif numeric := 0;
    v_old text; v_manual text; v_desc text;
begin
    if to_regclass('public.cierre_diario') is null or to_regclass('public.caja_movimientos') is null then
        return jsonb_build_object('ok', false, 'error', 'Falta la tabla de cierre diario o de caja');
    end if;
    select
        coalesce(sum(case when tipo = 'venta' and metodo_pago = 'pago_movil' then monto_bs end), 0) as pm,
        coalesce(sum(case when tipo = 'venta' and metodo_pago = 'punto' then monto_bs end), 0) as punto,
        coalesce(sum(case when metodo_pago = 'efectivo' then case when tipo = 'venta' then monto_bs when tipo = 'egreso' and concepto ilike 'vuelto%' then -monto_bs else 0 end end), 0) as ef_bs,
        coalesce(sum(case when metodo_pago = 'divisa' then case when tipo = 'venta' then monto_usd when tipo = 'egreso' and concepto ilike 'vuelto%' then -monto_usd else 0 end end), 0) as ef_usd,
        coalesce(sum(case when tipo = 'venta' and metodo_pago = 'transferencia' then monto_bs end), 0) as transf,
        coalesce(sum(case when tipo = 'venta' and metodo_pago in ('zelle', 'binance', 'otro') then monto_usd end), 0) as otros_usd,
        coalesce(sum(case when tipo = 'egreso' and coalesce(concepto, '') not ilike 'vuelto%' and (
                 (coalesce(monto_usd, 0) > 0 and coalesce(monto_bs, 0) = 0) or coalesce(metodo_pago, '') in ('divisa', 'zelle', 'binance', 'otro')) then monto_usd end), 0) as g_usd,
        coalesce(sum(case when tipo = 'egreso' and coalesce(concepto, '') not ilike 'vuelto%' and not (
                 (coalesce(monto_usd, 0) > 0 and coalesce(monto_bs, 0) = 0) or coalesce(metodo_pago, '') in ('divisa', 'zelle', 'binance', 'otro')) then monto_bs end), 0) as g_bs
    into m
    from caja_movimientos
    where fecha >= v_ini and fecha < v_fin and coalesce(sucursal_id, v_casa) = v_s;

    begin
        select count(*), coalesce(string_agg(distinct usuario_nombre, ', '), '') into v_vtas, v_cajeros
        from ventas where created_at >= v_ini and created_at < v_fin and coalesce(sucursal_id, v_casa) = v_s and coalesce(estado, '') <> 'anulada';
    exception when others then null;
    end;
    begin
        select count(*), coalesce(sum(diferencia_usd), 0) into v_turnos, v_dif
        from turnos where estado = 'cerrado' and cerrado_at >= v_ini and cerrado_at < v_fin and coalesce(sucursal_id, v_casa) = v_s;
    exception when others then null;
    end;

    select descripcion into v_old from cierre_diario where fecha = v_f and sucursal_id = v_s;
    v_manual := case when v_old is null then '' when v_old like '[Auto]%' then coalesce(substring(v_old from ' · Nota: (.*)$'), '') else v_old end;
    v_desc := '[Auto] ' || v_vtas || ' venta(s)' || case when v_cajeros <> '' then ' · cajeros: ' || v_cajeros else '' end
        || ' · turnos cerrados: ' || v_turnos || case when v_turnos > 0 then ' (diferencia ' || to_char(round(v_dif, 2), 'FM999G990D00') || ' $)' else '' end
        || case when m.transf <> 0 then ' · transferencias: ' || to_char(round(m.transf, 2), 'FM999G999G990D00') || ' Bs' else '' end
        || case when m.otros_usd <> 0 then ' · Zelle/Binance/otros: ' || to_char(round(m.otros_usd, 2), 'FM999G990D00') || ' $' else '' end
        || ' · Punto A = todos los pagos con débito'
        || case when v_manual <> '' then ' · Nota: ' || v_manual else '' end;

    insert into cierre_diario (fecha, sucursal_id, pago_movil, punto_a, punto_b, venta_bs, venta_usd, gastos_bs, gastos_usd, descripcion, usuario_nombre, updated_at)
    values (v_f, v_s, round(m.pm, 2), round(m.punto, 2), 0, round(m.ef_bs, 2), round(m.ef_usd, 2), round(m.g_bs, 2), round(m.g_usd, 2), v_desc, 'Automático (cierre de caja)', now())
    on conflict (fecha, sucursal_id) do update set
        pago_movil = excluded.pago_movil, punto_a = excluded.punto_a, punto_b = excluded.punto_b,
        venta_bs = excluded.venta_bs, venta_usd = excluded.venta_usd, gastos_bs = excluded.gastos_bs, gastos_usd = excluded.gastos_usd,
        descripcion = excluded.descripcion, usuario_nombre = excluded.usuario_nombre, updated_at = now();
    return jsonb_build_object('ok', true, 'fecha', v_f, 'ventas', v_vtas, 'pago_movil', round(m.pm, 2), 'punto', round(m.punto, 2),
        'efectivo_bs', round(m.ef_bs, 2), 'efectivo_usd', round(m.ef_usd, 2), 'gastos_bs', round(m.g_bs, 2), 'gastos_usd', round(m.g_usd, 2));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cierre_diario_guardar_v2(p_fecha date, p_sucursal_id uuid, p_pago_movil numeric DEFAULT 0, p_punto_a numeric DEFAULT 0, p_punto_b numeric DEFAULT 0, p_venta_bs numeric DEFAULT 0, p_venta_usd numeric DEFAULT 0, p_gastos_bs numeric DEFAULT 0, p_gastos_usd numeric DEFAULT 0, p_descripcion text DEFAULT ''::text, p_loq_bs numeric DEFAULT 0, p_loq_usd numeric DEFAULT 0, p_reparto_bs numeric DEFAULT 0, p_reparto_usd numeric DEFAULT 0, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  v_id := public.cierre_diario_guardar(
    p_fecha, p_pago_movil, p_punto_a, p_punto_b,
    p_venta_bs, p_venta_usd, p_gastos_bs, p_gastos_usd,
    p_loq_bs, p_loq_usd, p_reparto_bs, p_reparto_usd,
    p_sucursal_id, p_usuario, p_descripcion
  );
  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cierre_diario_importar_v2(p_rows jsonb, p_sucursal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row jsonb;
  v_fecha date;
  v_id uuid;
  v_nuevas integer := 0;
  v_actualizadas integer := 0;
  v_descartadas integer := 0;
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'p_rows debe ser array JSON');
  END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    v_fecha := NULL;
    BEGIN
      v_fecha := (v_row->>'fecha')::date;
    EXCEPTION WHEN OTHERS THEN
      v_fecha := NULL;
    END;

    IF v_fecha IS NULL THEN
      v_descartadas := v_descartadas + 1;
      CONTINUE;
    END IF;

    v_id := public.cierre_diario_importar(
      p_sucursal_id,
      COALESCE((v_row->>'usuario')::text, 'Sistema'),
      v_fecha,
      COALESCE((v_row->>'pago_movil')::numeric, 0),
      COALESCE((v_row->>'punto_a')::numeric, 0),
      COALESCE((v_row->>'punto_b')::numeric, 0),
      COALESCE((v_row->>'venta_bs')::numeric, 0),
      COALESCE((v_row->>'venta_usd')::numeric, 0),
      COALESCE((v_row->>'gastos_bs')::numeric, 0),
      COALESCE((v_row->>'gastos_usd')::numeric, 0),
      COALESCE((v_row->>'loq_bs')::numeric, 0),
      COALESCE((v_row->>'loq_usd')::numeric, 0),
      COALESCE((v_row->>'reparto_bs')::numeric, 0),
      COALESCE((v_row->>'reparto_usd')::numeric, 0),
      COALESCE((v_row->>'descripcion')::text, '')
    );

    v_nuevas := v_nuevas + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'nuevas', v_nuevas,
    'actualizadas', 0,
    'descartadas', v_descartadas
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_eliminar(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_id is null then
        raise exception 'Falta el cliente';
    end if;
    delete from clientes where id = p_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_guardar(p_nombre text, p_id uuid DEFAULT NULL::uuid, p_rif text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_direccion text DEFAULT NULL::text, p_tipo text DEFAULT 'final'::text, p_limite_credito numeric DEFAULT 0, p_notas text DEFAULT NULL::text, p_sucursal_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    if p_nombre is null or trim(p_nombre) = '' then
        raise exception 'El nombre del cliente es obligatorio';
    end if;
    if p_limite_credito is null then p_limite_credito := 0; end if;

    if p_id is null then
        insert into clientes (nombre, rif, telefono, email, direccion, tipo,
            limite_credito, notas, sucursal_id)
        values (trim(p_nombre), p_rif, p_telefono, p_email, p_direccion,
            coalesce(p_tipo, 'final'), p_limite_credito, p_notas, p_sucursal_id)
        returning id into v_id;
    else
        update clientes
        set nombre = trim(p_nombre), rif = p_rif, telefono = p_telefono,
            email = p_email, direccion = p_direccion, tipo = coalesce(p_tipo, 'final'),
            limite_credito = p_limite_credito, notas = p_notas,
            sucursal_id = coalesce(sucursal_id, p_sucursal_id)
        where id = p_id;
        v_id := p_id;
    end if;

    if v_id is null then
        raise exception 'No se pudo guardar el cliente';
    end if;
    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_registrar_abono_base(p_cliente_id uuid, p_monto numeric, p_sucursal_id uuid, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_saldo numeric;
    v_nombre text;
begin
    if p_cliente_id is null or p_monto is null or p_monto <= 0 then
        raise exception 'Faltan datos del abono';
    end if;

    select saldo_pendiente, nombre into v_saldo, v_nombre
    from clientes where id = p_cliente_id for update;

    if not found then
        raise exception 'Cliente no encontrado';
    end if;

    v_saldo := coalesce(v_saldo, 0) - p_monto;
    if v_saldo < 0 then v_saldo := 0; end if;

    update clientes set saldo_pendiente = v_saldo where id = p_cliente_id;

    insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs,
        sucursal_id, usuario_nombre, metodo_pago)
    values ('ingreso', 'Abono de cliente ' || coalesce(v_nombre, '') || ' (saldo $' ||
            to_char(p_monto, 'FM999999999999990.00') || ')',
            p_monto, null, p_sucursal_id, coalesce(p_usuario, 'Sistema'), 'efectivo');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_registrar_abono_v2(p_cliente_id uuid, p_monto numeric, p_sucursal_id uuid, p_usuario text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cliente public.clientes%rowtype;
  v_nuevo_saldo numeric;
BEGIN
  SELECT * INTO v_cliente FROM public.clientes WHERE id = p_cliente_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Cliente no encontrado');
  END IF;

  v_nuevo_saldo := GREATEST(COALESCE(v_cliente.saldo_pendiente, 0) - p_monto, 0);

  UPDATE public.clientes
  SET saldo_pendiente = v_nuevo_saldo
  WHERE id = p_cliente_id;

  INSERT INTO public.caja_movimientos (
    fecha, tipo, concepto, monto_usd, notas, sucursal_id, usuario_nombre
  ) VALUES (
    CURRENT_DATE, 'ingreso', 
    'Abono cliente: ' || COALESCE(v_cliente.nombre, p_cliente_id::text),
    p_monto,
    'Registrado por: ' || p_usuario,
    p_sucursal_id, p_usuario
  );

  RETURN jsonb_build_object('ok', true, 'nuevo_saldo', v_nuevo_saldo);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.colaborador_estado(p_id uuid, p_estado text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u record; v_token text;
begin
    select * into u from usuarios where id = p_id for update;
    if not found then raise exception 'Colaborador no encontrado'; end if;
    if p_estado = 'activo' then
        if u.pin is null then raise exception 'Este colaborador todavía no aceptó la invitación'; end if;
        update usuarios set estado = 'activo', activo = true where id = p_id;
    elsif p_estado = 'inactivo' then
        if u.rol = 'admin' and (select count(*) from usuarios where rol = 'admin' and activo and id <> p_id) = 0 then
            raise exception 'No puedes inactivar al único administrador';
        end if;
        update usuarios set estado = 'inactivo', activo = false where id = p_id;
    elsif p_estado = 'cancelado' then
        if u.estado <> 'pendiente' then raise exception 'Solo se cancelan invitaciones pendientes'; end if;
        update usuarios set estado = 'cancelado', activo = false where id = p_id;
        update invitaciones set cancelada = true where usuario_id = p_id and usada_at is null;
    elsif p_estado = 'pendiente' then
        if u.estado not in ('cancelado', 'pendiente') then raise exception 'Este colaborador ya aceptó la invitación'; end if;
        update usuarios set estado = 'pendiente', activo = false, invitado_at = now() where id = p_id;
        v_token := invitacion_vigente(p_id, p_usuario);
    else
        raise exception 'Estado inválido';
    end if;
    return jsonb_build_object('ok', true, 'estado', p_estado, 'token', v_token);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.colaborador_guardar(p_id uuid, p_datos jsonb, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    d jsonb := coalesce(p_datos, '{}'::jsonb);
    v_id uuid := p_id;
    v_nombres text := nullif(trim(coalesce(d->>'nombres', '')), '');
    v_apellido text := nullif(trim(coalesce(d->>'apellido', '')), '');
    v_email text := nullif(lower(trim(coalesce(d->>'email', ''))), '');
    v_rol text := coalesce(nullif(trim(coalesce(d->>'rol', '')), ''), 'cajero');
    v_permisos jsonb := case when jsonb_typeof(d->'permisos') = 'array' then d->'permisos' else '[]'::jsonb end;
    v_suc uuid[];
    v_nombre text;
    v_estado text;
    v_token text;
begin
    if v_nombres is null then raise exception 'Escribe el nombre'; end if;
    if v_email is null then raise exception 'Escribe el correo'; end if;
    if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Correo inválido'; end if;
    v_suc := case when jsonb_typeof(d->'sucursales') = 'array'
                  then array(select distinct (x)::uuid from jsonb_array_elements_text(d->'sucursales') x)
                  else '{}'::uuid[] end;
    if v_rol <> 'admin' and coalesce(array_length(v_suc, 1), 0) = 0 then
        raise exception 'Selecciona al menos una tienda';
    end if;
    v_nombre := trim(v_nombres || ' ' || coalesce(v_apellido, ''));
    if exists (select 1 from usuarios where lower(nombre) = lower(v_nombre) and id is distinct from v_id) then
        raise exception 'Ya existe un colaborador llamado %', v_nombre;
    end if;
    if exists (select 1 from usuarios where lower(email) = v_email and id is distinct from v_id) then
        raise exception 'Ese correo ya está asignado a otro colaborador';
    end if;

    if v_id is null then
        insert into usuarios (nombre, nombres, apellido, email, telefono, rol, permisos, sucursales, sucursal_id,
                              activo, estado, invitado_at)
        values (v_nombre, v_nombres, v_apellido, v_email, nullif(trim(coalesce(d->>'telefono', '')), ''), v_rol, v_permisos, v_suc,
                case when array_length(v_suc, 1) = 1 then v_suc[1] else null end,
                false, 'pendiente', now())
        returning id into v_id;
        v_estado := 'pendiente';
    else
        select estado into v_estado from usuarios where id = v_id;
        if not found then raise exception 'Colaborador no encontrado'; end if;
        update usuarios set
            nombre = v_nombre, nombres = v_nombres, apellido = v_apellido, email = v_email,
            telefono = coalesce(nullif(trim(coalesce(d->>'telefono', '')), ''), telefono),
            rol = v_rol, permisos = v_permisos, sucursales = v_suc,
            sucursal_id = case when array_length(v_suc, 1) = 1 then v_suc[1] else null end
        where id = v_id;
    end if;

    if v_estado = 'pendiente' then
        v_token := invitacion_vigente(v_id, p_usuario);
    end if;
    return jsonb_build_object('ok', true, 'id', v_id, 'estado', v_estado, 'token', v_token);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.colaborador_pin_restablecer(p_id uuid, p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_pin is null or length(p_pin) < 32 then raise exception 'PIN inválido'; end if;
    update usuarios set pin = p_pin where id = p_id;
    if not found then raise exception 'Colaborador no encontrado'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.compra_fiscal_guardar(p_id uuid, p_numero_control text, p_base numeric, p_exento numeric, p_alicuota numeric, p_iva numeric, p_retencion numeric, p_tasa numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if coalesce(p_base, 0) < 0 or coalesce(p_exento, 0) < 0 or coalesce(p_iva, 0) < 0 or coalesce(p_retencion, 0) < 0 then raise exception 'Los montos no pueden ser negativos'; end if;
    if p_alicuota is not null and p_alicuota not in (0, 8, 16, 31) then raise exception 'Alícuota inválida'; end if;
    update compras_proveedores set numero_control = nullif(trim(coalesce(p_numero_control, '')), ''), base_imponible = p_base, exento = p_exento,
        alicuota = p_alicuota, iva_monto = p_iva, retencion_iva = p_retencion, tasa_bcv = p_tasa
    where id = p_id;
    if not found then raise exception 'Factura de compra no encontrada'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.compra_proveedor_guardar(p_proveedor text, p_numero text, p_sucursal_id uuid, p_id uuid DEFAULT NULL::uuid, p_rif text DEFAULT NULL::text, p_fecha_emision date DEFAULT CURRENT_DATE, p_fecha_vencimiento date DEFAULT NULL::date, p_monto numeric DEFAULT 0, p_estado text DEFAULT 'Pendiente'::text, p_notas text DEFAULT NULL::text, p_sucursal_nombre text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    if p_proveedor is null or trim(p_proveedor) = '' then
        raise exception 'El proveedor es obligatorio';
    end if;
    if p_numero is null or trim(p_numero) = '' then
        raise exception 'El número de factura es obligatorio';
    end if;

    if p_id is null then
        if p_monto is null or p_monto <= 0 then
            raise exception 'El monto debe ser mayor a 0';
        end if;
        insert into compras_proveedores
            (proveedor, rif, numero, fecha_emision, fecha_vencimiento, monto_usd,
             monto_abonado, saldo_pendiente, estado, notas, sucursal_id, sucursal_nombre)
        values
            (trim(p_proveedor), p_rif, trim(p_numero), coalesce(p_fecha_emision, current_date),
             p_fecha_vencimiento, p_monto, 0, p_monto, coalesce(p_estado, 'Pendiente'),
             p_notas, p_sucursal_id, p_sucursal_nombre)
        returning id into v_id;
    else
        update compras_proveedores
        set proveedor = trim(p_proveedor), rif = p_rif, numero = trim(p_numero),
            fecha_emision = coalesce(p_fecha_emision, fecha_emision),
            fecha_vencimiento = p_fecha_vencimiento,
            estado = coalesce(p_estado, estado), notas = p_notas,
            sucursal_id = p_sucursal_id, sucursal_nombre = p_sucursal_nombre
        where id = p_id;
        v_id := p_id;
    end if;

    if v_id is null then
        raise exception 'No se pudo guardar la factura';
    end if;
    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.compra_registrar(p_proveedor_id uuid, p_proveedor_nombre text, p_fecha date, p_notas text, p_sucursal_id uuid, p_sucursal_nombre text, p_usuario text, p_items text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- refrimar_envuelta
begin
    p_usuario := coalesce((select nombre from usuarios where id = refrimar_sesion_uid(30)), p_usuario);
    return compra_registrar_base(p_proveedor_id => p_proveedor_id, p_proveedor_nombre => p_proveedor_nombre, p_fecha => p_fecha, p_notas => p_notas, p_sucursal_id => p_sucursal_id, p_sucursal_nombre => p_sucursal_nombre, p_usuario => p_usuario, p_items => p_items);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.compra_registrar_base(p_proveedor_id uuid, p_proveedor_nombre text, p_fecha date, p_notas text, p_sucursal_id uuid, p_sucursal_nombre text, p_usuario text, p_items text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_orden_id uuid;
  v_numero text;
  v_item jsonb;
  v_total numeric := 0;
BEGIN
  v_numero := 'OC-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('ordenes_compra_seq'::regclass)::text, 4, '0');

  INSERT INTO public.ordenes_compra (
    numero, proveedor_id, proveedor_nombre, fecha, notas,
    sucursal_id, sucursal_nombre, estado
  ) VALUES (
    v_numero, p_proveedor_id, p_proveedor_nombre, p_fecha, p_notas,
    p_sucursal_id, p_sucursal_nombre, 'pendiente'
  ) RETURNING id INTO v_orden_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items::jsonb)
  LOOP
    INSERT INTO public.compra_detalles (
      compra_id, producto_codigo, cantidad, costo_unitario
    ) VALUES (
      v_orden_id,
      v_item->>'codigo',
      (v_item->>'cantidad')::numeric,
      (v_item->>'costo_unitario')::numeric
    );

    INSERT INTO public.sucursal_stock (sucursal_id, producto_codigo, stock, costo, updated_at)
    VALUES (p_sucursal_id, v_item->>'codigo', 0, (v_item->>'costo_unitario')::numeric, now())
    ON CONFLICT (sucursal_id, producto_codigo) DO NOTHING;

    UPDATE public.sucursal_stock
    SET stock = stock + (v_item->>'cantidad')::numeric,
        updated_at = now()
    WHERE sucursal_id = p_sucursal_id
      AND producto_codigo = v_item->>'codigo';

    INSERT INTO public.kardex_movimientos (
      producto_codigo, tipo, cantidad, costo_unitario, producto_descripcion,
      sucursal_id, usuario_nombre
    ) VALUES (
      v_item->>'codigo', 'entrada', (v_item->>'cantidad')::numeric,
      (v_item->>'costo_unitario')::numeric,
      v_item->>'descripcion',
      p_sucursal_id, p_usuario
    );

    v_total := v_total + ((v_item->>'cantidad')::numeric * (v_item->>'costo_unitario')::numeric);
  END LOOP;

  INSERT INTO public.cuentas_por_pagar (
    sucursal_id, sucursal_nombre, proveedor_id, proveedor_nombre,
    numero_factura, fecha, fecha_vencimiento, monto, saldo, estado
  ) VALUES (
    p_sucursal_id, p_sucursal_nombre, p_proveedor_id, p_proveedor_nombre,
    v_numero, p_fecha, p_fecha + interval '30 days', v_total, v_total, 'pendiente'
  );

  RETURN jsonb_build_object('id', v_orden_id, 'numero', v_numero, 'ok', true);
END; $function$
;

CREATE OR REPLACE FUNCTION public.config_actualizar_tasa(p_tasa numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    if p_tasa is null or p_tasa <= 0 then
        raise exception 'Tasa inválida';
    end if;
    select id into v_id from configuracion limit 1;
    if v_id is null then
        insert into configuracion (nombre_negocio, tasa_bcv_manual, iva_incluido, updated_at)
        values ('REFRIMAR', p_tasa, false, now());
    else
        update configuracion set tasa_bcv_manual = p_tasa, updated_at = now() where id = v_id;
    end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.config_actualizar_tasa_v2(p_tasa numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.config_actualizar_tasa(p_tasa);
  RETURN jsonb_build_object('ok', true, 'tasa', p_tasa);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.config_fiscal_guardar(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid; v_rif text := upper(regexp_replace(coalesce(p ->> 'rif', ''), '[^A-Za-z0-9]', '', 'g'));
    v_razon text := nullif(trim(coalesce(p ->> 'razon_social', '')), '');
    v_extra jsonb := '{}'::jsonb;
begin
    if v_razon is null then raise exception 'Escribe la razón social'; end if;
    if not rif_valido(v_rif) then raise exception 'El RIF no es válido. Escríbelo así: J-12345678-9'; end if;
    v_rif := substr(v_rif, 1, 1) || '-' || substr(v_rif, 2, 8) || '-' || substr(v_rif, 10, 1);
    if p ? 'nombre_comercial' then v_extra := v_extra || jsonb_build_object('nombre_comercial', nullif(trim(p ->> 'nombre_comercial'), '')); end if;
    if p ? 'logo' then
        if length(coalesce(p ->> 'logo', '')) > 120000 then raise exception 'El logo es muy pesado: usa una imagen más pequeña'; end if;
        v_extra := v_extra || jsonb_build_object('logo', nullif(p ->> 'logo', ''));
    end if;
    if p ? 'ciudad' then v_extra := v_extra || jsonb_build_object('ciudad', nullif(trim(p ->> 'ciudad'), '')); end if;
    if p ? 'estado_ve' then v_extra := v_extra || jsonb_build_object('estado_ve', nullif(trim(p ->> 'estado_ve'), '')); end if;
    select id into v_id from configuracion limit 1;
    if v_id is null then
        insert into configuracion (nombre_negocio, rif, direccion, telefono, email, opciones)
        values (v_razon, v_rif, nullif(trim(p ->> 'direccion'), ''), nullif(trim(p ->> 'telefono'), ''), nullif(lower(trim(p ->> 'email')), ''), v_extra);
    else
        update configuracion set nombre_negocio = v_razon, rif = v_rif,
            direccion = nullif(trim(coalesce(p ->> 'direccion', '')), ''), telefono = nullif(trim(coalesce(p ->> 'telefono', '')), ''),
            email = nullif(lower(trim(coalesce(p ->> 'email', ''))), ''),
            opciones = coalesce(opciones, '{}'::jsonb) || v_extra, updated_at = now()
        where id = v_id;
    end if;
    -- La ficha de la empresa en la plataforma queda igual (si es una empresa de la plataforma)
    begin
        if to_regclass('saas.empresas') is not null and current_schema() <> 'public' then
            execute 'update saas.empresas set razon_social = $1, rif = $2, nombre = coalesce($3, nombre), actualizada_at = now() where esquema = $4'
            using v_razon, v_rif, nullif(trim(coalesce(p ->> 'nombre_comercial', '')), ''), current_schema();
        end if;
    exception when others then null;
    end;
    return jsonb_build_object('ok', true, 'rif', v_rif);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.config_guardar(p_nombre_negocio text, p_rif text DEFAULT NULL::text, p_direccion text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_mensaje text DEFAULT NULL::text, p_tasa_bcv_manual numeric DEFAULT 36.50, p_iva_incluido boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    if p_nombre_negocio is null or trim(p_nombre_negocio) = '' then
        raise exception 'El nombre del negocio es obligatorio';
    end if;
    select id into v_id from configuracion limit 1;

    if v_id is null then
        insert into configuracion (nombre_negocio, rif, direccion, telefono, email,
            mensaje_agradecimiento, tasa_bcv_manual, iva_incluido, updated_at)
        values (p_nombre_negocio, p_rif, p_direccion, p_telefono, p_email,
            p_mensaje, p_tasa_bcv_manual, p_iva_incluido, now())
        returning id into v_id;
    else
        update configuracion
        set nombre_negocio = p_nombre_negocio, rif = p_rif, direccion = p_direccion,
            telefono = p_telefono, email = p_email, mensaje_agradecimiento = p_mensaje,
            tasa_bcv_manual = p_tasa_bcv_manual, iva_incluido = p_iva_incluido,
            updated_at = now()
        where id = v_id;
    end if;

    if v_id is null then
        raise exception 'No se pudo guardar la configuración';
    end if;
    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.config_opciones_guardar(p_opciones jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
    if jsonb_typeof(p_opciones) <> 'object' then raise exception 'Opciones inválidas'; end if;
    if p_opciones ? 'logo' and length(coalesce(p_opciones ->> 'logo', '')) > 120000 then raise exception 'El logo es muy pesado: usa una imagen más pequeña'; end if;
    select id into v_id from configuracion limit 1;
    if v_id is null then
        insert into configuracion (nombre_negocio, opciones) values ('Mi empresa', p_opciones);
    else
        update configuracion set opciones = coalesce(opciones, '{}'::jsonb) || (p_opciones - 'iva_incluido'),
            iva_incluido = case when p_opciones ? 'iva_incluido' then coalesce((p_opciones ->> 'iva_incluido')::boolean, iva_incluido) else iva_incluido end,
            updated_at = now() where id = v_id;
    end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.config_rubro_guardar(p_rubro text, p_opciones jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_rubro is null or p_rubro !~ '^[a-z_]{3,30}$' then raise exception 'Rubro inválido'; end if;
    update configuracion set rubro = p_rubro,
        opciones = case when jsonb_typeof(p_opciones) = 'object' then coalesce(opciones, '{}'::jsonb) || p_opciones else opciones end;
    if not found then
        insert into configuracion (rubro, opciones) values (p_rubro, coalesce(p_opciones, '{}'::jsonb));
    end if;
    return jsonb_build_object('ok', true, 'rubro', p_rubro);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.conteo_cerrar(p_id uuid, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_c record;
    r record;
    v_delta numeric;
    v_nuevo numeric;
    v_ajustes int := 0;
begin
    select * into v_c from conteos where id = p_id for update;
    if not found then raise exception 'Conteo no encontrado'; end if;
    if v_c.estado in ('cerrada', 'cancelada') then raise exception 'Este conteo ya está %', v_c.estado; end if;

    for r in select * from conteo_items where conteo_id = p_id and contado is not null and contado <> stock_sistema loop
        v_delta := r.contado - r.stock_sistema;
        v_nuevo := stock_mover(r.producto_codigo, v_c.sucursal_id, v_delta);
        if v_nuevo < 0 then
            v_nuevo := stock_mover(r.producto_codigo, v_c.sucursal_id, -v_nuevo);
        end if;
        insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total,
            saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
        values (r.producto_codigo, coalesce(r.descripcion, r.producto_codigo), current_date,
            case when v_delta > 0 then 'entrada_ajuste' else 'salida_ajuste' end, v_delta, 0, 0,
            v_nuevo, 0, 'Conteo ' || v_c.numero, coalesce(p_usuario, 'Sistema'), v_c.sucursal_id);
        v_ajustes := v_ajustes + 1;
    end loop;

    update conteos set estado = 'cerrada', cerrado_at = now(), diferencias = v_ajustes where id = p_id;
    return jsonb_build_object('ok', true, 'ajustes', v_ajustes);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.conteo_crear(p_nombre text, p_sucursal_id uuid, p_sucursal_nombre text, p_categoria text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text, p_notas text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
    v_numero text;
    v_n int;
    v_casa boolean := (p_sucursal_id is null or p_sucursal_id = '00000000-0000-0000-0000-000000000001');
begin
    v_numero := 'CI-' || lpad(nextval('seq_conteo')::text, 6, '0');
    insert into conteos (numero, nombre, sucursal_id, sucursal_nombre, filtro_categoria, usuario_nombre, notas)
    values (v_numero, coalesce(nullif(trim(coalesce(p_nombre, '')), ''), 'Conteo ' || to_char(now(), 'DD/MM/YYYY')),
            p_sucursal_id, coalesce(p_sucursal_nombre, 'Casa Matriz'), nullif(trim(coalesce(p_categoria, '')), ''),
            coalesce(p_usuario, 'Sistema'), p_notas)
    returning id into v_id;

    insert into conteo_items (conteo_id, producto_codigo, descripcion, categoria, stock_sistema)
    select v_id, p.codigo, p.descripcion, p.categoria,
           case when v_casa then coalesce(p.stock, 0) else coalesce(ss.stock, 0) end
    from productos p
    left join sucursal_stock ss on ss.producto_codigo = p.codigo and ss.sucursal_id = p_sucursal_id
    where (nullif(trim(coalesce(p_categoria, '')), '') is null or p.categoria ilike trim(p_categoria))
      and (v_casa or ss.producto_codigo is not null);

    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception 'No hay productos para contar con ese filtro'; end if;
    update conteos set items_total = v_n where id = v_id;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero, 'items', v_n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.conteo_crear_lista(p_nombre text, p_sucursal_id uuid, p_sucursal_nombre text, p_codigos jsonb, p_usuario text DEFAULT 'Sistema'::text, p_descripcion text DEFAULT NULL::text, p_fecha_inicio date DEFAULT NULL::date, p_fecha_fin date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
    v_numero text;
    v_n int;
    v_casa boolean := (p_sucursal_id is null or p_sucursal_id = '00000000-0000-0000-0000-000000000001');
begin
    if p_codigos is null or jsonb_typeof(p_codigos) <> 'array' or jsonb_array_length(p_codigos) = 0 then raise exception 'Agrega al menos un producto al conteo'; end if;
    if p_fecha_inicio is not null and p_fecha_fin is not null and p_fecha_fin < p_fecha_inicio then raise exception 'La fecha fin no puede ser antes de la fecha inicio'; end if;
    v_numero := 'CI-' || lpad(nextval('seq_conteo')::text, 6, '0');
    insert into conteos (numero, nombre, sucursal_id, sucursal_nombre, usuario_nombre, notas, fecha_inicio, fecha_fin)
    values (v_numero, coalesce(nullif(trim(coalesce(p_nombre, '')), ''), 'Conteo ' || to_char(now(), 'DD/MM/YYYY')),
            p_sucursal_id, coalesce(p_sucursal_nombre, 'Casa Matriz'), coalesce(p_usuario, 'Sistema'), p_descripcion, p_fecha_inicio, p_fecha_fin)
    returning id into v_id;

    insert into conteo_items (conteo_id, producto_codigo, descripcion, categoria, stock_sistema)
    select v_id, p.codigo, p.descripcion, p.categoria,
           case when v_casa then coalesce(p.stock, 0) else coalesce(ss.stock, 0) end
    from (select distinct value as codigo from jsonb_array_elements_text(p_codigos)) c
    join productos p on p.codigo = c.codigo
    left join sucursal_stock ss on ss.producto_codigo = p.codigo and ss.sucursal_id = p_sucursal_id;

    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception 'Ninguno de los productos existe (o son servicios)'; end if;
    update conteos set items_total = v_n where id = v_id;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero, 'items', v_n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.conteo_estado(p_id uuid, p_estado text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_estado text;
begin
    if p_estado not in ('en_progreso', 'revisado', 'cancelada') then raise exception 'Estado inválido'; end if;
    select estado into v_estado from conteos where id = p_id for update;
    if not found then raise exception 'Conteo no encontrado'; end if;
    if v_estado in ('cerrada', 'cancelada') then raise exception 'Este conteo ya está %', v_estado; end if;
    update conteos set estado = p_estado, cerrado_at = case when p_estado = 'cancelada' then now() else cerrado_at end where id = p_id;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.conteo_guardar(p_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_estado text;
    v_item jsonb;
    v_contado numeric;
begin
    select estado into v_estado from conteos where id = p_id for update;
    if not found then raise exception 'Conteo no encontrado'; end if;
    if v_estado in ('cerrada', 'cancelada') then raise exception 'Este conteo ya está %', v_estado; end if;
    for v_item in select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
        if v_item->>'contado' is null or v_item->>'contado' = '' then
            v_contado := null;
        else
            v_contado := (v_item->>'contado')::numeric;
            if v_contado < 0 then raise exception 'La cantidad contada no puede ser negativa'; end if;
        end if;
        update conteo_items set contado = v_contado
        where conteo_id = p_id and producto_codigo = v_item->>'codigo';
    end loop;
    update conteos c set
        estado = case when c.estado = 'borrador' then 'en_progreso' else c.estado end,
        items_contados = (select count(*) from conteo_items i where i.conteo_id = p_id and i.contado is not null),
        diferencias = (select count(*) from conteo_items i where i.conteo_id = p_id and i.contado is not null and i.contado <> i.stock_sistema)
    where c.id = p_id;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.conteo_items_sin_servicios()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if exists (select 1 from productos where codigo = new.producto_codigo and tipo_producto = 'servicio') then
        return null;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cotizacion_guardar(p_numero text, p_detalle jsonb, p_cliente_nombre text DEFAULT 'Consumidor Final'::text, p_cliente_rif text DEFAULT NULL::text, p_subtotal numeric DEFAULT 0, p_iva numeric DEFAULT 0, p_total_usd numeric DEFAULT 0, p_tasa_bcv numeric DEFAULT 0, p_total_bs numeric DEFAULT 0, p_validez_dias integer DEFAULT 7, p_estado text DEFAULT 'pendiente'::text, p_sucursal_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_cotizacion_id uuid;
    v_row jsonb;
    v_count int := 0;
begin
    if p_numero is null or trim(p_numero) = '' then
        raise exception 'Falta el número de cotización';
    end if;
    if p_detalle is null or jsonb_typeof(p_detalle) <> 'array' or jsonb_array_length(p_detalle) = 0 then
        raise exception 'La cotización no tiene productos';
    end if;

    insert into cotizaciones
        (numero, cliente_nombre, cliente_rif, subtotal, iva, total_usd,
         tasa_bcv, total_bs, validez_dias, estado, sucursal_id)
    values
        (trim(p_numero),
         coalesce(nullif(trim(coalesce(p_cliente_nombre, '')), ''), 'Consumidor Final'),
         p_cliente_rif, coalesce(p_subtotal, 0), coalesce(p_iva, 0), coalesce(p_total_usd, 0),
         coalesce(p_tasa_bcv, 0), coalesce(p_total_bs, 0), coalesce(p_validez_dias, 7),
         coalesce(p_estado, 'pendiente'), p_sucursal_id)
    returning id into v_cotizacion_id;

    for v_row in select value from jsonb_array_elements(p_detalle)
    loop
        if coalesce(v_row->>'producto_codigo', '') = '' then
            continue;
        end if;
        insert into detalle_cotizacion
            (cotizacion_id, producto_codigo, descripcion, cantidad, precio_unitario, descuento, total)
        values
            (v_cotizacion_id,
             v_row->>'producto_codigo',
             v_row->>'descripcion',
             coalesce((v_row->>'cantidad')::numeric, 0),
             coalesce((v_row->>'precio_unitario')::numeric, 0),
             coalesce((v_row->>'descuento')::numeric, 0),
             coalesce((v_row->>'total')::numeric, 0));
        v_count := v_count + 1;
    end loop;

    if v_count = 0 then
        raise exception 'La cotización no tiene productos';
    end if;

    return v_cotizacion_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cotizacion_guardar_v2(p_numero text, p_cliente_nombre text, p_cliente_rif text, p_subtotal numeric, p_iva numeric, p_total_usd numeric, p_tasa_bcv numeric, p_total_bs numeric, p_validez_dias integer, p_estado text, p_detalle jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  v_id := public.cotizacion_guardar(
    p_numero, p_detalle, p_cliente_nombre, p_cliente_rif,
    p_subtotal, p_iva, p_total_usd, p_tasa_bcv, p_total_bs,
    p_validez_dias, p_estado
  );
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'numero', p_numero);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cuenta_guardar(p_id uuid, p_datos jsonb, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    d jsonb := coalesce(p_datos, '{}'::jsonb);
    v_id uuid := p_id;
    v_saldo numeric := coalesce(nullif(d->>'saldo', '')::numeric, 0);
    v_moneda text := upper(coalesce(nullif(d->>'moneda', ''), 'VES'));
    v_def boolean := coalesce((d->>'por_defecto')::boolean, false);
begin
    if nullif(trim(coalesce(d->>'banco', '')), '') is null then raise exception 'Selecciona el banco'; end if;
    if nullif(trim(coalesce(d->>'alias', '')), '') is null then raise exception 'Escribe el alias de la cuenta'; end if;
    if v_moneda not in ('VES', 'USD') then raise exception 'Moneda inválida'; end if;
    if v_def then update cuentas_bancarias set por_defecto = false where moneda = v_moneda; end if;
    if v_id is null then
        insert into cuentas_bancarias (banco, alias, numero, moneda, saldo, metodos, por_defecto)
        values (trim(d->>'banco'), trim(d->>'alias'), nullif(trim(coalesce(d->>'numero', '')), ''), v_moneda, v_saldo,
                case when jsonb_typeof(d->'metodos') = 'array' then array(select jsonb_array_elements_text(d->'metodos')) else '{}' end, v_def)
        returning id into v_id;
        insert into cuenta_movimientos (cuenta_id, tipo, monto, saldo_despues, motivo, usuario_nombre)
        values (v_id, 'saldo_inicial', v_saldo, v_saldo, 'Saldo inicial', p_usuario);
    else
        update cuentas_bancarias set banco = trim(d->>'banco'), alias = trim(d->>'alias'), numero = nullif(trim(coalesce(d->>'numero', '')), ''),
            moneda = v_moneda, por_defecto = v_def, activa = coalesce((d->>'activa')::boolean, activa),
            metodos = case when jsonb_typeof(d->'metodos') = 'array' then array(select jsonb_array_elements_text(d->'metodos')) else metodos end
        where id = v_id;
        if not found then raise exception 'Cuenta no encontrada'; end if;
    end if;
    return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cuenta_movimiento_base(p_cuenta uuid, p_tipo text, p_monto numeric, p_motivo text, p_fecha date DEFAULT CURRENT_DATE, p_referencia text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_saldo numeric; v_delta numeric;
begin
    if p_tipo not in ('ingreso', 'egreso', 'ajuste') then raise exception 'Tipo inválido'; end if;
    if p_monto is null or (p_tipo <> 'ajuste' and p_monto <= 0) then raise exception 'El monto debe ser mayor a 0'; end if;
    select saldo into v_saldo from cuentas_bancarias where id = p_cuenta for update;
    if not found then raise exception 'Cuenta no encontrada'; end if;
    v_delta := case when p_tipo = 'egreso' then -p_monto when p_tipo = 'ingreso' then p_monto else p_monto - v_saldo end;
    update cuentas_bancarias set saldo = saldo + v_delta where id = p_cuenta returning saldo into v_saldo;
    insert into cuenta_movimientos (cuenta_id, fecha, tipo, monto, saldo_despues, motivo, referencia, usuario_nombre)
    values (p_cuenta, coalesce(p_fecha, current_date), p_tipo, v_delta, v_saldo, p_motivo, p_referencia, p_usuario);
    return jsonb_build_object('ok', true, 'saldo', v_saldo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cuenta_transferir(p_origen uuid, p_destino uuid, p_fecha date, p_monto numeric, p_monto_destino numeric, p_motivo text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- refrimar_envuelta
begin
    if p_monto is not null and (p_monto < 0 or p_monto > 1000000000) then raise exception 'El valor de monto no es válido'; end if;
    return cuenta_transferir_base(p_origen => p_origen, p_destino => p_destino, p_fecha => p_fecha, p_monto => p_monto, p_monto_destino => p_monto_destino, p_motivo => p_motivo, p_usuario => p_usuario);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cuenta_transferir_base(p_origen uuid, p_destino uuid, p_fecha date, p_monto numeric, p_monto_destino numeric, p_motivo text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    o record; d record; v_tid uuid := gen_random_uuid(); v_md numeric;
begin
    if p_origen = p_destino then raise exception 'El banco origen y destino no pueden ser el mismo'; end if;
    if p_monto is null or p_monto <= 0 then raise exception 'El monto debe ser mayor a 0'; end if;
    select * into o from cuentas_bancarias where id = p_origen for update;
    if not found then raise exception 'Cuenta origen no encontrada'; end if;
    select * into d from cuentas_bancarias where id = p_destino for update;
    if not found then raise exception 'Cuenta destino no encontrada'; end if;
    if o.moneda <> d.moneda and (p_monto_destino is null or p_monto_destino <= 0) then raise exception 'Las cuentas tienen monedas distintas: indica el monto que llega al destino'; end if;
    v_md := case when o.moneda = d.moneda then p_monto else p_monto_destino end;
    update cuentas_bancarias set saldo = saldo - p_monto where id = p_origen;
    update cuentas_bancarias set saldo = saldo + v_md where id = p_destino;
    insert into cuenta_movimientos (cuenta_id, fecha, tipo, monto, saldo_despues, motivo, usuario_nombre, transferencia_id)
    values (p_origen, coalesce(p_fecha, current_date), 'transferencia_salida', -p_monto, o.saldo - p_monto, coalesce(nullif(p_motivo, ''), 'Transferencia a ' || d.alias), p_usuario, v_tid),
           (p_destino, coalesce(p_fecha, current_date), 'transferencia_entrada', v_md, d.saldo + v_md, coalesce(nullif(p_motivo, ''), 'Transferencia desde ' || o.alias), p_usuario, v_tid);
    return jsonb_build_object('ok', true, 'id', v_tid);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.detalle_venta_completar_costo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
    v_suc uuid;
    v_costo numeric;
begin
    if coalesce(new.costo_unitario, 0) > 0 then
        return new;
    end if;

    select sucursal_id into v_suc from ventas where id = new.venta_id;

    if v_suc is not null and v_suc <> v_casa then
        select costo into v_costo
        from sucursal_stock
        where sucursal_id = v_suc and producto_codigo = new.producto_codigo;
    end if;

    if coalesce(v_costo, 0) <= 0 then
        select costo into v_costo from productos where codigo = new.producto_codigo;
    end if;

    new.costo_unitario := coalesce(v_costo, 0);
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.deuda_marcar_avisada(p_venta_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update ventas set ultimo_aviso = current_date where id = p_venta_id;
  return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.deuda_venta_abonar(p_venta_id uuid, p_monto numeric, p_fecha date DEFAULT NULL::date, p_metodo text DEFAULT 'efectivo'::text, p_notas text DEFAULT NULL::text, p_sucursal_id uuid DEFAULT NULL::uuid, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_cliente_rif text;
    v_cliente_nombre text;
    v_numero text;
    v_total numeric;
    v_abonado numeric;
    v_saldo numeric;
begin
    if p_monto is null or p_monto <= 0 then
        raise exception 'El monto del abono debe ser mayor a 0';
    end if;

    select cliente_rif, cliente_nombre, numero, coalesce(total_usd, 0), coalesce(monto_abonado, 0)
    into v_cliente_rif, v_cliente_nombre, v_numero, v_total, v_abonado
    from ventas
    where id = p_venta_id and metodo_pago = 'credito' and estado = 'completada'
    for update;

    if not found then
        raise exception 'Deuda no encontrada';
    end if;

    v_saldo := greatest(v_total - v_abonado, 0);
    if p_monto > v_saldo + 0.005 then
        raise exception 'El abono supera el saldo pendiente de la deuda (saldo: %)', v_saldo;
    end if;

    insert into abonos_ventas (venta_id, monto, fecha, metodo, usuario_nombre, sucursal_id, notas)
    values (p_venta_id, p_monto, coalesce(p_fecha, current_date),
            coalesce(p_metodo, 'efectivo'), coalesce(p_usuario, 'Sistema'),
            p_sucursal_id, p_notas);

    update ventas set monto_abonado = v_abonado + p_monto where id = p_venta_id;

    if v_cliente_rif is not null and v_cliente_rif <> '' then
        update clientes
        set saldo_pendiente = greatest(coalesce(saldo_pendiente, 0) - p_monto, 0)
        where rif = v_cliente_rif;
    end if;

    insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs,
        sucursal_id, usuario_nombre, metodo_pago)
    values ('ingreso',
            'Abono de cliente ' || coalesce(v_cliente_nombre, '') ||
            ' (deuda ' || coalesce(v_numero, '') || ')',
            p_monto, null, p_sucursal_id, coalesce(p_usuario, 'Sistema'),
            coalesce(p_metodo, 'efectivo'));

    return jsonb_build_object('ok', true, 'saldo_pendiente', greatest(v_saldo - p_monto, 0));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.deuda_venta_crear(p_cliente_id uuid, p_numero text DEFAULT NULL::text, p_monto_usd numeric DEFAULT 0, p_dias_credito integer DEFAULT 30, p_notas text DEFAULT NULL::text, p_sucursal_id uuid DEFAULT NULL::uuid, p_sucursal_nombre text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_nombre text;
    v_rif text;
    v_saldo numeric;
    v_limite numeric;
    v_venta_id uuid;
    v_numero text;
begin
    if p_cliente_id is null then
        raise exception 'Debes seleccionar un cliente';
    end if;
    if p_monto_usd is null or p_monto_usd <= 0 then
        raise exception 'El monto de la deuda debe ser mayor a 0';
    end if;
    if p_dias_credito is null or p_dias_credito < 1 then
        p_dias_credito := 30;
    end if;

    select nombre, rif, coalesce(saldo_pendiente, 0), coalesce(limite_credito, 0)
    into v_nombre, v_rif, v_saldo, v_limite
    from clientes where id = p_cliente_id for update;

    if not found then
        raise exception 'Cliente no encontrado';
    end if;

    if v_limite > 0 and v_saldo + p_monto_usd > v_limite then
        raise exception 'La deuda excede el límite de crédito del cliente (saldo: %, límite: %)',
            v_saldo, v_limite;
    end if;

    v_numero := nullif(trim(coalesce(p_numero, '')), '');
    if v_numero is null then
        v_numero := 'D-' || to_char(now(), 'YYYYMMDD') || '-' ||
                    lpad(floor(random() * 999999)::text, 6, '0');
    end if;

    insert into ventas (numero, cliente_nombre, cliente_rif, subtotal, iva, total_usd,
                        tasa_bcv, total_bs, metodo_pago, estado, sucursal_id, sucursal_nombre,
                        monto_abonado, dias_credito, notas)
    values (v_numero, v_nombre, v_rif, 0, 0, p_monto_usd, 0, 0, 'credito', 'completada',
            p_sucursal_id, p_sucursal_nombre, 0, p_dias_credito, p_notas)
    returning id into v_venta_id;

    update clientes set saldo_pendiente = v_saldo + p_monto_usd where id = p_cliente_id;

    return jsonb_build_object('ok', true, 'venta_id', v_venta_id, 'numero', v_numero);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.deuda_venta_pago_completo(p_venta_id uuid, p_fecha date DEFAULT NULL::date, p_metodo text DEFAULT 'efectivo'::text, p_notas text DEFAULT NULL::text, p_sucursal_id uuid DEFAULT NULL::uuid, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_monto numeric;
begin
    select greatest(coalesce(total_usd, 0) - coalesce(monto_abonado, 0), 0)
    into v_monto
    from ventas
    where id = p_venta_id and metodo_pago = 'credito' and estado = 'completada';

    if v_monto is null then
        raise exception 'Deuda no encontrada';
    end if;
    if v_monto <= 0.005 then
        return jsonb_build_object('ok', true, 'saldo_pendiente', 0, 'mensaje', 'La deuda ya está saldada');
    end if;

    return deuda_venta_abonar(p_venta_id, v_monto, p_fecha, p_metodo, p_notas,
                              p_sucursal_id, p_usuario);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.documento_control_asignar(p_tipo text, p_numero text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    c record; f jsonb; v_actual text; v_pref text; v_seq bigint; v_hasta bigint; v_ancho int; v_ctl text; v_rest bigint;
begin
    -- Si el documento ya tiene número de control, se devuelve el mismo (reimpresión)
    if p_tipo = 'factura' then select numero_control into v_actual from ventas where numero = p_numero;
    elsif p_tipo = 'nota_credito' then execute 'select numero_control from notas_credito where numero = $1' into v_actual using p_numero;
    elsif p_tipo = 'nota_debito' then select numero_control into v_actual from notas_debito where numero = p_numero;
    else raise exception 'Tipo de documento inválido'; end if;
    if v_actual is not null then return jsonb_build_object('ok', true, 'numero_control', v_actual, 'nuevo', false); end if;

    select * into c from configuracion limit 1 for update;
    f := coalesce(c.opciones -> 'facturacion', '{}'::jsonb);
    if coalesce(f ->> 'modo', '') <> 'forma_libre' then
        return jsonb_build_object('ok', false, 'error', 'El negocio no factura en forma libre');
    end if;
    -- Formato "00-00000001": identificador de 2 dígitos + secuencial de hasta 8 (Providencia 0071, art. 44)
    v_actual := coalesce(nullif(f ->> 'proximo_control', ''), nullif(f ->> 'control_desde', ''));
    if v_actual is null or v_actual !~ '^\s*[0-9]{1,2}\s*-\s*[0-9]{1,8}\s*$' then
        raise exception 'Configura el rango de números de control (ej. 00-00000001 hasta 00-00005000) en Primeros pasos → Facturas';
    end if;
    v_pref := lpad(trim(split_part(v_actual, '-', 1)), 2, '0');
    v_seq := trim(split_part(v_actual, '-', 2))::bigint;
    v_ancho := greatest(8, length(trim(split_part(v_actual, '-', 2))));
    if coalesce(f ->> 'control_hasta', '') ~ '^\s*[0-9]{1,2}\s*-\s*[0-9]{1,8}\s*$' then
        v_hasta := trim(split_part(f ->> 'control_hasta', '-', 2))::bigint;
        if v_seq > v_hasta then raise exception 'Se acabaron los números de control (último: %). Pide formatos nuevos a la imprenta y actualiza el rango.', f ->> 'control_hasta'; end if;
        v_rest := v_hasta - v_seq;
    end if;
    v_ctl := v_pref || '-' || lpad(v_seq::text, v_ancho, '0');

    if p_tipo = 'factura' then update ventas set numero_control = v_ctl, serie = nullif(f ->> 'serie', ''), control_asignado_at = now() where numero = p_numero;
    elsif p_tipo = 'nota_credito' then execute 'update notas_credito set numero_control = $1 where numero = $2' using v_ctl, p_numero;
    else update notas_debito set numero_control = v_ctl where numero = p_numero; end if;
    if not found then raise exception 'Documento % no encontrado', p_numero; end if;

    update configuracion set opciones = jsonb_set(coalesce(opciones, '{}'::jsonb), '{facturacion,proximo_control}',
        to_jsonb(v_pref || '-' || lpad((v_seq + 1)::text, v_ancho, '0')), true)
    where id = c.id;
    return jsonb_build_object('ok', true, 'numero_control', v_ctl, 'nuevo', true, 'restantes', v_rest,
        'desde', f ->> 'control_desde', 'hasta', f ->> 'control_hasta');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.documento_numero_siguiente(p_tipo text, p_fecha timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n bigint;
begin
    insert into documento_correlativos (tipo, ultimo) values (p_tipo, 1)
    on conflict (tipo) do update set ultimo = documento_correlativos.ultimo + 1, actualizado = now()
    returning ultimo into v_n;
    if v_n > 99999999 then raise exception 'Se acabó la numeración de % (8 dígitos)', p_tipo; end if;
    return to_char(coalesce(p_fecha, now()) at time zone 'America/Caracas', 'YYYYMM') || lpad(v_n::text, 8, '0');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.documento_numero_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if tg_op = 'UPDATE' then
        if old.numero_doc is not null and new.numero_doc is distinct from old.numero_doc then
            raise exception 'El número del documento % no se puede cambiar', old.numero_doc;
        end if;
        return new;
    end if;
    if new.numero_doc is null then
        new.numero_doc := documento_numero_siguiente(tg_argv[0],
            coalesce(nullif(to_jsonb(new) ->> 'created_at', '')::timestamptz, now()));
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fecha_valida(p_val text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
    if p_val is null then return null; end if;
    if trim(p_val) = '' or lower(trim(p_val)) = 'null' then return null; end if;
    begin
        return trim(p_val)::date;
    exception when others then
        return null;
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.gasto_eliminar_base(p_gasto_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caja_id uuid;
begin
    select caja_movimiento_id into v_caja_id from gastos where id = p_gasto_id;

    if not found then
        raise exception 'Gasto no encontrado';
    end if;

    delete from gastos where id = p_gasto_id;

    if v_caja_id is not null then
        delete from caja_movimientos where id = v_caja_id;
    end if;

    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.gasto_registrar(p_categoria text, p_concepto text, p_monto_usd numeric, p_monto_bs numeric, p_fecha date, p_metodo_pago text, p_sucursal_id uuid, p_usuario text, p_notas text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- refrimar_envuelta
begin
    if p_monto_usd is not null and (p_monto_usd < 0 or p_monto_usd > 1000000000) then raise exception 'El valor de monto usd no es válido'; end if;
    p_usuario := coalesce((select nombre from usuarios where id = refrimar_sesion_uid(30)), p_usuario);
    return gasto_registrar_base(p_categoria => p_categoria, p_concepto => p_concepto, p_monto_usd => p_monto_usd, p_monto_bs => p_monto_bs, p_fecha => p_fecha, p_metodo_pago => p_metodo_pago, p_sucursal_id => p_sucursal_id, p_usuario => p_usuario, p_notas => p_notas);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.gasto_registrar_base(p_categoria text, p_concepto text, p_monto_usd numeric, p_monto_bs numeric, p_fecha date, p_metodo_pago text, p_sucursal_id uuid, p_usuario text, p_notas text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_gasto_id uuid;
    v_caja_id uuid;
begin
    if p_concepto is null or trim(p_concepto) = '' then
        raise exception 'El concepto es obligatorio';
    end if;
    if coalesce(p_monto_usd, 0) <= 0 and coalesce(p_monto_bs, 0) <= 0 then
        raise exception 'Debe indicar un monto';
    end if;

    -- Egreso de caja (solo el monto principal definido; si ambos, prioriza USD)
    insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre, metodo_pago)
    values (
        'egreso',
        'Gasto (' || p_categoria || '): ' || p_concepto,
        coalesce(p_monto_usd, 0),
        coalesce(p_monto_bs, 0),
        p_sucursal_id,
        coalesce(p_usuario, 'Sistema'),
        coalesce(p_metodo_pago, 'efectivo')
    )
    returning id into v_caja_id;

    insert into gastos (categoria, concepto, monto_usd, monto_bs, fecha, metodo_pago, usuario_nombre, sucursal_id, notas, caja_movimiento_id)
    values (p_categoria, p_concepto, coalesce(p_monto_usd, 0), coalesce(p_monto_bs, 0), coalesce(p_fecha, current_date), coalesce(p_metodo_pago, 'efectivo'), p_usuario, p_sucursal_id, p_notas, v_caja_id)
    returning id into v_gasto_id;

    return jsonb_build_object('ok', true, 'gasto_id', v_gasto_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.horario_guardar(p_usuario_id uuid, p_sucursal_id uuid, p_rota boolean, p_semana_base date, p_tolerancia integer, p_filas jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u record; f jsonb; n int := 0; v_ent time; v_sal time;
begin
    select id, nombre into u from usuarios where id = p_usuario_id;
    if not found then raise exception 'Ese colaborador no existe.'; end if;
    if jsonb_typeof(coalesce(p_filas, '[]'::jsonb)) <> 'array' then raise exception 'Horario inválido'; end if;
    insert into horario_personas (usuario_id, usuario_nombre, sucursal_id, rota, semana_base, tolerancia_min, actualizado_at)
    values (u.id, u.nombre, p_sucursal_id, coalesce(p_rota, false), p_semana_base, greatest(0, least(coalesce(p_tolerancia, 10), 120)), now())
    on conflict (usuario_id) do update set usuario_nombre = excluded.usuario_nombre, sucursal_id = excluded.sucursal_id, rota = excluded.rota,
        semana_base = excluded.semana_base, tolerancia_min = excluded.tolerancia_min, actualizado_at = now();
    delete from horarios_personal where usuario_id = u.id;
    for f in select value from jsonb_array_elements(coalesce(p_filas, '[]'::jsonb)) loop
        v_ent := nullif(f ->> 'entrada', '')::time; v_sal := nullif(f ->> 'salida', '')::time;
        if v_ent is null or v_sal is null then continue; end if;   -- día libre
        if v_sal <= v_ent then raise exception 'La salida (%) debe ser después de la entrada (%).', to_char(v_sal, 'HH12:MI AM'), to_char(v_ent, 'HH12:MI AM'); end if;
        insert into horarios_personal (usuario_id, semana, dia, entrada, salida, almuerzo_ini, almuerzo_fin, sucursal_id)
        values (u.id, case when coalesce(p_rota, false) and f ->> 'semana' = 'B' then 'B' else 'A' end, (f ->> 'dia')::smallint, v_ent, v_sal,
                nullif(f ->> 'almuerzo_ini', '')::time, nullif(f ->> 'almuerzo_fin', '')::time, nullif(f ->> 'sucursal_id', '')::uuid)
        on conflict (usuario_id, semana, dia) do update set entrada = excluded.entrada, salida = excluded.salida,
            almuerzo_ini = excluded.almuerzo_ini, almuerzo_fin = excluded.almuerzo_fin, sucursal_id = excluded.sucursal_id;
        n := n + 1;
    end loop;
    return jsonb_build_object('ok', true, 'dias', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.importacion_desactivar_faltantes(p_id uuid, p_codigos text[], p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int := 0; v_suc uuid;
begin
    select sucursal_id into v_suc from importaciones_productos where id = p_id and deshecha_at is null and estado in ('en_curso', 'completada');
    if not found then raise exception 'La importación no existe o ya se deshizo'; end if;
    if coalesce(array_length(p_codigos, 1), 0) = 0 then raise exception 'El archivo no trae códigos'; end if;

    -- Respaldo: cómo estaba cada producto antes de desactivarlo
    insert into importacion_cambios (importacion_id, codigo, accion, antes, sucursal_id)
    select p_id, p.codigo, 'desactivado', to_jsonb(p), null
    from productos p
    where coalesce(p.activo, true)
      and lower(p.codigo) <> all (select lower(c) from unnest(p_codigos) c)
      and coalesce(to_jsonb(p)->>'tipo_producto', 'fisico') <> 'servicio'
      and coalesce((to_jsonb(p)->>'es_kit')::boolean, false) = false
      and not exists (select 1 from importacion_cambios x where x.importacion_id = p_id and x.codigo = p.codigo);

    update productos p set activo = false
    from importacion_cambios x
    where x.importacion_id = p_id and x.accion = 'desactivado' and x.codigo = p.codigo and coalesce(p.activo, true);
    get diagnostics v_n = row_count;

    return jsonb_build_object('ok', true, 'desactivados', v_n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.importacion_deshacer(p_id uuid, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    imp record; c record; v_cols text; v_actual numeric; v_nuevo numeric; v_delta numeric;
    n_rest int := 0; n_desact int := 0; n_stock int := 0; n_react int := 0;
begin
    select * into imp from importaciones_productos where id = p_id for update;
    if not found then raise exception 'Importación no encontrada'; end if;
    if imp.deshecha_at is not null then raise exception 'Esta importación ya se deshizo'; end if;
    if not exists (select 1 from importacion_cambios where importacion_id = p_id) then
        raise exception 'Esta importación se hizo antes de poder deshacer (no tiene respaldo)';
    end if;

    select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
    from information_schema.columns
    where table_schema = 'public' and table_name = 'productos'
      and column_name not in ('id', 'codigo', 'stock', 'created_at') and is_generated = 'NEVER';

    for c in select * from importacion_cambios where importacion_id = p_id order by id loop
        if c.accion = 'actualizado' and c.antes is not null then
            execute format('update productos p set (%s) = (select %s from jsonb_populate_record(null::productos, $1) x) where p.codigo = $2',
                           v_cols, regexp_replace(v_cols, '(^|, )', '\1x.', 'g'))
            using c.antes, c.codigo;
            n_rest := n_rest + 1;
        elsif c.accion = 'creado' then
            update productos set activo = false where codigo = c.codigo;
            n_desact := n_desact + 1;
        elsif c.accion = 'desactivado' then
            update productos set activo = coalesce((c.antes->>'activo')::boolean, true) where codigo = c.codigo;
            n_react := n_react + 1;
        end if;
        -- Stock: se quita solo lo que movió la importación
        if c.stock_despues is not null and c.stock_antes is not null and c.stock_despues <> c.stock_antes then
            v_actual := stock_en(c.codigo, c.sucursal_id);
            v_delta := -(c.stock_despues - c.stock_antes);
            v_nuevo := v_actual + v_delta;
            if c.sucursal_id is null then
                update productos set stock = v_nuevo where codigo = c.codigo;
            else
                update sucursal_stock set stock = v_nuevo, updated_at = now() where sucursal_id = c.sucursal_id and producto_codigo = c.codigo;
            end if;
            insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total,
                saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
            select c.codigo, p.descripcion, current_date, case when v_delta > 0 then 'entrada_ajuste' else 'salida_ajuste' end, v_delta,
                   coalesce(p.costo, 0), abs(v_delta) * coalesce(p.costo, 0), v_nuevo, coalesce(p.costo, 0),
                   'Deshacer importación ' || coalesce(imp.archivo, ''), coalesce(p_usuario, 'Sistema'), c.sucursal_id
            from productos p where p.codigo = c.codigo;
            n_stock := n_stock + 1;
        end if;
    end loop;

    update importaciones_productos set estado = 'deshecha', deshecha_at = now(), deshecha_por = p_usuario,
        deshacer_resumen = jsonb_build_object('restaurados', n_rest, 'desactivados', n_desact, 'stock', n_stock, 'reactivados', n_react)
    where id = p_id;
    return jsonb_build_object('ok', true, 'restaurados', n_rest, 'desactivados', n_desact, 'stock', n_stock, 'reactivados', n_react);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.importacion_iniciar(p_archivo text, p_sucursal_id uuid, p_sucursal_nombre text, p_usuario text, p_modo_stock text, p_filas integer, p_tipo text DEFAULT 'productos'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
    insert into importaciones_productos (archivo, sucursal_id, sucursal_nombre, usuario_nombre, modo_stock, filas, estado, tipo)
    values (left(p_archivo, 200), p_sucursal_id, p_sucursal_nombre, p_usuario, p_modo_stock, coalesce(p_filas, 0), 'en_curso', coalesce(p_tipo, 'productos'))
    returning id into v_id;
    return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.importar_abonos_masiva(p_rows jsonb, p_sucursal_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_row jsonb;
    v_compra_id uuid;
    v_monto numeric;
    v_fecha date;
    v_aplicados int := 0;
    v_no_encontrados int := 0;
    v_duplicados int := 0;
    v_descartados int := 0;
begin
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
        return jsonb_build_object('ok', false, 'error', 'Debes enviar un array JSON');
    end if;

    for v_row in select value from jsonb_array_elements(p_rows)
    loop
        v_monto := numero_valido(v_row->>'monto');
        if v_monto is null or v_monto <= 0 then
            v_descartados := v_descartados + 1;
            continue;
        end if;

        select id into v_compra_id
        from compras_proveedores
        where upper(proveedor) = upper(trim(coalesce(v_row->>'proveedor', '')))
          and numero = trim(coalesce(v_row->>'factura_numero', v_row->>'numero', ''))
          and (p_sucursal_id is null or sucursal_id = p_sucursal_id)
        limit 1;

        if v_compra_id is null then
            v_no_encontrados := v_no_encontrados + 1;
            continue;
        end if;

        v_fecha := coalesce(fecha_valida(v_row->>'fecha'), current_date);

        if v_row->>'id' is not null
           and v_row->>'id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
           and exists (select 1 from abonos_compras where abono_origen_id = (v_row->>'id')::uuid) then
            v_duplicados := v_duplicados + 1;
            continue;
        end if;

        insert into abonos_compras (compra_proveedor_id, monto, fecha, abono_origen_id, sucursal_id)
        select v_compra_id, v_monto, v_fecha,
               case when v_row->>'id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                    then (v_row->>'id')::uuid
                    else null end,
               coalesce(sucursal_id, '00000000-0000-0000-0000-000000000001')
        from compras_proveedores
        where id = v_compra_id;

        v_aplicados := v_aplicados + 1;
    end loop;

    return jsonb_build_object(
        'ok', true,
        'aplicados', v_aplicados,
        'no_encontrados', v_no_encontrados,
        'duplicados', v_duplicados,
        'descartados', v_descartados
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.importar_cxp_masiva(p_rows jsonb, p_sucursal_id uuid DEFAULT NULL::uuid, p_sucursal_nombre text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_row jsonb;
    v_proveedor text;
    v_numero text;
    v_estado text;
    v_monto numeric;
    v_saldo numeric;
    v_abonado numeric;
    v_sucursal uuid;
    v_sucursal_nombre text;
    v_nuevas int := 0;
    v_actualizadas int := 0;
    v_descartadas int := 0;
    v_ins record;
begin
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
        return jsonb_build_object('ok', false, 'error', 'Debes enviar un array JSON');
    end if;

    for v_row in select value from jsonb_array_elements(p_rows)
    loop
        v_proveedor := upper(trim(coalesce(v_row->>'proveedor', '')));
        v_numero := trim(coalesce(v_row->>'numero', ''));
        if v_proveedor = '' or v_numero = '' then
            v_descartadas := v_descartadas + 1;
            continue;
        end if;

        -- Sucursal: prioridad fila > parámetro > Casa Matriz
        if v_row->>'sucursal_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
            v_sucursal := (v_row->>'sucursal_id')::uuid;
        else
            v_sucursal := coalesce(p_sucursal_id, '00000000-0000-0000-0000-000000000001');
        end if;
        v_sucursal_nombre := nullif(trim(coalesce(v_row->>'sucursal_nombre', p_sucursal_nombre, '')), '');
        if v_sucursal_nombre is null then
            v_sucursal_nombre := 'Casa Matriz';
        end if;

        v_estado := upper(trim(coalesce(v_row->>'estado', 'Pendiente')));
        if v_estado not in ('PENDIENTE', 'PAGADA', 'VENCIDA', 'ANULADA') then
            v_estado := 'PENDIENTE';
        end if;

        v_monto := greatest(coalesce(numero_valido(v_row->>'monto_usd'),
                                     numero_valido(v_row->>'monto'), 0), 0);
        v_saldo := greatest(coalesce(numero_valido(v_row->>'saldo_pendiente'), 0), 0);
        v_abonado := greatest(coalesce(numero_valido(v_row->>'monto_abonado'), 0),
                              v_monto - v_saldo, 0);

        with ins as (
            insert into compras_proveedores
                (proveedor, rif, numero, fecha_emision, fecha_vencimiento,
                 monto_usd, monto_abonado, saldo_pendiente, estado, notas,
                 foto_url, fecha_pago, factura_origen_id, origen,
                 sucursal_id, sucursal_nombre)
            values
                (v_proveedor,
                 nullif(trim(coalesce(v_row->>'rif', '')), ''),
                 v_numero,
                 coalesce(fecha_valida(v_row->>'fecha_emision'),
                          fecha_valida(v_row->>'fecha'),
                          current_date),
                 coalesce(fecha_valida(v_row->>'fecha_vencimiento'),
                          fecha_valida(v_row->>'vencimiento')),
                 v_monto,
                 v_abonado,
                 v_saldo,
                 v_estado,
                 nullif(trim(coalesce(v_row->>'notas', '')), ''),
                 nullif(trim(coalesce(v_row->>'foto_url', '')), ''),
                 coalesce(fecha_valida(v_row->>'fecha_pago'),
                          fecha_valida(v_row->>'fecha_vencimiento')),
                 case when v_row->>'factura_origen_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                      then (v_row->>'factura_origen_id')::uuid
                      else null end,
                 'migracion',
                 v_sucursal,
                 v_sucursal_nombre)
            on conflict (sucursal_id, proveedor, numero) do update set
                rif = excluded.rif,
                fecha_emision = excluded.fecha_emision,
                fecha_vencimiento = excluded.fecha_vencimiento,
                monto_usd = excluded.monto_usd,
                monto_abonado = excluded.monto_abonado,
                saldo_pendiente = excluded.saldo_pendiente,
                estado = excluded.estado,
                notas = excluded.notas,
                foto_url = excluded.foto_url,
                fecha_pago = excluded.fecha_pago,
                sucursal_id = excluded.sucursal_id,
                sucursal_nombre = excluded.sucursal_nombre,
                origen = 'migracion'
            returning (xmax = 0) as es_insert
        )
        select count(*) filter (where es_insert) as nuevas,
               count(*) filter (where not es_insert) as actualizadas
        into v_ins
        from ins;

        v_nuevas := v_nuevas + coalesce(v_ins.nuevas, 0)::int;
        v_actualizadas := v_actualizadas + coalesce(v_ins.actualizadas, 0)::int;
    end loop;

    return jsonb_build_object(
        'ok', true,
        'nuevas', v_nuevas,
        'actualizadas', v_actualizadas,
        'descartadas', v_descartadas,
        'total_procesadas', v_nuevas + v_actualizadas
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.importar_ventas_historicas(p_rows jsonb, p_sucursal_id uuid DEFAULT NULL::uuid, p_sucursal_nombre text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
    v_sucursal uuid;
    v_sucursal_nombre text;
    v_row jsonb;
    v_numero text;
    v_total numeric;
    v_insertadas int := 0;
    v_duplicadas int := 0;
    v_descartadas int := 0;
begin
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
        return jsonb_build_object('ok', false, 'error', 'Debes enviar un array JSON');
    end if;

    v_sucursal := coalesce(p_sucursal_id, v_casa);
    v_sucursal_nombre := nullif(coalesce(p_sucursal_nombre, ''), '');
    if v_sucursal_nombre is null then
        select coalesce(nombre, 'Casa Matriz') into v_sucursal_nombre
        from sucursales where id = v_sucursal;
        v_sucursal_nombre := coalesce(v_sucursal_nombre, 'Casa Matriz');
    end if;

    for v_row in select value from jsonb_array_elements(p_rows)
    loop
        v_numero := trim(coalesce(v_row->>'numero', ''));
        v_total := greatest(coalesce(numero_valido(v_row->>'total'), 0), 0);
        if v_numero = '' or v_total = 0 then
            v_descartadas := v_descartadas + 1;
            continue;
        end if;

        if exists (select 1 from ventas where numero = v_numero) then
            v_duplicadas := v_duplicadas + 1;
            continue;
        end if;

        insert into ventas
            (numero, cliente_nombre, cliente_rif, subtotal, iva, total_usd,
             tasa_bcv, total_bs, metodo_pago, estado, sucursal_id, sucursal_nombre,
             created_at)
        values
            (v_numero,
             case when coalesce(trim(coalesce(v_row->>'cliente', '')), '') = ''
                  then 'Consumidor Final'
                  else nullif(trim(coalesce(v_row->>'cliente', '')), '')
             end,
             null,
             v_total,
             0,
             v_total,
             0,
             0,
             'contado',
             'completada',
             v_sucursal,
             v_sucursal_nombre,
             coalesce(fecha_valida(v_row->>'fecha'), current_date)::timestamptz);

        v_insertadas := v_insertadas + 1;
    end loop;

    return jsonb_build_object(
        'ok', true,
        'insertadas', v_insertadas,
        'duplicadas', v_duplicadas,
        'descartadas', v_descartadas
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inventario_eliminar_todo(p_confirmacion text, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid; v_nom text;
    v_suf text := to_char(now() at time zone 'America/Caracas', 'YYYYMMDD_HH24MISS');
    v_pre text := current_schema();          -- public o el esquema de la empresa
    v_tab_p text; v_tab_s text;
    v_p int := 0; v_s int := 0;
begin
    if coalesce(upper(trim(p_confirmacion)), '') <> 'ELIMINAR' then
        raise exception 'Escribe ELIMINAR para confirmar.';
    end if;
    v_uid := refrimar_sesion_uid(0);
    if v_uid is null or not refrimar_es_admin(v_uid) then
        raise exception 'Solo el administrador puede eliminar todo el inventario.';
    end if;
    select nombre into v_nom from usuarios where id = v_uid;

    -- Respaldo (una tabla por cada vez que se usa el botón)
    v_tab_p := v_pre || '_productos_' || v_suf;
    execute format('create table respaldo_inventario.%I as table productos', v_tab_p);
    if to_regclass('sucursal_stock') is not null then
        v_tab_s := v_pre || '_sucursal_stock_' || v_suf;
        execute format('create table respaldo_inventario.%I as table sucursal_stock', v_tab_s);
        delete from sucursal_stock where true;
        get diagnostics v_s = row_count;
    end if;

    delete from productos where true;
    get diagnostics v_p = row_count;

    if to_regclass('auditoria') is not null then
        insert into auditoria (tabla, accion, registro, usuario_id, usuario_nombre, cambios)
        values ('productos', 'borrar', 'TODO EL INVENTARIO', v_uid, coalesce(v_nom, p_usuario),
                jsonb_build_object('productos', v_p, 'existencias_tiendas', v_s, 'respaldo', 'respaldo_inventario.' || v_tab_p));
    end if;

    return jsonb_build_object('ok', true, 'productos', v_p, 'existencias', v_s, 'respaldo', v_tab_p);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.invitacion_aceptar(p_token text, p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_email text; v_avatar text; u record; i record;
begin
    begin
        v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
        v_avatar := coalesce(auth.jwt() -> 'user_metadata' ->> 'avatar_url', auth.jwt() -> 'user_metadata' ->> 'picture');
    exception when others then v_email := '';
    end;
    if v_email = '' then return jsonb_build_object('success', false, 'error', 'Primero entra con tu cuenta de Google'); end if;
    if p_pin is null or length(p_pin) < 32 then return jsonb_build_object('success', false, 'error', 'Crea un PIN de 4 dígitos'); end if;

    if nullif(p_token, '') is not null then
        select * into i from invitaciones where token = p_token;
        if not found or i.cancelada or i.usada_at is not null or i.expira_at < now() then
            return jsonb_build_object('success', false, 'error', 'La invitación ya no es válida. Pídele una nueva al administrador.');
        end if;
        if lower(i.email) <> v_email then
            return jsonb_build_object('success', false, 'error', 'Esta invitación es para ' || i.email || ' y entraste con ' || v_email || '. Entra con la cuenta correcta.');
        end if;
        select * into u from usuarios where id = i.usuario_id for update;
    else
        select * into u from usuarios where lower(email) = v_email and estado = 'pendiente' for update;
        if not found then return jsonb_build_object('success', false, 'error', 'No hay una invitación pendiente para ' || v_email); end if;
    end if;
    if u.estado not in ('pendiente') then
        return jsonb_build_object('success', false, 'error', 'Esta invitación ya no está pendiente.');
    end if;

    update usuarios set pin = p_pin, activo = true, estado = 'activo', aceptado_at = now(),
        avatar_url = coalesce(v_avatar, avatar_url)
    where id = u.id;
    update invitaciones set usada_at = now() where usuario_id = u.id and usada_at is null and not cancelada;
    return usuario_sesion_json(u.id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.invitacion_enlace(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_estado text;
begin
    select estado into v_estado from usuarios where id = p_id;
    if not found then raise exception 'Colaborador no encontrado'; end if;
    if v_estado <> 'pendiente' then raise exception 'Este colaborador no tiene una invitación pendiente'; end if;
    return jsonb_build_object('ok', true, 'token', invitacion_vigente(p_id, null));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.invitacion_info(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i record; u record; v_empresa text; v_tiendas text[];
begin
    select * into i from invitaciones where token = p_token;
    if not found then return jsonb_build_object('ok', false, 'error', 'Esta invitación no existe.'); end if;
    select * into u from usuarios where id = i.usuario_id;
    if i.usada_at is not null or u.estado = 'activo' then return jsonb_build_object('ok', false, 'usada', true, 'error', 'Esta invitación ya fue aceptada. Entra con tu cuenta de Google.'); end if;
    if i.cancelada or u.estado = 'cancelado' then return jsonb_build_object('ok', false, 'error', 'Esta invitación fue cancelada. Pídele una nueva al administrador.'); end if;
    if i.expira_at < now() then return jsonb_build_object('ok', false, 'error', 'Esta invitación venció. Pídele una nueva al administrador.'); end if;
    select coalesce(nullif(trim(nombre_negocio), ''), 'Comercial Refrimar') into v_empresa from configuracion limit 1;
    select array_agg(n order by n) into v_tiendas from (
        select case when x = '00000000-0000-0000-0000-000000000001'::uuid then 'Casa Matriz' else s.nombre end n
        from unnest(u.sucursales) x left join sucursales s on s.id = x) t;
    return jsonb_build_object('ok', true, 'nombre', u.nombres, 'nombre_completo', u.nombre, 'email', i.email,
        'rol', u.rol, 'empresa', coalesce(v_empresa, 'Comercial Refrimar'), 'tiendas', coalesce(to_jsonb(v_tiendas), '[]'::jsonb));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.invitacion_vigente(p_usuario uuid, p_creada_por text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_token text; v_email text;
begin
    select email into v_email from usuarios where id = p_usuario;
    if v_email is null then raise exception 'El colaborador no tiene correo'; end if;
    select token into v_token from invitaciones
    where usuario_id = p_usuario and not cancelada and usada_at is null and expira_at > now()
      and lower(email) = lower(v_email)
    order by created_at desc limit 1;
    if v_token is null then
        update invitaciones set cancelada = true where usuario_id = p_usuario and usada_at is null;
        insert into invitaciones (usuario_id, email, creada_por) values (p_usuario, lower(v_email), p_creada_por)
        returning token into v_token;
    end if;
    return v_token;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.kardex_ajuste(p_producto_codigo text, p_tipo text, p_cantidad numeric, p_costo_unitario numeric, p_concepto text, p_sucursal_id uuid, p_usuario text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
    v_desc text;
    v_stock_actual numeric;
    v_costo_actual numeric;
    v_nuevo_stock numeric;
    v_nuevo_costo numeric;
    v_kardex_tipo text;
begin
    if p_producto_codigo is null or p_producto_codigo = '' then
        raise exception 'Debe indicar un producto';
    end if;
    if p_cantidad is null or p_cantidad <= 0 then
        raise exception 'La cantidad debe ser mayor a cero';
    end if;
    if p_tipo not in ('entrada', 'salida') then
        raise exception 'Tipo debe ser entrada o salida';
    end if;

    select descripcion, coalesce(costo, 0) into v_desc, v_costo_actual
    from productos where codigo = p_producto_codigo;

    if not found then
        raise exception 'Producto % no existe', p_producto_codigo;
    end if;

    v_kardex_tipo := case when p_tipo = 'entrada' then 'entrada_ajuste' else 'salida_ajuste' end;

    -- Stock según ubicación
    if p_sucursal_id is null or p_sucursal_id = v_casa then
        select coalesce(stock, 0) into v_stock_actual from productos where codigo = p_producto_codigo;
        if p_tipo = 'salida' and v_stock_actual < p_cantidad then
            raise exception 'Stock insuficiente (actual: %)', v_stock_actual;
        end if;
        v_nuevo_stock := case when p_tipo = 'entrada' then v_stock_actual + p_cantidad else v_stock_actual - p_cantidad end;
        update productos set stock = v_nuevo_stock where codigo = p_producto_codigo;
    else
        select coalesce(stock, 0) into v_stock_actual from sucursal_stock where sucursal_id = p_sucursal_id and producto_codigo = p_producto_codigo;
        if p_tipo = 'salida' and v_stock_actual < p_cantidad then
            raise exception 'Stock insuficiente (actual: %)', v_stock_actual;
        end if;
        v_nuevo_stock := case when p_tipo = 'entrada' then v_stock_actual + p_cantidad else v_stock_actual - p_cantidad end;
        insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
        values (p_sucursal_id, p_producto_codigo, coalesce(v_desc, p_producto_codigo), v_nuevo_stock)
        on conflict (sucursal_id, producto_codigo)
        do update set stock = excluded.stock, producto_descripcion = excluded.producto_descripcion, updated_at = now();
    end if;

    -- Costo promedio ponderado en entrada con costo informado
    if p_tipo = 'entrada' and coalesce(p_costo_unitario, 0) > 0 then
        select coalesce(stock, 0) into v_stock_actual from productos where codigo = p_producto_codigo;
        if v_stock_actual > 0 then
            v_nuevo_costo := (v_stock_actual * v_costo_actual + p_cantidad * p_costo_unitario) / (v_stock_actual + p_cantidad);
            update productos set costo = v_nuevo_costo where codigo = p_producto_codigo;
        else
            v_nuevo_costo := p_costo_unitario;
            update productos set costo = p_costo_unitario where codigo = p_producto_codigo;
        end if;
    else
        select coalesce(costo, 0) into v_nuevo_costo from productos where codigo = p_producto_codigo;
    end if;

    insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total, saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
    values (p_producto_codigo, coalesce(v_desc, p_producto_codigo), current_date, v_kardex_tipo,
            case when p_tipo = 'entrada' then p_cantidad else -p_cantidad end,
            coalesce(p_costo_unitario, 0),
            case when p_tipo = 'entrada' then p_cantidad * coalesce(p_costo_unitario, 0) else p_cantidad * v_costo_actual end,
            v_nuevo_stock, v_nuevo_costo,
            coalesce(p_concepto, v_kardex_tipo), p_usuario, p_sucursal_id);

    return jsonb_build_object('ok', true, 'stock', v_nuevo_stock, 'costo_promedio', v_nuevo_costo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.kit_guardar(p_kit text, p_componentes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c jsonb; v_cod text; v_cant numeric; n int := 0;
begin
    if not exists (select 1 from productos where codigo = p_kit) then raise exception 'Producto % no existe', p_kit; end if;
    delete from producto_componentes where kit_codigo = p_kit;
    for c in select value from jsonb_array_elements(coalesce(p_componentes, '[]'::jsonb)) loop
        v_cod := nullif(trim(coalesce(c->>'codigo', '')), '');
        v_cant := coalesce(nullif(c->>'cantidad', '')::numeric, 0);
        if v_cod is null or v_cant <= 0 then raise exception 'Componente o cantidad inválida'; end if;
        if v_cod = p_kit then raise exception 'Un combo no puede contenerse a sí mismo'; end if;
        if not exists (select 1 from productos where codigo = v_cod) then raise exception 'El componente % no existe', v_cod; end if;
        if exists (select 1 from productos where codigo = v_cod and (es_kit or coalesce(tipo_producto, 'fisico') = 'servicio')) then
            raise exception 'El componente % es un combo o un servicio: usa productos físicos', v_cod;
        end if;
        insert into producto_componentes (kit_codigo, componente_codigo, cantidad) values (p_kit, v_cod, v_cant)
        on conflict (kit_codigo, componente_codigo) do update set cantidad = producto_componentes.cantidad + excluded.cantidad;
        n := n + 1;
    end loop;
    update productos set es_kit = n > 0 where codigo = p_kit;
    -- El combo no lleva inventario propio (como los servicios): siempre "hay"; lo que manda es el stock de los componentes
    if n > 0 then perform servicio_stock_asegurar(p_kit); end if;
    return jsonb_build_object('ok', true, 'componentes', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.kit_mover_componentes(p_kit text, p_cantidad numeric, p_sucursal uuid, p_signo integer, p_ref text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; v_q numeric; v_stock numeric; v_suc uuid := case when p_sucursal = '00000000-0000-0000-0000-000000000001' then null else p_sucursal end;
begin
    for c in select pc.componente_codigo, pc.cantidad, p.descripcion, coalesce(p.costo, 0) as costo
             from producto_componentes pc join productos p on p.codigo = pc.componente_codigo where pc.kit_codigo = p_kit loop
        v_q := c.cantidad * p_cantidad;
        if v_suc is null then
            select coalesce(stock, 0) into v_stock from productos where codigo = c.componente_codigo for update;
            if p_signo < 0 and v_stock < v_q then raise exception 'Stock insuficiente de "%" (componente del combo %): disponible %', c.descripcion, p_kit, v_stock; end if;
            update productos set stock = coalesce(stock, 0) + p_signo * v_q where codigo = c.componente_codigo returning stock into v_stock;
        else
            select stock into v_stock from sucursal_stock where sucursal_id = v_suc and producto_codigo = c.componente_codigo for update;
            if p_signo < 0 and coalesce(v_stock, 0) < v_q then raise exception 'Stock insuficiente de "%" (componente del combo %) en la tienda: disponible %', c.descripcion, p_kit, coalesce(v_stock, 0); end if;
            insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock) values (v_suc, c.componente_codigo, c.descripcion, p_signo * v_q)
            on conflict (sucursal_id, producto_codigo) do update set stock = sucursal_stock.stock + p_signo * v_q, updated_at = now()
            returning stock into v_stock;
        end if;
        insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total, saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
        values (c.componente_codigo, c.descripcion, current_date, case when p_signo < 0 then 'salida_venta' else 'entrada_devolucion' end, p_signo * v_q,
                c.costo, v_q * c.costo, v_stock, c.costo, p_ref || ' (combo ' || p_kit || ')', coalesce(p_usuario, 'Sistema'), v_suc);
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.kit_trg_anulacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d record;
begin
    if new.estado = 'anulada' and coalesce(old.estado, '') <> 'anulada' then
        for d in select dv.producto_codigo, dv.cantidad from detalle_venta dv join productos p on p.codigo = dv.producto_codigo and p.es_kit where dv.venta_id = new.id loop
            perform kit_mover_componentes(d.producto_codigo, d.cantidad, new.sucursal_id, 1, 'Anulación ' || coalesce(new.numero, ''), null);
        end loop;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.kit_trg_nc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
        declare n record;
        begin
            if not exists (select 1 from productos where codigo = new.producto_codigo and es_kit) then return new; end if;
            select numero, sucursal_id, usuario_nombre into n from notas_credito where id = new.nota_id;
            perform kit_mover_componentes(new.producto_codigo, new.cantidad, n.sucursal_id, 1, 'Nota de crédito ' || coalesce(n.numero, ''), n.usuario_nombre);
            return new;
        end;
        $function$
;

CREATE OR REPLACE FUNCTION public.kit_trg_venta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v record;
begin
    if not exists (select 1 from productos where codigo = new.producto_codigo and es_kit) then return new; end if;
    select numero, sucursal_id, usuario_nombre into v from ventas where id = new.venta_id;
    perform kit_mover_componentes(new.producto_codigo, new.cantidad, v.sucursal_id, -1, 'Venta ' || coalesce(v.numero, ''), v.usuario_nombre);
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.login_google()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_email text;
    v_avatar text;
    u record;
begin
    begin
        v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
        v_avatar := coalesce(auth.jwt() -> 'user_metadata' ->> 'avatar_url', auth.jwt() -> 'user_metadata' ->> 'picture');
    exception when others then v_email := '';
    end;
    if v_email = '' then return jsonb_build_object('success', false, 'error', 'No hay una sesión de Google activa'); end if;
    select * into u from usuarios where lower(email) = v_email limit 1;
    if not found then
        return jsonb_build_object('success', false, 'error', 'El correo ' || v_email || ' no está registrado. Pídele al administrador que te invite en Configuración → Gestión de equipo.');
    end if;
    if u.estado = 'pendiente' then
        return jsonb_build_object('success', false, 'pendiente', true, 'nombre', u.nombres, 'email', v_email,
            'error', 'Tienes una invitación pendiente: crea tu PIN para activarla.');
    end if;
    if u.estado = 'cancelado' then
        return jsonb_build_object('success', false, 'error', 'Tu invitación fue cancelada. Habla con el administrador.');
    end if;
    if not coalesce(u.activo, false) then
        return jsonb_build_object('success', false, 'error', 'Tu usuario está inactivo. Habla con el administrador.');
    end if;
    if v_avatar is not null then update usuarios set avatar_url = v_avatar where id = u.id; end if;
    return usuario_sesion_json(u.id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.login_usuario(nombre_input text, pin_input text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  usuario_record record;
BEGIN
  SELECT * INTO usuario_record FROM usuarios 
  WHERE nombre = nombre_input AND pin = pin_input AND activo = true;
  
  IF usuario_record.id IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Credenciales inválidas');
  END IF;
  
  RETURN json_build_object(
    'success', true,
    'id', usuario_record.id,
    'nombre', usuario_record.nombre,
    'rol', usuario_record.rol
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.lote_eliminar(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    delete from producto_lotes where id = p_id;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.lote_guardar_base(p_codigo text, p_lote text, p_vencimiento date, p_cantidad numeric, p_sucursal uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_suc uuid := case when p_sucursal = '00000000-0000-0000-0000-000000000001' then null else p_sucursal end; v_id uuid;
begin
    if not exists (select 1 from productos where codigo = p_codigo) then raise exception 'El producto % no existe', p_codigo; end if;
    if nullif(trim(coalesce(p_lote, '')), '') is null then raise exception 'Escribe el número de lote'; end if;
    if coalesce(p_cantidad, 0) < 0 then raise exception 'La cantidad no puede ser negativa'; end if;
    select id into v_id from producto_lotes
    where producto_codigo = p_codigo and coalesce(sucursal_id, '00000000-0000-0000-0000-000000000001'::uuid) = coalesce(v_suc, '00000000-0000-0000-0000-000000000001'::uuid)
      and lote = trim(p_lote);
    if v_id is null then
        insert into producto_lotes (producto_codigo, sucursal_id, lote, vencimiento, cantidad)
        values (p_codigo, v_suc, trim(p_lote), p_vencimiento, coalesce(p_cantidad, 0)) returning id into v_id;
    else
        update producto_lotes set vencimiento = p_vencimiento, cantidad = coalesce(p_cantidad, 0), actualizado_at = now() where id = v_id;
    end if;
    return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.lotes_importar_base(p_rows jsonb, p_sucursal uuid DEFAULT NULL::uuid, p_reemplazar boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; n int := 0; v_suc uuid := case when p_sucursal = '00000000-0000-0000-0000-000000000001' then null else p_sucursal end;
begin
    if jsonb_typeof(p_rows) <> 'array' then raise exception 'Filas inválidas'; end if;
    if p_reemplazar then
        delete from producto_lotes l
        where coalesce(l.sucursal_id, '00000000-0000-0000-0000-000000000001'::uuid) = coalesce(v_suc, '00000000-0000-0000-0000-000000000001'::uuid)
          and l.producto_codigo in (select distinct x ->> 'codigo' from jsonb_array_elements(p_rows) x);
    end if;
    for r in select value from jsonb_array_elements(p_rows) loop
        if nullif(trim(coalesce(r ->> 'lote', '')), '') is null or not exists (select 1 from productos where codigo = r ->> 'codigo') then continue; end if;
        perform lote_guardar(r ->> 'codigo', r ->> 'lote', nullif(r ->> 'vencimiento', '')::date, coalesce(nullif(r ->> 'cantidad', '')::numeric, 0), p_sucursal);
        n := n + 1;
    end loop;
    return jsonb_build_object('ok', true, 'lotes', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.nota_credito_registrar_base(p_venta_id uuid, p_items jsonb, p_motivo text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_venta record;
    v_item jsonb;
    v_codigo text;
    v_cant numeric;
    v_vendida numeric;
    v_total_linea_venta numeric;
    v_devuelta numeric;
    v_desc text;
    v_precio numeric;
    v_total numeric := 0;
    v_total_bs numeric;
    v_ratio numeric;
    v_nota_id uuid;
    v_numero text;
    v_metodo text;
    v_pendiente numeric;
    v_abono numeric;
begin
    select * into v_venta from ventas where id = p_venta_id for update;
    if not found then raise exception 'Factura no encontrada'; end if;
    if v_venta.estado <> 'completada' then raise exception 'Solo se puede hacer nota de crédito a facturas completadas'; end if;
    if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
        raise exception 'Selecciona al menos un producto a devolver';
    end if;

    v_numero := 'NC-' || lpad(nextval('seq_nota_credito')::text, 6, '0');
    v_metodo := case when v_venta.metodo_pago = 'credito' then 'rebaja_deuda'
                     when v_venta.metodo_pago = 'mixto' then 'efectivo'
                     else coalesce(v_venta.metodo_pago, 'efectivo') end;

    insert into notas_credito (numero, venta_id, venta_numero, cliente_nombre, cliente_rif, motivo,
        metodo_reembolso, sucursal_id, sucursal_nombre, usuario_nombre)
    values (v_numero, v_venta.id, v_venta.numero, v_venta.cliente_nombre, v_venta.cliente_rif,
        nullif(trim(coalesce(p_motivo, '')), ''), v_metodo, v_venta.sucursal_id, v_venta.sucursal_nombre,
        coalesce(p_usuario, 'Sistema'))
    returning id into v_nota_id;

    for v_item in select value from jsonb_array_elements(p_items) loop
        v_codigo := coalesce(v_item->>'codigo', '');
        v_cant := coalesce((v_item->>'cantidad')::numeric, 0);
        if v_codigo = '' or v_cant <= 0 then continue; end if;

        select coalesce(sum(cantidad), 0), coalesce(sum(total), 0), max(descripcion)
        into v_vendida, v_total_linea_venta, v_desc
        from detalle_venta where venta_id = v_venta.id and producto_codigo = v_codigo;

        if v_vendida <= 0 then raise exception 'El producto % no está en la factura', v_codigo; end if;

        select coalesce(sum(d.cantidad), 0) into v_devuelta
        from notas_credito_detalle d join notas_credito n on n.id = d.nota_id
        where n.venta_id = v_venta.id and d.producto_codigo = v_codigo and n.id <> v_nota_id;

        if v_cant > v_vendida - v_devuelta + 0.0005 then
            raise exception 'No puedes devolver % de "%": vendidos %, ya devueltos %', v_cant, coalesce(v_desc, v_codigo), v_vendida, v_devuelta;
        end if;

        v_precio := round(v_total_linea_venta / v_vendida, 4);
        insert into notas_credito_detalle (nota_id, producto_codigo, descripcion, cantidad, precio_unitario, total)
        values (v_nota_id, v_codigo, v_desc, v_cant, v_precio, round(v_precio * v_cant, 2));
        v_total := v_total + round(v_precio * v_cant, 2);

        -- El producto vuelve al stock de la sucursal donde se vendió
        perform stock_mover(v_codigo, v_venta.sucursal_id, v_cant);
        insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total,
            saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
        values (v_codigo, coalesce(v_desc, v_codigo), current_date, 'entrada_devolucion', v_cant, 0, 0,
            stock_en(v_codigo, v_venta.sucursal_id), 0, v_numero || ' (' || coalesce(v_venta.numero, '') || ')',
            coalesce(p_usuario, 'Sistema'), v_venta.sucursal_id);
    end loop;

    if v_total <= 0 then raise exception 'La nota de crédito no tiene productos'; end if;

    v_ratio := case when coalesce(v_venta.total_usd, 0) > 0 then coalesce(v_venta.total_bs, 0) / v_venta.total_usd
                    else coalesce(v_venta.tasa_bcv, 0) end;
    v_total_bs := round(v_total * v_ratio, 2);

    update notas_credito set total_usd = v_total, total_bs = v_total_bs where id = v_nota_id;
    update ventas set total_devuelto_usd = coalesce(total_devuelto_usd, 0) + v_total where id = v_venta.id;

    if v_venta.metodo_pago = 'credito' then
        -- Rebaja la deuda: se registra como abono "nota_credito"
        v_pendiente := greatest(coalesce(v_venta.total_usd, 0) - coalesce(v_venta.monto_abonado, 0), 0);
        v_abono := least(v_total, v_pendiente);
        if v_abono > 0 then
            insert into abonos_ventas (venta_id, monto, fecha, metodo, usuario_nombre, sucursal_id, notas)
            values (v_venta.id, v_abono, current_date, 'nota_credito', coalesce(p_usuario, 'Sistema'), v_venta.sucursal_id, v_numero);
            update ventas set monto_abonado = coalesce(monto_abonado, 0) + v_abono where id = v_venta.id;
            if coalesce(v_venta.cliente_rif, '') <> '' then
                update clientes set saldo_pendiente = greatest(coalesce(saldo_pendiente, 0) - v_abono, 0) where rif = v_venta.cliente_rif;
            end if;
        end if;
    else
        -- Reembolso: egreso de caja con el mismo método de pago
        insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre, metodo_pago)
        values ('egreso', 'Nota de crédito ' || v_numero || ' (factura ' || coalesce(v_venta.numero, '') || ')',
            v_total, v_total_bs, v_venta.sucursal_id, coalesce(p_usuario, 'Sistema'), v_metodo);
    end if;

    return jsonb_build_object('ok', true, 'nota_id', v_nota_id, 'numero', v_numero, 'total_usd', v_total, 'total_bs', v_total_bs);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.nota_debito_anular(p_numero text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update notas_debito set estado = 'anulada' where numero = p_numero and estado = 'emitida';
    if not found then raise exception 'Nota de débito no encontrada o ya anulada'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.nota_debito_crear(p_factura text, p_motivo text, p_monto_usd numeric, p_iva_pct numeric DEFAULT 16, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- refrimar_envuelta
begin
    if p_monto_usd is not null and (p_monto_usd < 0 or p_monto_usd > 1000000000) then raise exception 'El valor de monto usd no es válido'; end if;
    return nota_debito_crear_base(p_factura => p_factura, p_motivo => p_motivo, p_monto_usd => p_monto_usd, p_iva_pct => p_iva_pct, p_usuario => p_usuario);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.nota_debito_crear_base(p_factura text, p_motivo text, p_monto_usd numeric, p_iva_pct numeric DEFAULT 16, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v record; v_num text; v_tasa numeric; v_sub numeric; v_iva numeric; nd notas_debito;
begin
    select * into v from ventas where numero = p_factura;
    if not found then raise exception 'No existe la factura %', p_factura; end if;
    if v.estado = 'anulada' then raise exception 'La factura % está anulada', p_factura; end if;
    if nullif(trim(coalesce(p_motivo, '')), '') is null then raise exception 'Escribe el motivo de la nota de débito'; end if;
    if coalesce(p_monto_usd, 0) <= 0 then raise exception 'El monto debe ser mayor que cero'; end if;
    if coalesce(p_iva_pct, 16) not in (0, 8, 16, 31) then raise exception 'Alícuota inválida'; end if;
    select coalesce(nullif(tasa_bcv_manual, 0), v.tasa_bcv) into v_tasa from configuracion limit 1;
    v_sub := round(p_monto_usd, 2);
    v_iva := round(v_sub * coalesce(p_iva_pct, 16) / 100, 2);
    v_num := 'ND-' || lpad(nextval('seq_nota_debito')::text, 6, '0');
    insert into notas_debito (numero, venta_id, factura_numero, factura_fecha, factura_control, cliente_nombre, cliente_rif, motivo, iva_pct,
        subtotal_usd, iva_usd, total_usd, tasa_bcv, total_bs, sucursal_id, usuario_nombre)
    values (v_num, v.id, v.numero, v.created_at, v.numero_control, v.cliente_nombre, v.cliente_rif, trim(p_motivo), coalesce(p_iva_pct, 16),
        v_sub, v_iva, v_sub + v_iva, v_tasa, round((v_sub + v_iva) * coalesce(v_tasa, 0), 2), v.sucursal_id, coalesce(p_usuario, 'Sistema'))
    returning * into nd;
    return to_jsonb(nd);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.numero_valido(p_val text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    v text;
begin
    if p_val is null then return null; end if;
    v := trim(p_val);
    if v = '' or lower(v) in ('null', 'n/a', '-') then return null; end if;
    begin
        return v::numeric;
    exception when others then
        -- formato venezolano con coma decimal: "1.234,56" -> 1234.56
        v := regexp_replace(v, '\s', '', 'g');
        v := replace(v, '.', '');
        v := replace(v, ',', '.');
        v := regexp_replace(v, '[^0-9.\-]', '', 'g');
        begin
            return v::numeric;
        exception when others then
            return null;
        end;
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.oc_estado(p_id uuid, p_estado text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_estado text; v_recibido numeric;
begin
    if p_estado not in ('ordenada', 'cerrada', 'cancelada') then raise exception 'Estado inválido'; end if;
    select estado into v_estado from ordenes_compra where id = p_id for update;
    if not found then raise exception 'Orden no encontrada'; end if;
    select coalesce(sum(cantidad_recibida), 0) into v_recibido from compra_detalles where compra_id = p_id;
    if p_estado = 'ordenada' and v_estado <> 'borrador' then raise exception 'Solo un borrador puede pasar a ordenada'; end if;
    if p_estado = 'cancelada' and v_recibido > 0 then raise exception 'No se puede cancelar: ya se recibieron productos. Ciérrala.'; end if;
    if v_estado in ('cerrada', 'cancelada') then raise exception 'La orden ya está %', v_estado; end if;
    if p_estado = 'cerrada' and v_estado = 'recibida' then raise exception 'La orden ya está recibida completa'; end if;
    update ordenes_compra set estado = p_estado where id = p_id;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.oc_guardar(p_id uuid, p_proveedor_id uuid, p_proveedor_nombre text, p_fecha_estimada date, p_notas text, p_sucursal_id uuid, p_sucursal_nombre text, p_usuario text, p_estado text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid := p_id;
    v_numero text;
    v_estado_actual text;
    v_item jsonb;
    v_codigo text; v_cant numeric; v_costo numeric; v_desc text;
    v_total numeric := 0;
begin
    if p_estado not in ('borrador', 'ordenada') then raise exception 'Estado inválido'; end if;
    if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
        raise exception 'Agrega al menos un producto a la orden';
    end if;

    if v_id is null then
        v_numero := 'ODC-' || lpad(nextval('seq_odc')::text, 8, '0');
        insert into ordenes_compra (numero, proveedor_id, proveedor_nombre, fecha, fecha_estimada, notas, usuario_nombre,
            sucursal_id, sucursal_nombre, estado)
        values (v_numero, p_proveedor_id, p_proveedor_nombre, current_date, p_fecha_estimada, p_notas, p_usuario,
            p_sucursal_id, coalesce(p_sucursal_nombre, 'Casa Matriz'), p_estado)
        returning id into v_id;
    else
        select estado, numero into v_estado_actual, v_numero from ordenes_compra where id = v_id for update;
        if not found then raise exception 'Orden no encontrada'; end if;
        if v_estado_actual not in ('borrador', 'ordenada') then raise exception 'Solo se pueden editar órdenes en borrador u ordenadas'; end if;
        update ordenes_compra set proveedor_id = p_proveedor_id, proveedor_nombre = p_proveedor_nombre,
            fecha_estimada = p_fecha_estimada, notas = p_notas, sucursal_id = p_sucursal_id,
            sucursal_nombre = coalesce(p_sucursal_nombre, 'Casa Matriz'), estado = p_estado
        where id = v_id;
        delete from compra_detalles where compra_id = v_id;
    end if;

    for v_item in select value from jsonb_array_elements(p_items) loop
        v_codigo := coalesce(v_item->>'codigo', '');
        v_cant := coalesce((v_item->>'cantidad')::numeric, 0);
        v_costo := coalesce((v_item->>'costo_unitario')::numeric, 0);
        if v_codigo = '' or v_cant <= 0 then raise exception 'Producto o cantidad inválida en la orden'; end if;
        select descripcion into v_desc from productos where codigo = v_codigo;
        if not found then raise exception 'Producto % no existe', v_codigo; end if;
        insert into compra_detalles (compra_id, producto_codigo, descripcion, cantidad, costo_unitario, subtotal, cantidad_recibida)
        values (v_id, v_codigo, v_desc, v_cant, v_costo, round(v_cant * v_costo, 2), 0);
        v_total := v_total + round(v_cant * v_costo, 2);
    end loop;
    update ordenes_compra set subtotal = v_total where id = v_id;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero, 'total', v_total);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.oc_recibir(p_id uuid, p_items jsonb, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_oc record;
    v_item jsonb;
    v_det record;
    v_cant numeric;
    v_stock_global numeric;
    v_costo_actual numeric;
    v_nuevo_costo numeric;
    v_nuevo_stock numeric;
    v_pend numeric;
    v_recibidos int := 0;
begin
    select * into v_oc from ordenes_compra where id = p_id for update;
    if not found then raise exception 'Orden no encontrada'; end if;
    if v_oc.estado not in ('ordenada', 'parcial', 'borrador') then
        raise exception 'Esta orden está % y no puede recibir productos', v_oc.estado;
    end if;

    for v_item in select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
        v_cant := coalesce((v_item->>'cantidad')::numeric, 0);
        if v_cant <= 0 then continue; end if;
        select * into v_det from compra_detalles where compra_id = p_id and producto_codigo = v_item->>'codigo' for update;
        if not found then raise exception 'El producto % no está en la orden', v_item->>'codigo'; end if;
        v_pend := v_det.cantidad - v_det.cantidad_recibida;
        if v_cant > v_pend + 0.0005 then
            raise exception 'De "%" faltan por recibir % (intentaste %)', coalesce(v_det.descripcion, v_det.producto_codigo), v_pend, v_cant;
        end if;

        -- Costo promedio ponderado global (igual que compra_registrar)
        select coalesce(stock, 0), coalesce(costo, 0) into v_stock_global, v_costo_actual from productos where codigo = v_det.producto_codigo;
        v_nuevo_stock := stock_mover(v_det.producto_codigo, v_oc.sucursal_id, v_cant);
        if v_det.costo_unitario > 0 then
            if v_stock_global + v_cant > 0 then
                v_nuevo_costo := (v_stock_global * v_costo_actual + v_cant * v_det.costo_unitario) / (v_stock_global + v_cant);
            else
                v_nuevo_costo := v_det.costo_unitario;
            end if;
            update productos set costo = round(v_nuevo_costo, 4) where codigo = v_det.producto_codigo;
            if v_oc.sucursal_id is not null and v_oc.sucursal_id <> '00000000-0000-0000-0000-000000000001' then
                update sucursal_stock set costo = v_det.costo_unitario where sucursal_id = v_oc.sucursal_id and producto_codigo = v_det.producto_codigo;
            end if;
        else
            v_nuevo_costo := v_costo_actual;
        end if;

        update compra_detalles set cantidad_recibida = cantidad_recibida + v_cant where id = v_det.id;
        insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total,
            saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
        values (v_det.producto_codigo, coalesce(v_det.descripcion, v_det.producto_codigo), current_date, 'entrada_compra', v_cant,
            v_det.costo_unitario, round(v_cant * v_det.costo_unitario, 2), v_nuevo_stock, coalesce(v_nuevo_costo, 0),
            v_oc.numero, coalesce(p_usuario, 'Sistema'), v_oc.sucursal_id);
        v_recibidos := v_recibidos + 1;
    end loop;

    if v_recibidos = 0 then raise exception 'Indica cuántas unidades recibes de al menos un producto'; end if;

    update ordenes_compra set
        estado = case when exists (select 1 from compra_detalles where compra_id = p_id and cantidad_recibida < cantidad) then 'parcial' else 'recibida' end,
        recibida_at = now()
    where id = p_id;
    return jsonb_build_object('ok', true, 'estado', (select estado from ordenes_compra where id = p_id));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pago_movil_registrar_base(p_banco text, p_remitente text, p_monto numeric, p_sucursal_id uuid, p_referencia text DEFAULT NULL::text, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_banco is null or trim(p_banco) = '' then
        raise exception 'El banco es obligatorio';
    end if;
    if p_remitente is null or trim(p_remitente) = '' then
        raise exception 'El remitente es obligatorio';
    end if;
    if p_monto is null or p_monto <= 0 then
        raise exception 'El monto debe ser mayor a 0';
    end if;

    insert into pagos_moviles (banco, remitente, monto, referencia,
        sucursal_id, usuario_nombre)
    values (trim(p_banco), trim(p_remitente), p_monto, p_referencia,
        p_sucursal_id, coalesce(p_usuario, 'Sistema'));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_borrador_eliminar(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    delete from pos_borradores where id = p_id;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_borrador_guardar(p_id uuid, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d jsonb := coalesce(p_datos, '{}'::jsonb); v_id uuid := p_id;
begin
    if jsonb_typeof(d->'items') <> 'array' or jsonb_array_length(d->'items') = 0 then raise exception 'El borrador no tiene productos'; end if;
    if v_id is null or not exists (select 1 from pos_borradores where id = v_id) then
        insert into pos_borradores (nombre, sucursal_id, usuario_nombre, terminal, cliente, items, total_usd)
        values (nullif(trim(coalesce(d->>'nombre', '')), ''), nullif(d->>'sucursal_id', '')::uuid, d->>'usuario_nombre', d->>'terminal',
                d->'cliente', d->'items', coalesce((d->>'total_usd')::numeric, 0))
        returning id into v_id;
    else
        update pos_borradores set nombre = nullif(trim(coalesce(d->>'nombre', '')), ''), cliente = d->'cliente', items = d->'items',
            total_usd = coalesce((d->>'total_usd')::numeric, 0), usuario_nombre = coalesce(d->>'usuario_nombre', usuario_nombre), updated_at = now()
        where id = v_id;
    end if;
    return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_facturar(p_venta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    declare r jsonb; v jsonb := coalesce(p_venta, '{}'::jsonb);
    begin
        -- Venta repetida (reintento de la caja sin internet): se devuelve la existente sin revisar de nuevo
        if exists (select 1 from ventas where numero = nullif(trim(coalesce(v->>'numero', '')), '')) then return pos_facturar_base(v); end if;
        r := pos_validar_venta(v);
        if r->>'usuario' is not null then v := jsonb_set(v, '{usuario}', to_jsonb(r->>'usuario')); end if;
        return pos_facturar_base(v);
    end;
    $function$
;

CREATE OR REPLACE FUNCTION public.pos_facturar_base(p_venta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v jsonb := coalesce(p_venta, '{}'::jsonb);
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
    v_numero text := nullif(trim(coalesce(v->>'numero', '')), '');
    v_suc uuid := nullif(v->>'sucursal_id', '')::uuid;
    v_usuario text := coalesce(nullif(v->>'usuario', ''), 'Sistema');
    v_cli_nombre text := coalesce(nullif(trim(coalesce(v->'cliente'->>'nombre', '')), ''), 'Consumidor Final');
    v_cli_rif text := nullif(trim(coalesce(v->'cliente'->>'rif', '')), '');
    v_total numeric := coalesce((v->>'total_usd')::numeric, 0);
    v_total_bs numeric := coalesce((v->>'total_bs')::numeric, 0);
    v_tasa numeric := coalesce((v->>'tasa')::numeric, 0);
    v_id uuid; v_item jsonb; v_cant numeric; v_unidad text; v_stock numeric;
    p jsonb; v_pagado numeric := 0; v_credito numeric := 0; v_vuelto numeric := 0;
    v_metodos text[] := '{}'; v_metodo text; v_saldo numeric; v_limite numeric;
begin
    if v_numero is null then raise exception 'Falta el número de la factura'; end if;
    select id into v_id from ventas where numero = v_numero limit 1;
    if found then return jsonb_build_object('ok', true, 'venta_id', v_id, 'numero', v_numero, 'duplicada', true); end if;
    if jsonb_typeof(v->'items') <> 'array' or jsonb_array_length(v->'items') = 0 then raise exception 'La factura no tiene productos'; end if;
    if jsonb_typeof(v->'pagos') <> 'array' or jsonb_array_length(v->'pagos') = 0 then raise exception 'Agrega al menos un método de pago'; end if;

    for p in select value from jsonb_array_elements(v->'pagos') loop
        if coalesce((p->>'monto_usd')::numeric, 0) <= 0 then raise exception 'Hay un pago sin monto'; end if;
        if p->>'metodo' = 'credito' then v_credito := v_credito + (p->>'monto_usd')::numeric;
        else v_pagado := v_pagado + (p->>'monto_usd')::numeric;
             if not (p->>'metodo' = any(v_metodos)) then v_metodos := v_metodos || (p->>'metodo'); end if;
        end if;
    end loop;
    if jsonb_typeof(v->'vuelto') = 'array' then
        select coalesce(sum((x->>'monto_usd')::numeric), 0) into v_vuelto from jsonb_array_elements(v->'vuelto') x;
    end if;
    if v_pagado - v_vuelto + v_credito < v_total - 0.01 then
        raise exception 'Los pagos (%) no cubren el total de la factura (%)', round(v_pagado - v_vuelto + v_credito, 2), round(v_total, 2);
    end if;
    if v_vuelto > v_pagado + 0.01 then raise exception 'El vuelto no puede ser mayor a lo recibido'; end if;
    v_metodo := case when v_credito > 0 then 'credito' when array_length(v_metodos, 1) = 1 then v_metodos[1] else 'mixto' end;

    if v_credito > 0 then
        if v_cli_rif is null then raise exception 'Para vender a crédito indica el documento del cliente'; end if;
        select saldo_pendiente, limite_credito into v_saldo, v_limite from clientes where rif = v_cli_rif for update;
        if not found then raise exception 'El cliente % no está registrado. Regístralo antes de vender a crédito.', v_cli_rif; end if;
        if coalesce(v_limite, 0) > 0 and coalesce(v_saldo, 0) + v_credito > v_limite then
            raise exception 'La venta excede el límite de crédito del cliente (saldo: %, límite: %)', coalesce(v_saldo, 0), v_limite;
        end if;
    end if;

    insert into ventas (numero, cliente_nombre, cliente_rif, cliente_email, subtotal, iva, total_usd, tasa_bcv, total_bs, metodo_pago, estado,
                        sucursal_id, sucursal_nombre, usuario_nombre, pagos, vuelto, turno_id, terminal, estado_fiscal, monto_abonado)
    values (v_numero, v_cli_nombre, v_cli_rif, nullif(trim(coalesce(v->'cliente'->>'email', '')), ''),
            coalesce((v->>'subtotal')::numeric, v_total), coalesce((v->>'iva')::numeric, 0), v_total, v_tasa, v_total_bs, v_metodo, 'completada',
            v_suc, coalesce(v->>'sucursal_nombre', 'Casa Matriz'), v_usuario, v->'pagos', v->'vuelto',
            nullif(v->>'turno_id', '')::uuid, v->>'terminal', nullif(v->>'estado_fiscal', ''),
            case when v_credito > 0 then greatest(v_total - v_credito, 0) else 0 end)
    returning id into v_id;

    for v_item in select value from jsonb_array_elements(v->'items') loop
        v_cant := coalesce((v_item->>'cantidad')::numeric, 0);
        if v_item->>'codigo' is null or v_cant <= 0 then raise exception 'Producto o cantidad inválida: %', v_item->>'codigo'; end if;
        select coalesce(unidad, 'uds') into v_unidad from productos where codigo = v_item->>'codigo';
        if not found then raise exception 'Producto "%" no encontrado', v_item->>'codigo'; end if;
        if v_unidad = 'uds' and v_cant <> floor(v_cant) then raise exception 'El producto "%" se vende por unidad; la cantidad debe ser entera.', v_item->>'codigo'; end if;
        if v_suc is null or v_suc = v_casa then
            select stock into v_stock from productos where codigo = v_item->>'codigo' for update;
            if coalesce(v_stock, 0) < v_cant then raise exception 'Stock insuficiente de "%" (disponible: %)', coalesce(v_item->>'descripcion', v_item->>'codigo'), coalesce(v_stock, 0); end if;
            update productos set stock = stock - v_cant where codigo = v_item->>'codigo';
        else
            select stock into v_stock from sucursal_stock where sucursal_id = v_suc and producto_codigo = v_item->>'codigo' for update;
            if not found then raise exception 'Producto "%" sin stock en esta tienda', coalesce(v_item->>'descripcion', v_item->>'codigo'); end if;
            if v_stock < v_cant then raise exception 'Stock insuficiente de "%" en la tienda (disponible: %)', coalesce(v_item->>'descripcion', v_item->>'codigo'), v_stock; end if;
            update sucursal_stock set stock = stock - v_cant, updated_at = now() where sucursal_id = v_suc and producto_codigo = v_item->>'codigo';
        end if;
        insert into detalle_venta (venta_id, producto_codigo, descripcion, cantidad, precio_unitario, costo_unitario, descuento, total)
        values (v_id, v_item->>'codigo', v_item->>'descripcion', v_cant, coalesce((v_item->>'precio')::numeric, 0),
                coalesce((v_item->>'costo')::numeric, 0), coalesce((v_item->>'descuento')::numeric, 0), coalesce((v_item->>'total')::numeric, 0));
    end loop;

    -- Caja: un movimiento por cada pago (el crédito no entra a caja)
    for p in select value from jsonb_array_elements(v->'pagos') loop
        continue when p->>'metodo' = 'credito';
        insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre, metodo_pago)
        values ('venta', 'Venta ' || v_numero || ' - ' || v_cli_nombre || ' (' || (p->>'metodo') || coalesce(' ' || nullif(p->>'moneda', ''), '') || ')',
                round((p->>'monto_usd')::numeric, 2), round(coalesce((p->>'monto_bs')::numeric, (p->>'monto_usd')::numeric * v_tasa), 2), v_suc, v_usuario, p->>'metodo');
        if p->>'metodo' = 'pago_movil' then
            insert into pagos_moviles (banco, remitente, monto, referencia, sucursal_id, usuario_nombre, venta_numero)
            values (coalesce(p->>'banco', ''), coalesce(nullif(p->>'remitente', ''), v_cli_nombre),
                    round(coalesce((p->>'monto_bs')::numeric, (p->>'monto_usd')::numeric * v_tasa), 2), nullif(p->>'referencia', ''), v_suc, v_usuario, v_numero);
        end if;
    end loop;
    -- Vuelto entregado (sale de la caja)
    if jsonb_typeof(v->'vuelto') = 'array' then
        for p in select value from jsonb_array_elements(v->'vuelto') loop
            continue when coalesce((p->>'monto_usd')::numeric, 0) <= 0;
            insert into caja_movimientos (tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre, metodo_pago)
            values ('egreso', 'Vuelto venta ' || v_numero || ' (' || (p->>'metodo') || coalesce(' ' || nullif(p->>'moneda', ''), '') || ')',
                    round((p->>'monto_usd')::numeric, 2), round(coalesce((p->>'monto_bs')::numeric, (p->>'monto_usd')::numeric * v_tasa), 2), v_suc, v_usuario, p->>'metodo');
        end loop;
    end if;

    if v_credito > 0 then
        update clientes set saldo_pendiente = coalesce(saldo_pendiente, 0) + v_credito where rif = v_cli_rif;
    end if;
    if nullif(trim(coalesce(v->'cliente'->>'email', '')), '') is not null and v_cli_rif is not null then
        update clientes set email = trim(v->'cliente'->>'email') where rif = v_cli_rif and coalesce(email, '') = '';
    end if;
    return jsonb_build_object('ok', true, 'venta_id', v_id, 'numero', v_numero, 'metodo', v_metodo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_fiscal_registrar(p_tipo text, p_numero text, p_numero_fiscal text, p_serial text, p_estado text DEFAULT 'fiscalizada'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_tipo = 'nota_credito' then
        update notas_credito set numero_fiscal = p_numero_fiscal, serial_fiscal = p_serial, estado_fiscal = p_estado, fecha_fiscal = now() where numero = p_numero;
    else
        update ventas set numero_fiscal = p_numero_fiscal, serial_fiscal = p_serial, estado_fiscal = p_estado, fecha_fiscal = now() where numero = p_numero;
    end if;
    if not found then raise exception 'Documento % no encontrado', p_numero; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_nota_credito(p_venta_id uuid, p_items jsonb, p_motivo text, p_usuario text, p_metodo text DEFAULT NULL::text, p_estado_fiscal text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb;
begin
    r := nota_credito_registrar(p_venta_id, p_items, p_motivo, p_usuario);
    if p_metodo is not null and p_metodo <> '' then
        update caja_movimientos set metodo_pago = p_metodo
        where tipo = 'egreso' and concepto like 'Nota de crédito ' || (r->>'numero') || '%';
        update notas_credito set metodo_reembolso = p_metodo where numero = r->>'numero' and metodo_reembolso <> 'rebaja_deuda';
    end if;
    if p_estado_fiscal is not null then update notas_credito set estado_fiscal = p_estado_fiscal where numero = r->>'numero'; end if;
    return r;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_turno_cerrar(p_id uuid, p_contado_usd numeric, p_contado_bs numeric, p_conteo jsonb, p_notas text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; v_t record;
begin
    r := turno_cerrar(p_id, p_contado_usd, p_contado_bs, p_notas);
    update turnos set resumen = coalesce(resumen, '{}'::jsonb) || jsonb_build_object('conteo', coalesce(p_conteo, '[]'::jsonb)) where id = p_id;
    begin
        select sucursal_id, cerrado_at into v_t from turnos where id = p_id;
        perform cierre_diario_auto((coalesce(v_t.cerrado_at, now()) at time zone 'America/Caracas')::date,
                                   coalesce(v_t.sucursal_id, '00000000-0000-0000-0000-000000000001'));
    exception when others then null;
    end;
    return r;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pos_validar_venta(p_venta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_uid uuid := refrimar_sesion_uid(30);
    -- Precios con IVA incluido: igual que la caja (columna iva_incluido o la opción del negocio, en cualquier fila de configuración)
    v_incl boolean := coalesce((select bool_or(coalesce(iva_incluido, false) or coalesce((opciones->>'iva_incluido')::boolean, false)) from configuracion), false);
    it jsonb; pr record; v_cant numeric; v_precio numeric; v_desc numeric; v_iva numeric;
    v_min numeric := 0; v_n int := 0; v_total numeric := coalesce((p_venta->>'total_usd')::numeric, 0);
    v_nombre text;
begin
    if jsonb_typeof(p_venta->'items') <> 'array' then raise exception 'La factura no tiene productos'; end if;
    for it in select value from jsonb_array_elements(p_venta->'items') loop
        v_n := v_n + 1;
        select precio, iva_tasa into pr from productos where codigo = it->>'codigo';
        if not found then raise exception 'Producto "%" no encontrado', it->>'codigo'; end if;
        v_cant := coalesce((it->>'cantidad')::numeric, 0);
        v_precio := coalesce((it->>'precio')::numeric, -1);
        v_desc := coalesce((it->>'descuento')::numeric, 0);
        if v_cant <= 0 or v_cant > 1000000 then raise exception 'Cantidad inválida en "%"', coalesce(it->>'descripcion', it->>'codigo'); end if;
        if v_precio < 0 then raise exception 'Precio inválido en "%"', coalesce(it->>'descripcion', it->>'codigo'); end if;
        if v_desc < 0 or v_desc > 100 then raise exception 'Descuento inválido en "%"', coalesce(it->>'descripcion', it->>'codigo'); end if;
        if v_precio < coalesce(pr.precio, 0) - 0.0001 and not (v_uid is not null and refrimar_tiene_permiso(v_uid, 'app_cambiar_precio')) then
            raise exception 'No tienes permiso para bajar el precio de "%" (precio: % $). Pide a un supervisor.', coalesce(it->>'descripcion', it->>'codigo'), round(pr.precio, 2);
        end if;
        if v_desc > 0 and not (v_uid is not null and refrimar_tiene_permiso(v_uid, 'app_descuento')) then
            raise exception 'No tienes permiso para aplicar descuentos ("%").', coalesce(it->>'descripcion', it->>'codigo');
        end if;
        v_iva := coalesce(pr.iva_tasa, 16);
        -- Piso del total: precio x cantidad (sin sumar IVA). Así sirve igual si los precios traen el IVA incluido o no;
        -- lo que de verdad protege es que cada precio no esté por debajo del real (revisado arriba).
        v_min := v_min + v_precio * v_cant * (1 - v_desc / 100);
    end loop;
    if v_total < v_min - (0.01 * v_n + 0.02) then
        raise exception 'El total de la factura (% $) no coincide con los productos (% $). Vuelve a cargar la caja.', round(v_total, 2), round(v_min, 2);
    end if;
    select nombre into v_nombre from usuarios where id = v_uid;
    return jsonb_build_object('ok', true, 'usuario', v_nombre, 'total_minimo', round(v_min, 2));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precio_actualizacion_aplicar_items(p_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_item jsonb; v_codigo text; v_nuevo numeric; v_ant numeric; v_desc text;
    v_ok int := 0; v_err int := 0; v_omit int := 0; v_tot int := 0;
begin
    for v_item in select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
        v_tot := v_tot + 1;
        v_codigo := trim(coalesce(v_item->>'codigo', ''));
        begin v_nuevo := round((v_item->>'precio')::numeric, 2); exception when others then v_nuevo := null; end;
        select precio, descripcion into v_ant, v_desc from productos where codigo = v_codigo;
        if not found then
            v_err := v_err + 1;
            insert into precio_actualizacion_detalle (actualizacion_id, producto_codigo, precio_nuevo, resultado)
            values (p_id, v_codigo, v_nuevo, 'error: código no existe');
            continue;
        end if;
        if v_nuevo is null or v_nuevo <= 0 or v_nuevo = coalesce(v_ant, 0) then
            v_omit := v_omit + 1;
            insert into precio_actualizacion_detalle (actualizacion_id, producto_codigo, descripcion, precio_anterior, precio_nuevo, resultado)
            values (p_id, v_codigo, v_desc, v_ant, v_nuevo, 'omitido');
            continue;
        end if;
        update productos set precio = v_nuevo where codigo = v_codigo;
        insert into precio_actualizacion_detalle (actualizacion_id, producto_codigo, descripcion, precio_anterior, precio_nuevo)
        values (p_id, v_codigo, v_desc, v_ant, v_nuevo);
        v_ok := v_ok + 1;
    end loop;
    update precio_actualizaciones set procesados = v_ok, errores = v_err, omitidos = v_omit, total = v_tot,
        estado = 'completada', ejecutada_at = now()
    where id = p_id;
    return jsonb_build_object('procesados', v_ok, 'errores', v_err, 'omitidos', v_omit, 'total', v_tot);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precio_programada_cancelar(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update precio_actualizaciones set estado = 'cancelada' where id = p_id and estado = 'programada';
    if not found then raise exception 'Solo se pueden cancelar actualizaciones programadas'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precios_actualizacion_crear(p_tipo text, p_descripcion text, p_items jsonb, p_usuario text DEFAULT 'Sistema'::text, p_cuando timestamp with time zone DEFAULT NULL::timestamp with time zone, p_tasa_nueva numeric DEFAULT NULL::numeric, p_parametros jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_numero text; v_res jsonb := '{}'::jsonb;
begin
    if (p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0) and p_tasa_nueva is null then
        raise exception 'No hay productos para actualizar';
    end if;
    if p_tasa_nueva is not null and p_tasa_nueva <= 0 then raise exception 'Tasa inválida'; end if;
    if p_cuando is not null and p_cuando < now() - interval '1 minute' then raise exception 'La fecha programada ya pasó'; end if;
    v_numero := 'AP-' || lpad(nextval('seq_precio_act')::text, 6, '0');
    insert into precio_actualizaciones (numero, tipo, descripcion, usuario_nombre, estado, programada_para, items, tasa_nueva, parametros)
    values (v_numero, coalesce(p_tipo, 'manual'), p_descripcion, coalesce(p_usuario, 'Sistema'),
            case when p_cuando is null then 'completada' else 'programada' end, p_cuando, coalesce(p_items, '[]'::jsonb), p_tasa_nueva, p_parametros)
    returning id into v_id;
    if p_cuando is null then
        if p_tasa_nueva is not null then perform config_actualizar_tasa(p_tasa_nueva); end if;
        v_res := precio_actualizacion_aplicar_items(v_id, p_items);
    end if;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero,
        'estado', case when p_cuando is null then 'completada' else 'programada' end) || v_res;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precios_actualizar(p_tipo text, p_descripcion text, p_items jsonb, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
    v_numero text;
    v_item jsonb;
    v_codigo text;
    v_nuevo numeric;
    v_ant numeric;
    v_desc text;
    v_ok int := 0; v_err int := 0; v_omit int := 0; v_tot int := 0;
begin
    if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
        raise exception 'No hay productos para actualizar';
    end if;
    v_numero := 'AP-' || lpad(nextval('seq_precio_act')::text, 6, '0');
    insert into precio_actualizaciones (numero, tipo, descripcion, usuario_nombre)
    values (v_numero, coalesce(p_tipo, 'manual'), p_descripcion, coalesce(p_usuario, 'Sistema'))
    returning id into v_id;

    for v_item in select value from jsonb_array_elements(p_items) loop
        v_tot := v_tot + 1;
        v_codigo := trim(coalesce(v_item->>'codigo', ''));
        begin
            v_nuevo := round((v_item->>'precio')::numeric, 2);
        exception when others then
            v_nuevo := null;
        end;
        select precio, descripcion into v_ant, v_desc from productos where codigo = v_codigo;
        if not found then
            v_err := v_err + 1;
            insert into precio_actualizacion_detalle (actualizacion_id, producto_codigo, precio_nuevo, resultado)
            values (v_id, v_codigo, v_nuevo, 'error: código no existe');
            continue;
        end if;
        if v_nuevo is null or v_nuevo <= 0 or v_nuevo = coalesce(v_ant, 0) then
            v_omit := v_omit + 1;
            insert into precio_actualizacion_detalle (actualizacion_id, producto_codigo, descripcion, precio_anterior, precio_nuevo, resultado)
            values (v_id, v_codigo, v_desc, v_ant, v_nuevo, 'omitido');
            continue;
        end if;
        update productos set precio = v_nuevo where codigo = v_codigo;
        insert into precio_actualizacion_detalle (actualizacion_id, producto_codigo, descripcion, precio_anterior, precio_nuevo)
        values (v_id, v_codigo, v_desc, v_ant, v_nuevo);
        v_ok := v_ok + 1;
    end loop;

    update precio_actualizaciones set procesados = v_ok, errores = v_err, omitidos = v_omit, total = v_tot where id = v_id;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero, 'procesados', v_ok, 'errores', v_err, 'omitidos', v_omit, 'total', v_tot);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precios_programados_aplicar()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; n int := 0;
begin
    for r in select * from precio_actualizaciones
             where estado = 'programada' and programada_para <= now()
             order by programada_para for update skip locked loop
        if r.tasa_nueva is not null then perform config_actualizar_tasa(r.tasa_nueva); end if;
        perform precio_actualizacion_aplicar_items(r.id, r.items);
        n := n + 1;
    end loop;
    return jsonb_build_object('ok', true, 'aplicadas', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precios_revertir(p_id uuid, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_estado text;
    v_n int := 0;
    r record;
begin
    select estado into v_estado from precio_actualizaciones where id = p_id for update;
    if not found then raise exception 'Actualización no encontrada'; end if;
    if v_estado <> 'completada' then raise exception 'Esta actualización ya fue revertida'; end if;
    for r in select * from precio_actualizacion_detalle where actualizacion_id = p_id and resultado = 'procesado' loop
        update productos set precio = r.precio_anterior where codigo = r.producto_codigo and precio = r.precio_nuevo;
        if found then v_n := v_n + 1; end if;
    end loop;
    update precio_actualizaciones set estado = 'revertida', revertida_at = now() where id = p_id;
    return jsonb_build_object('ok', true, 'revertidos', v_n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.producto_eliminar(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_id is null then
        raise exception 'Falta el producto';
    end if;
    delete from productos where id = p_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.producto_extra_guardar(p_codigo text, p_subcategoria text, p_activo boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update productos set subcategoria = nullif(trim(coalesce(p_subcategoria, '')), ''), activo = coalesce(p_activo, true)
    where codigo = p_codigo;
    if not found then raise exception 'Producto % no existe', p_codigo; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.producto_ficha_guardar(p_codigo text, p_ficha jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    f jsonb := coalesce(p_ficha, '{}'::jsonb);
    v_tipo text;
    v_estatus text;
    v_iva numeric;
    v_tipo_antes text;
begin
    select tipo_producto into v_tipo_antes from productos where codigo = p_codigo;
    if not found then
        raise exception 'Producto % no existe', p_codigo;
    end if;

    v_tipo := coalesce(nullif(f->>'tipo_producto', ''), 'fisico');
    if v_tipo not in ('fisico', 'servicio') then v_tipo := 'fisico'; end if;
    v_estatus := coalesce(nullif(f->>'estatus', ''), 'activo');
    if v_estatus not in ('borrador', 'activo', 'inactivo') then v_estatus := 'activo'; end if;
    v_iva := coalesce(nullif(f->>'iva_tasa', '')::numeric, 16);
    if v_iva < 0 or v_iva > 100 then raise exception 'IVA inválido'; end if;

    update productos set
        sku = nullif(trim(coalesce(f->>'sku', '')), ''),
        detalle = nullif(trim(coalesce(f->>'detalle', '')), ''),
        subcategoria = nullif(trim(coalesce(f->>'subcategoria', '')), ''),
        tipo_producto = v_tipo,
        iva_tasa = v_iva,
        sensible = coalesce((f->>'sensible')::boolean, false),
        requiere_serial = coalesce((f->>'requiere_serial')::boolean, false),
        pesable = coalesce((f->>'pesable')::boolean, false),
        codigo_balanza = nullif(trim(coalesce(f->>'codigo_balanza', '')), ''),
        referencia_interna = nullif(trim(coalesce(f->>'referencia_interna', '')), ''),
        estatus = v_estatus,
        activo = (v_estatus = 'activo'),
        clasificacion = nullif(trim(coalesce(f->>'clasificacion', '')), ''),
        origen = nullif(trim(coalesce(f->>'origen', '')), ''),
        tipo_medida = nullif(trim(coalesce(f->>'tipo_medida', '')), ''),
        medida = nullif(trim(coalesce(f->>'medida', '')), ''),
        presentacion = nullif(trim(coalesce(f->>'presentacion', '')), ''),
        empaques = case when jsonb_typeof(f->'empaques') = 'array' then f->'empaques' else '[]'::jsonb end,
        impuestos_extra = case when jsonb_typeof(f->'impuestos_extra') = 'array' then f->'impuestos_extra' else '[]'::jsonb end,
        proveedores = case when jsonb_typeof(f->'proveedores') = 'array'
                           then array(select jsonb_array_elements_text(f->'proveedores')) else '{}'::text[] end,
        atributos = case when jsonb_typeof(f->'atributos') = 'object' then f->'atributos' else '{}'::jsonb end,
        ref_fabrica = nullif(trim(coalesce(f->>'ref_fabrica', '')), ''),
        cpe = nullif(trim(coalesce(f->>'cpe', '')), ''),
        registro_sanitario = nullif(trim(coalesce(f->>'registro_sanitario', '')), ''),
        variante_grupo = nullif(trim(coalesce(f->>'variante_grupo', '')), ''),
        updated_at = now()
    where codigo = p_codigo;

    -- Un código de barra de empaque no puede chocar con otro producto
    if exists (
        select 1
        from jsonb_array_elements(case when jsonb_typeof(f->'empaques') = 'array' then f->'empaques' else '[]'::jsonb end) e
        join productos p on p.codigo = e->>'barra' and p.codigo <> p_codigo
    ) then
        raise exception 'Un código de barra de empaque ya es el código de otro producto';
    end if;

    -- Servicios: siempre disponibles en todas las tiendas
    if v_tipo = 'servicio' then
        perform servicio_stock_asegurar(p_codigo);
    elsif v_tipo_antes = 'servicio' then
        -- dejó de ser servicio: el stock "infinito" vuelve a 0
        update productos set stock = 0 where codigo = p_codigo;
        update sucursal_stock set stock = 0, updated_at = now() where producto_codigo = p_codigo and stock >= 999999;
    end if;

    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.producto_guardar(p_codigo text, p_descripcion text, p_id uuid DEFAULT NULL::uuid, p_categoria text DEFAULT NULL::text, p_marca text DEFAULT NULL::text, p_unidad text DEFAULT 'uds'::text, p_costo numeric DEFAULT 0, p_precio numeric DEFAULT 0, p_stock numeric DEFAULT 0, p_stock_minimo numeric DEFAULT 0, p_codigos_alternos jsonb DEFAULT NULL::jsonb, p_stock_inicial numeric DEFAULT 0, p_sucursal_stock_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
    v_stock numeric;
    v_codigos_alternos text[] := '{}';
    v_descripcion text;
begin
    if p_codigo is null or trim(p_codigo) = '' then
        raise exception 'El código es obligatorio';
    end if;
    if p_descripcion is null or trim(p_descripcion) = '' then
        raise exception 'La descripción es obligatoria';
    end if;

    if p_codigos_alternos is not null and jsonb_typeof(p_codigos_alternos) = 'array' then
        select coalesce(array_agg(x), '{}') into v_codigos_alternos
        from jsonb_array_elements_text(p_codigos_alternos) x;
    end if;

    -- Si el producto se crea estando en una sucursal, el stock del
    -- catálogo (Casa Matriz) queda en 0 y el stock inicial se
    -- acredita a la sucursal.
    v_stock := case when p_sucursal_stock_id is not null then 0 else coalesce(p_stock, 0) end;
    v_descripcion := trim(p_descripcion);

    if p_id is null then
        insert into productos
            (codigo, descripcion, categoria, marca, unidad, costo, precio, stock, stock_minimo, codigos_alternos)
        values
            (trim(p_codigo), v_descripcion, p_categoria, p_marca, coalesce(p_unidad, 'uds'),
             coalesce(p_costo, 0), coalesce(p_precio, 0), v_stock, coalesce(p_stock_minimo, 0),
             v_codigos_alternos)
        returning id into v_id;
    else
        update productos
        set codigo = trim(p_codigo), descripcion = v_descripcion, categoria = p_categoria,
            marca = p_marca, unidad = coalesce(p_unidad, 'uds'),
            costo = coalesce(p_costo, 0), precio = coalesce(p_precio, 0), stock = v_stock,
            stock_minimo = coalesce(p_stock_minimo, 0),
            codigos_alternos = case when p_codigos_alternos is not null
                                    then v_codigos_alternos else codigos_alternos end
        where id = p_id;
        v_id := p_id;
    end if;

    if v_id is null then
        raise exception 'No se pudo guardar el producto';
    end if;

    -- Stock inicial a sucursal (producto nuevo creado desde una sucursal)
    if p_sucursal_stock_id is not null and coalesce(p_stock_inicial, 0) > 0 then
        insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
        values (p_sucursal_stock_id, trim(p_codigo), v_descripcion, p_stock_inicial)
        on conflict (sucursal_id, producto_codigo)
        do update set stock = sucursal_stock.stock + excluded.stock, updated_at = now();
    end if;

    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.producto_imagenes_guardar(p_codigo text, p_imagenes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if not exists (select 1 from productos where codigo = p_codigo) then
        raise exception 'Producto % no existe', p_codigo;
    end if;
    if p_imagenes is null or jsonb_typeof(p_imagenes) <> 'array' then p_imagenes := '[]'::jsonb; end if;
    if jsonb_array_length(p_imagenes) > 4 then raise exception 'Máximo 4 fotos por producto'; end if;
    if length(p_imagenes::text) > 1500000 then raise exception 'Las fotos pesan demasiado'; end if;
    insert into producto_imagenes (producto_codigo, imagenes, updated_at)
    values (p_codigo, p_imagenes, now())
    on conflict (producto_codigo) do update set imagenes = excluded.imagenes, updated_at = now();
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.producto_stock_maximo(p_codigo text, p_max numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_max is not null and p_max < 0 then raise exception 'El stock máximo no puede ser negativo'; end if;
    update productos set stock_maximo = nullif(p_max, 0) where codigo = p_codigo;
    if not found then raise exception 'Producto % no existe', p_codigo; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_importar(p_rows jsonb, p_sucursal_id uuid DEFAULT NULL::uuid, p_modo_stock text DEFAULT 'reemplazar'::text, p_actualizar boolean DEFAULT true, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa boolean := (p_sucursal_id is null or p_sucursal_id = '00000000-0000-0000-0000-000000000001');
    r jsonb;
    v_fila int;
    v_cod text; v_barra text; v_desc text;
    v_costo numeric; v_precio numeric; v_stock numeric; v_min numeric;
    v_existe record;
    v_actual numeric; v_nuevo numeric; v_delta numeric;
    v_creados int := 0; v_actualizados int := 0; v_omitidos int := 0;
    v_errores jsonb := '[]'::jsonb;
    v_alt text[];
begin
    if p_modo_stock not in ('reemplazar', 'sumar', 'no_tocar') then raise exception 'Modo de stock inválido'; end if;
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then raise exception 'No hay filas para importar'; end if;

    for r in select value from jsonb_array_elements(p_rows) loop
        v_fila := coalesce((r->>'fila')::int, 0);
        begin
            v_cod := nullif(trim(coalesce(r->>'codigo', '')), '');
            v_barra := nullif(trim(coalesce(r->>'barra', '')), '');
            if v_cod is null then v_cod := v_barra; end if;
            if v_cod is null then raise exception 'Sin código'; end if;
            v_desc := nullif(trim(coalesce(r->>'descripcion', '')), '');
            v_costo := nullif(r->>'costo', '')::numeric;
            v_precio := nullif(r->>'precio', '')::numeric;
            v_stock := nullif(r->>'stock', '')::numeric;
            v_min := nullif(r->>'stock_minimo', '')::numeric;
            if v_costo < 0 or v_precio < 0 or v_min < 0 then raise exception 'Hay números negativos'; end if;

            select * into v_existe from productos where codigo = v_cod;

            if not found then
                if v_desc is null then raise exception 'Producto nuevo sin nombre'; end if;
                v_alt := case when v_barra is not null and v_barra <> v_cod then array[v_barra] else '{}'::text[] end;
                insert into productos (codigo, descripcion, categoria, subcategoria, marca, unidad, costo, precio, stock, stock_minimo, codigos_alternos, activo)
                values (v_cod, v_desc, nullif(trim(coalesce(r->>'categoria', '')), ''), nullif(trim(coalesce(r->>'subcategoria', '')), ''),
                        nullif(trim(coalesce(r->>'marca', '')), ''), unidad_normalizar(r->>'unidad'),
                        coalesce(v_costo, 0), coalesce(v_precio, 0), 0, coalesce(v_min, 0), v_alt, true);
                v_creados := v_creados + 1;
            elsif p_actualizar then
                update productos set
                    descripcion = coalesce(v_desc, descripcion),
                    categoria = coalesce(nullif(trim(coalesce(r->>'categoria', '')), ''), categoria),
                    subcategoria = coalesce(nullif(trim(coalesce(r->>'subcategoria', '')), ''), subcategoria),
                    marca = coalesce(nullif(trim(coalesce(r->>'marca', '')), ''), marca),
                    unidad = case when nullif(trim(coalesce(r->>'unidad', '')), '') is null then unidad else unidad_normalizar(r->>'unidad') end,
                    costo = coalesce(v_costo, costo),
                    precio = coalesce(v_precio, precio),
                    stock_minimo = coalesce(v_min, stock_minimo),
                    codigos_alternos = case when v_barra is not null and v_barra <> v_cod and not (v_barra = any(coalesce(codigos_alternos, '{}')))
                                            then array_append(coalesce(codigos_alternos, '{}'), v_barra) else codigos_alternos end
                where codigo = v_cod;
                v_actualizados := v_actualizados + 1;
            else
                v_omitidos := v_omitidos + 1;
                continue;
            end if;

            -- Stock en la tienda elegida
            if v_stock is not null and p_modo_stock <> 'no_tocar' then
                if v_stock < 0 then raise exception 'Stock negativo'; end if;
                v_actual := stock_en(v_cod, p_sucursal_id);
                v_nuevo := case when p_modo_stock = 'sumar' then v_actual + v_stock else v_stock end;
                v_delta := v_nuevo - v_actual;
                if v_delta <> 0 then
                    if v_casa then
                        update productos set stock = v_nuevo where codigo = v_cod;
                    else
                        insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock, costo)
                        values (p_sucursal_id, v_cod, coalesce(v_desc, v_existe.descripcion, v_cod), v_nuevo, v_costo)
                        on conflict (sucursal_id, producto_codigo)
                        do update set stock = excluded.stock, costo = coalesce(excluded.costo, sucursal_stock.costo), updated_at = now();
                    end if;
                    insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total,
                        saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
                    values (v_cod, coalesce(v_desc, v_existe.descripcion, v_cod), current_date,
                        case when v_delta > 0 then 'entrada_ajuste' else 'salida_ajuste' end, v_delta,
                        coalesce(v_costo, 0), abs(v_delta) * coalesce(v_costo, 0), v_nuevo, coalesce(v_costo, 0),
                        'Importación Excel', coalesce(p_usuario, 'Sistema'), case when v_casa then null else p_sucursal_id end);
                elsif not v_casa and not exists (select 1 from sucursal_stock where sucursal_id = p_sucursal_id and producto_codigo = v_cod) then
                    -- stock 0 en sucursal: igual se registra para que el producto aparezca en esa tienda
                    insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock, costo)
                    values (p_sucursal_id, v_cod, coalesce(v_desc, v_existe.descripcion, v_cod), 0, v_costo)
                    on conflict (sucursal_id, producto_codigo) do nothing;
                end if;
            end if;
        exception when others then
            v_errores := v_errores || jsonb_build_object('fila', v_fila, 'codigo', coalesce(v_cod, ''), 'error', sqlerrm);
        end;
    end loop;

    return jsonb_build_object('ok', true, 'creados', v_creados, 'actualizados', v_actualizados,
        'omitidos', v_omitidos, 'errores', v_errores);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_importar_atributos(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; v_cod text; n int := 0; v_attr jsonb;
begin
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return jsonb_build_object('ok', true, 'actualizados', 0); end if;
    for r in select value from jsonb_array_elements(p_rows) loop
        v_cod := nullif(trim(coalesce(r->>'codigo', '')), '');
        if v_cod is null then continue; end if;
        -- Solo se guardan los valores con texto (los vacíos no borran lo que ya había)
        select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_attr
        from jsonb_each(case when jsonb_typeof(r->'atributos') = 'object' then r->'atributos' else '{}'::jsonb end)
        where coalesce(nullif(trim(value #>> '{}'), ''), null) is not null;
        update productos set
            atributos = coalesce(atributos, '{}'::jsonb) || v_attr,
            requiere_serial = case when r ? 'requiere_serial' then coalesce((r->>'requiere_serial')::boolean, requiere_serial) else requiere_serial end
        where codigo = v_cod;
        if found then n := n + 1; end if;
    end loop;
    return jsonb_build_object('ok', true, 'actualizados', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_importar_extra(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    r jsonb;
    v_cod text;
    v_iva numeric;
    n int := 0;
begin
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return jsonb_build_object('ok', true, 'actualizados', 0); end if;
    for r in select value from jsonb_array_elements(p_rows) loop
        v_cod := nullif(trim(coalesce(r->>'codigo', '')), '');
        if v_cod is null then v_cod := nullif(trim(coalesce(r->>'barra', '')), ''); end if;
        if v_cod is null then continue; end if;
        begin
            v_iva := iva_normalizar(r->>'iva');
        exception when others then v_iva := null;
        end;
        update productos set
            iva_tasa = coalesce(v_iva, iva_tasa),
            sku = coalesce(nullif(trim(coalesce(r->>'sku', '')), ''), sku),
            detalle = coalesce(nullif(trim(coalesce(r->>'detalle', '')), ''), detalle)
        where codigo = v_cod
          and (v_iva is not null or nullif(trim(coalesce(r->>'sku', '')), '') is not null or nullif(trim(coalesce(r->>'detalle', '')), '') is not null);
        if found then n := n + 1; end if;
    end loop;
    return jsonb_build_object('ok', true, 'actualizados', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_importar_ficha(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    r jsonb;
    v_cod text;
    v_iva numeric;
    v_tipo text;
    n int := 0;
begin
    if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return jsonb_build_object('ok', true, 'actualizados', 0); end if;
    for r in select value from jsonb_array_elements(p_rows) loop
        v_cod := nullif(trim(coalesce(r->>'codigo', '')), '');
        if v_cod is null then continue; end if;
        begin v_iva := iva_normalizar(r->>'iva'); exception when others then v_iva := null; end;
        v_tipo := case when r->>'tipo_producto' = 'servicio' then 'servicio' else 'fisico' end;
        update productos set
            iva_tasa = coalesce(v_iva, iva_tasa),
            sku = coalesce(nullif(trim(coalesce(r->>'sku', '')), ''), sku),
            detalle = coalesce(nullif(trim(coalesce(r->>'detalle', '')), ''), detalle),
            tipo_producto = v_tipo,
            pesable = coalesce((r->>'pesable')::boolean, pesable),
            codigo_balanza = coalesce(nullif(trim(coalesce(r->>'codigo_balanza', '')), ''), codigo_balanza),
            clasificacion = coalesce(nullif(trim(coalesce(r->>'clasificacion', '')), ''), clasificacion),
            origen = coalesce(nullif(trim(coalesce(r->>'origen', '')), ''), origen),
            tipo_medida = coalesce(nullif(trim(coalesce(r->>'tipo_medida', '')), ''), tipo_medida),
            medida = coalesce(nullif(trim(coalesce(r->>'medida', '')), ''), medida),
            presentacion = coalesce(nullif(trim(coalesce(r->>'presentacion', '')), ''), presentacion),
            ref_fabrica = coalesce(nullif(trim(coalesce(r->>'ref_fabrica', '')), ''), ref_fabrica),
            referencia_interna = coalesce(nullif(trim(coalesce(r->>'referencia_interna', '')), ''), referencia_interna),
            stock_maximo = coalesce(nullif(r->>'stock_maximo', '')::numeric, stock_maximo),
            proveedores = case when jsonb_typeof(r->'proveedores') = 'array' and jsonb_array_length(r->'proveedores') > 0
                               then array(select distinct x from unnest(coalesce(proveedores, '{}') || array(select jsonb_array_elements_text(r->'proveedores'))) x)
                               else proveedores end,
            updated_at = now()
        where codigo = v_cod;
        if found then
            n := n + 1;
            if v_tipo = 'servicio' then perform servicio_stock_asegurar(v_cod); end if;
        end if;
    end loop;
    return jsonb_build_object('ok', true, 'actualizados', n);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_importar_lote(p_importacion_id uuid, p_rows jsonb, p_sucursal_id uuid DEFAULT NULL::uuid, p_modo_stock text DEFAULT 'reemplazar'::text, p_actualizar boolean DEFAULT true, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_suc uuid := case when p_sucursal_id = '00000000-0000-0000-0000-000000000001' then null else p_sucursal_id end;
    v_codigos text[]; v_res jsonb;
begin
    if not exists (select 1 from importaciones_productos where id = p_importacion_id and estado = 'en_curso') then
        raise exception 'La importación no está abierta';
    end if;
    select array_agg(distinct c) into v_codigos from (
        select coalesce(nullif(trim(coalesce(value->>'codigo', '')), ''), nullif(trim(coalesce(value->>'barra', '')), '')) c
        from jsonb_array_elements(p_rows)) x where c is not null;
    v_codigos := coalesce(v_codigos, '{}');

    -- Estado anterior (solo la primera vez que aparece el código en esta importación)
    insert into importacion_cambios (importacion_id, codigo, accion, antes, sucursal_id, stock_antes)
    select p_importacion_id, p.codigo, 'actualizado', to_jsonb(p), v_suc, stock_en(p.codigo, p_sucursal_id)
    from productos p
    where p.codigo = any (v_codigos)
      and not exists (select 1 from importacion_cambios c where c.importacion_id = p_importacion_id and c.codigo = p.codigo);

    v_res := productos_importar(p_rows, p_sucursal_id, p_modo_stock, p_actualizar, p_usuario);

    -- Productos nuevos
    insert into importacion_cambios (importacion_id, codigo, accion, sucursal_id, stock_antes)
    select p_importacion_id, p.codigo, 'creado', v_suc, 0
    from productos p
    where p.codigo = any (v_codigos)
      and not exists (select 1 from importacion_cambios c where c.importacion_id = p_importacion_id and c.codigo = p.codigo);

    update importacion_cambios c set stock_despues = stock_en(c.codigo, p_sucursal_id)
    where c.importacion_id = p_importacion_id and c.codigo = any (v_codigos);

    return v_res;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_importar_simular(p_rows jsonb, p_sucursal_id uuid DEFAULT NULL::uuid, p_modo_stock text DEFAULT 'reemplazar'::text, p_actualizar boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res jsonb;
begin
    begin
        v_res := productos_importar(p_rows, p_sucursal_id, p_modo_stock, p_actualizar, 'Simulación');
        raise exception using errcode = 'P0099', message = 'simulacion';
    exception when sqlstate 'P0099' then
        null;   -- todo lo hecho dentro del bloque se revierte
    end;
    return coalesce(v_res, '{}'::jsonb) || jsonb_build_object('simulacion', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.productos_servicio_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.tipo_producto = 'servicio' and coalesce(new.stock, 0) < 999999 then
        new.stock := 999999;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_crear_sesion(p_uid uuid, p_metodo text, p_dispositivo text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tok text := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
begin
    insert into sesiones (token_hash, usuario_id, rol, metodo, dispositivo, expira_at)
    values (refrimar_hash(v_tok), p_uid, (select rol from usuarios where id = p_uid), p_metodo, left(coalesce(p_dispositivo, 'web'), 40),
            now() + case when coalesce(p_dispositivo, '') = 'pos' then interval '7 days' else interval '24 hours' end);
    -- Limpieza de sesiones viejas
    delete from sesiones where expira_at < now() - interval '45 days';
    return v_tok;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_envolver(p_fn text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    f record; v_args text[]; v_names text[]; v_types text[]; v_chk text := ''; v_call text; v_ret text; v_body text; i int; v_cfg text;
begin
    select p.oid, pg_get_function_arguments(p.oid) as args, pg_get_function_result(p.oid) as res, p.proargnames, p.proargtypes::regtype[]::text[] as tipos, p.proconfig
      into f from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = p_fn order by p.oid desc limit 1;
    if not found then return p_fn || ': no existe'; end if;
    if pg_get_functiondef(f.oid) ~ 'refrimar_envuelta' then return p_fn || ': ya revisada'; end if;
    if to_regproc('public.' || p_fn || '_base') is not null then execute format('drop function public.%I(%s)', p_fn || '_base', pg_get_function_identity_arguments(to_regproc('public.' || p_fn || '_base'))); end if;
    execute format('alter function public.%I(%s) rename to %I', p_fn, pg_get_function_identity_arguments(f.oid), p_fn || '_base');
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated', p_fn || '_base', pg_get_function_identity_arguments(f.oid));
    v_names := f.proargnames; v_types := f.tipos; v_args := '{}';
    for i in 1 .. coalesce(array_length(v_types, 1), 0) loop
        v_args := v_args || format('%I => %I', v_names[i], v_names[i]);
        if v_types[i] = 'numeric' and v_names[i] ~ '^p_(monto|cantidad|costo|precio)' then
            v_chk := v_chk || format('    if %1$I is not null and (%1$I < 0 or %1$I > 1000000000) then raise exception ''El valor de %2$s no es válido''; end if;' || chr(10), v_names[i], replace(substr(v_names[i], 3), '_', ' '));
        elsif v_types[i] = 'jsonb' and v_names[i] = 'p_items' then
            v_chk := v_chk || '    perform refrimar_validar_items(p_items);' || chr(10);
        elsif v_names[i] = 'p_usuario' and v_types[i] = 'text' then
            v_chk := v_chk || '    p_usuario := coalesce((select nombre from usuarios where id = refrimar_sesion_uid(30)), p_usuario);' || chr(10);
        end if;
    end loop;
    v_call := format('%I(%s)', p_fn || '_base', array_to_string(v_args, ', '));
    v_ret := case when f.res = 'void' then 'perform ' || v_call || '; return;'
                  when f.res ~* '^(setof|table)' then 'return query select * from ' || v_call || ';'
                  else 'return ' || v_call || ';' end;
    v_cfg := coalesce((select string_agg('set ' || split_part(c, '=', 1) || ' = ' || split_part(c, '=', 2), ' ') from unnest(f.proconfig) c), 'set search_path = public');
    v_body := format('create function public.%I(%s) returns %s language plpgsql security definer %s as $w$' || chr(10) ||
                     '-- refrimar_envuelta' || chr(10) || 'begin' || chr(10) || '%s    %s' || chr(10) || 'end;' || chr(10) || '$w$',
                     p_fn, f.args, f.res, v_cfg, v_chk, v_ret);
    execute v_body;
    execute format('grant execute on function public.%I(%s) to anon, authenticated', p_fn, pg_get_function_identity_arguments(f.oid));
    return p_fn || ': revisada';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_header(p text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
    return nullif(coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json ->> p, '');
exception when others then return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_mover_stock(p_codigo text, p_sucursal uuid, p_delta numeric, p_desc text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v numeric;
begin
    if p_sucursal is null or p_sucursal = '00000000-0000-0000-0000-000000000001' then
        update productos set stock = coalesce(stock, 0) + p_delta where codigo = p_codigo returning stock into v;
    else
        insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
        values (p_sucursal, p_codigo, coalesce(p_desc, p_codigo), p_delta)
        on conflict (sucursal_id, producto_codigo) do update set stock = sucursal_stock.stock + p_delta, updated_at = now()
        returning stock into v;
    end if;
    return v;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_pre_request()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_path text := coalesce(current_setting('request.path', true), '');
    v_met text := upper(coalesce(current_setting('request.method', true), 'GET'));
    v_rpc text; v_tabla text; v_nivel text; v_perm text; v_gracia int := 0;
    v_uid uuid; v_motivo text; v_modo text;
begin
    if v_path like '/rpc/%' then
        v_rpc := lower(split_part(substr(v_path, 6), '?', 1));
        select nivel, permiso, gracia_dias into v_nivel, v_perm, v_gracia from seguridad_rpc where nombre = v_rpc;
        if v_nivel = 'publico' then return; end if;
        if v_nivel = 'compat' then
            if refrimar_modo() = 'estricto' then
                raise exception using errcode = 'PT403', message = 'Actualiza la página: el acceso cambió por seguridad.';
            end if;
            return;
        end if;
        if v_nivel = 'servicio' then
            if exists (select 1 from seguridad_config where id = 1 and (servicio_token_hash is null or servicio_token_hash = refrimar_hash(refrimar_header('x-refrimar-servicio')))) then return; end if;
        end if;
    else
        v_tabla := lower(split_part(ltrim(v_path, '/'), '?', 1));
        -- Lecturas que necesita la página ANTES de entrar (login, tienda, bot de WhatsApp)
        if v_met in ('GET', 'HEAD') and v_tabla in ('sucursales', 'usuarios', 'configuracion', 'tasas_historial') then return; end if;
        if v_met in ('GET', 'HEAD') and refrimar_servicio_ok() then return; end if;   -- bot y tareas automáticas
        if v_tabla = '' then return; end if;   -- esquema OpenAPI
    end if;

    v_uid := refrimar_sesion_uid(coalesce(v_gracia, 0));
    if v_uid is null then
        v_motivo := 'sin_sesion';
    elsif v_perm is not null and not refrimar_tiene_permiso(v_uid, v_perm) then
        v_motivo := 'sin_permiso:' || v_perm;
    elsif not exists (select 1 from usuarios where id = v_uid and activo is not false) then
        v_motivo := 'usuario_inactivo';
    end if;
    if v_motivo is null then return; end if;

    perform refrimar_evento(v_path, v_met, v_motivo, v_uid);
    v_modo := refrimar_modo();
    if v_modo = 'estricto' then
        if v_motivo = 'sin_sesion' then
            raise exception using errcode = 'PT401', message = 'Tu sesión venció. Vuelve a entrar.';
        end if;
        raise exception using errcode = 'PT403', message = 'Tu usuario no tiene permiso para esta operación.';
    end if;
exception
    when others then
        if SQLSTATE in ('PT401', 'PT403') then raise; end if;
        return;   -- cualquier falla inesperada aquí NO tumba el sistema
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_puede_aprobar(p_usuario text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid; v_rol text;
begin
    begin execute 'select refrimar_sesion_uid(0)' into v_uid; exception when others then v_uid := null; end;
    if v_uid is not null then select rol into v_rol from usuarios where id = v_uid;
    else select rol into v_rol from usuarios where nombre = p_usuario and activo is not false limit 1; end if;
    return coalesce(v_rol, '') in ('admin', 'administrador', 'supervisor_tienda');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_quien()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid; v_nom text;
begin
    begin
        execute 'select refrimar_sesion_uid(30)' into v_uid;
    exception when others then v_uid := null;
    end;
    if v_uid is not null then select nombre into v_nom from usuarios where id = v_uid; end if;
    if v_nom is null then
        begin
            v_nom := nullif(coalesce(current_setting('request.jwt.claims', true), '{}')::json ->> 'email', '');
        exception when others then v_nom := null;
        end;
    end if;
    return jsonb_build_object('id', v_uid, 'nombre', coalesce(v_nom, 'Sistema'));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_sesion_uid(p_gracia_dias integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tok text := refrimar_header('x-refrimar-sesion'); v_uid uuid;
begin
    if v_tok is null then return null; end if;
    select s.usuario_id into v_uid from sesiones s
    where s.token_hash = refrimar_hash(v_tok) and not s.revocada
      and s.expira_at + make_interval(days => greatest(coalesce(p_gracia_dias, 0), 0)) > now();
    return v_uid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_tiene_permiso(p_uid uuid, p_permiso text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u record; v_lista jsonb;
begin
    select * into u from usuarios where id = p_uid;
    if not found or u.activo is false then return false; end if;
    if u.rol = 'admin' then return true; end if;
    if p_permiso is null then return true; end if;
    v_lista := coalesce(to_jsonb(u.permisos), '[]'::jsonb);
    if jsonb_typeof(v_lista) <> 'array' then v_lista := '[]'::jsonb; end if;
    -- Permisos viejos (antes de "Gestión de equipo"): lista fija del empleado
    if not (v_lista ? 'v2') and v_lista = '[]'::jsonb then
        return p_permiso = any (array['facturar', 'ver_mi_caja', 'registrar_clientes', 'ver_inventario', 'cotizar', 'ver_dashboard']);
    end if;
    if v_lista ? p_permiso then return true; end if;
    return exists (select 1 from permisos_mapa m where m.interno = p_permiso and v_lista ? m.clave);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refrimar_validar_items(p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare it jsonb; c numeric;
begin
    if p_items is null then return; end if;
    if jsonb_typeof(p_items) <> 'array' then raise exception 'Lista de productos inválida'; end if;
    if jsonb_array_length(p_items) > 5000 then raise exception 'Demasiados productos en un solo documento (máximo 5000)'; end if;
    for it in select value from jsonb_array_elements(p_items) loop
        if jsonb_typeof(it) <> 'object' then raise exception 'Producto inválido en la lista'; end if;
        foreach c in array array[nullif(it->>'cantidad', '')::numeric, nullif(it->>'costo', '')::numeric, nullif(it->>'costo_unitario', '')::numeric, nullif(it->>'precio', '')::numeric] loop
            if c is not null and (c < 0 or c > 1000000000) then raise exception 'Hay una cantidad o un monto inválido en "%"', coalesce(it->>'descripcion', it->>'codigo', '?'); end if;
        end loop;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_venta(p_numero text, p_cliente_nombre text, p_cliente_rif text, p_subtotal numeric, p_iva numeric, p_total_usd numeric, p_tasa_bcv numeric, p_total_bs numeric, p_metodo_pago text, p_sucursal_id uuid, p_usuario text, p_items text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_venta_id uuid;
  v_venta_numero text;
  v_item jsonb;
BEGIN
  INSERT INTO public.ventas (
    numero, cliente_nombre, cliente_rif, subtotal, iva, total_usd,
    tasa_bcv, total_bs, metodo_pago, sucursal_id, estado
  ) VALUES (
    p_numero, p_cliente_nombre, p_cliente_rif, p_subtotal, p_iva, p_total_usd,
    p_tasa_bcv, p_total_bs, p_metodo_pago, p_sucursal_id, 'completada'
  ) RETURNING id, numero INTO v_venta_id, v_venta_numero;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items::jsonb)
  LOOP
    INSERT INTO public.detalle_venta (
      venta_id, producto_codigo, descripcion, cantidad, precio_unitario, costo_unitario, total
    ) VALUES (
      v_venta_id,
      v_item->>'codigo',
      v_item->>'descripcion',
      (v_item->>'cantidad')::numeric,
      (v_item->>'precio')::numeric,
      (v_item->>'costo')::numeric,
      ((v_item->>'cantidad')::numeric * (v_item->>'precio')::numeric)
    );

    INSERT INTO public.sucursal_stock (sucursal_id, producto_codigo, stock, costo, updated_at)
    VALUES (p_sucursal_id, v_item->>'codigo', 0, (v_item->>'costo')::numeric, now())
    ON CONFLICT (sucursal_id, producto_codigo) DO NOTHING;

    UPDATE public.sucursal_stock
    SET stock = stock - (v_item->>'cantidad')::numeric,
        updated_at = now()
    WHERE sucursal_id = p_sucursal_id
      AND producto_codigo = v_item->>'codigo';

    INSERT INTO public.kardex_movimientos (
      producto_codigo, tipo, cantidad, costo_unitario, producto_descripcion,
      sucursal_id, usuario_nombre
    ) VALUES (
      v_item->>'codigo', 'salida', (v_item->>'cantidad')::numeric,
      (v_item->>'costo')::numeric,
      v_item->>'descripcion',
      p_sucursal_id, p_usuario
    );
  END LOOP;

  INSERT INTO public.caja_movimientos (
    tipo, concepto, monto_usd, monto_bs, sucursal_id, usuario_nombre
  ) VALUES (
    'venta', 'Venta ' || v_venta_numero,
    p_total_usd, p_total_bs, p_sucursal_id, p_usuario
  );

  RETURN jsonb_build_object('id', v_venta_id, 'numero', v_venta_numero, 'ok', true);
END; $function$
;

CREATE OR REPLACE FUNCTION public.revertir_traspaso_sucursal(p_movimiento_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa_matriz uuid := '00000000-0000-0000-0000-000000000001';
    v_mov record;
begin
    select * into v_mov from sucursal_movimientos where id = p_movimiento_id for update;
    if not found then
        raise exception 'Movimiento no encontrado';
    end if;

    if v_mov.tipo = 'traspaso' and v_mov.producto_codigo is not null then
        -- Traspaso original fue Casa Matriz -> sucursal destino (v_mov.sucursal_id).
        -- Revertir = devolver cantidad de la sucursal a Casa Matriz.
        update sucursal_stock
        set stock = greatest(stock - v_mov.cantidad, 0), updated_at = now()
        where sucursal_id = v_mov.sucursal_id and producto_codigo = v_mov.producto_codigo;

        update productos set stock = stock + v_mov.cantidad where codigo = v_mov.producto_codigo;
    end if;

    delete from sucursal_movimientos where id = p_movimiento_id;

    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rif_valido(p text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare d text := upper(regexp_replace(coalesce(p, ''), '[^A-Za-z0-9]', '', 'g')); s int; pesos int[] := array[3, 2, 7, 6, 5, 4, 3, 2]; i int; v int;
begin
    if d !~ '^[VEJPGC][0-9]{9}$' then return false; end if;
    s := 4 * (case substr(d, 1, 1) when 'V' then 1 when 'E' then 2 when 'J' then 3 when 'P' then 4 when 'G' then 5 when 'C' then 3 end);
    for i in 1..8 loop s := s + substr(d, i + 1, 1)::int * pesos[i]; end loop;
    v := 11 - (s % 11);
    if v >= 10 then v := 0; end if;
    return v = substr(d, 10, 1)::int;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_admin_crear_empresa(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
begin
    if not saas.es_superadmin() then raise exception 'Solo el administrador de la plataforma' using errcode = 'PT403'; end if;
    return saas.crear_empresa(p, 'superadmin');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_admin_empresa_guardar(p_id uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare e saas.empresas;
begin
    if not saas.es_superadmin() then raise exception 'Solo el administrador de la plataforma' using errcode = 'PT403'; end if;
    select * into e from saas.empresas where id = p_id for update;
    if not found then raise exception 'Empresa no encontrada'; end if;
    if e.esquema = 'public' and coalesce(p ->> 'estado', 'activa') not in ('activa') then raise exception 'La empresa principal no se puede bloquear'; end if;
    if p ? 'plan_id' and not exists (select 1 from saas.planes where id = p ->> 'plan_id') then raise exception 'Plan no existe'; end if;
    update saas.empresas set
        nombre = coalesce(nullif(trim(p ->> 'nombre'), ''), nombre),
        plan_id = coalesce(nullif(p ->> 'plan_id', ''), plan_id),
        estado = coalesce(nullif(p ->> 'estado', ''), estado),
        prueba_hasta = case when p ? 'prueba_hasta' then nullif(p ->> 'prueba_hasta', '')::date else prueba_hasta end,
        pagado_hasta = case when p ? 'pagado_hasta' then nullif(p ->> 'pagado_hasta', '')::date else pagado_hasta end,
        notas = case when p ? 'notas' then p ->> 'notas' else notas end,
        actualizada_at = now()
    where id = p_id;
    perform saas.registrar_evento(p_id, 'empresa_actualizada', p);
    if p ? 'estado' then perform saas.exponer_esquemas(); end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_admin_pago(p_empresa uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare e saas.empresas; v_desde date; v_hasta date; v_meses int := greatest(1, coalesce(nullif(p ->> 'meses', '')::int, 1));
begin
    if not saas.es_superadmin() then raise exception 'Solo el administrador de la plataforma' using errcode = 'PT403'; end if;
    select * into e from saas.empresas where id = p_empresa for update;
    if not found then raise exception 'Empresa no encontrada'; end if;
    -- El período nuevo empieza donde terminó el pagado (o hoy si ya venció)
    v_desde := greatest(current_date, coalesce(e.pagado_hasta + 1, current_date));
    v_hasta := coalesce(nullif(p ->> 'hasta', '')::date, (v_desde + make_interval(months => v_meses))::date - 1);
    insert into saas.pagos (empresa_id, fecha, monto_usd, metodo, referencia, periodo_desde, periodo_hasta, notas, registrado_por)
    values (p_empresa, coalesce(nullif(p ->> 'fecha', '')::date, current_date), coalesce(nullif(p ->> 'monto_usd', '')::numeric, 0),
            nullif(p ->> 'metodo', ''), nullif(p ->> 'referencia', ''), v_desde, v_hasta, nullif(p ->> 'notas', ''), auth.jwt() ->> 'email');
    update saas.empresas set estado = 'activa', pagado_hasta = v_hasta, actualizada_at = now() where id = p_empresa;
    perform saas.registrar_evento(p_empresa, 'pago_registrado', p || jsonb_build_object('hasta', v_hasta));
    perform saas.exponer_esquemas();
    return jsonb_build_object('ok', true, 'pagado_hasta', v_hasta);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_admin_plan_guardar(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare v_id text := lower(nullif(trim(coalesce(p ->> 'id', '')), ''));
begin
    if not saas.es_superadmin() then raise exception 'Solo el administrador de la plataforma' using errcode = 'PT403'; end if;
    if v_id is null or v_id !~ '^[a-z0-9_-]{2,30}$' then raise exception 'Código de plan inválido'; end if;
    insert into saas.planes (id, nombre, descripcion, precio_usd_mes, precio_usd_anual, max_sucursales, max_usuarios, max_productos, modulos, publico, activo, orden)
    values (v_id, coalesce(nullif(trim(p ->> 'nombre'), ''), v_id), p ->> 'descripcion', nullif(p ->> 'precio_usd_mes', '')::numeric, nullif(p ->> 'precio_usd_anual', '')::numeric,
            nullif(p ->> 'max_sucursales', '')::int, nullif(p ->> 'max_usuarios', '')::int, nullif(p ->> 'max_productos', '')::int,
            coalesce(p -> 'modulos', '[]'::jsonb), coalesce((p ->> 'publico')::boolean, true), coalesce((p ->> 'activo')::boolean, true), coalesce(nullif(p ->> 'orden', '')::int, 0))
    on conflict (id) do update set nombre = excluded.nombre, descripcion = excluded.descripcion, precio_usd_mes = excluded.precio_usd_mes,
        precio_usd_anual = excluded.precio_usd_anual, max_sucursales = excluded.max_sucursales, max_usuarios = excluded.max_usuarios,
        max_productos = excluded.max_productos, modulos = excluded.modulos, publico = excluded.publico, activo = excluded.activo, orden = excluded.orden;
    perform saas.registrar_evento(null, 'plan_guardado', p);
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_admin_resumen()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
begin
    if not saas.es_superadmin() then raise exception 'Solo el administrador de la plataforma' using errcode = 'PT403'; end if;
    return jsonb_build_object(
        'ok', true,
        'config', (select to_jsonb(c) from saas.config c where id = 1),
        'planes', (select coalesce(jsonb_agg(to_jsonb(p) order by orden), '[]'::jsonb) from saas.planes p),
        'empresas', (select coalesce(jsonb_agg(to_jsonb(e) || jsonb_build_object('estado_efectivo', saas.estado_efectivo(e),
                        'ultimo_pago', (select to_jsonb(x) from (select fecha, monto_usd, periodo_hasta from saas.pagos where empresa_id = e.id order by fecha desc, creado_at desc limit 1) x))
                        order by e.creada_at desc), '[]'::jsonb) from saas.empresas e),
        'pagos', (select coalesce(jsonb_agg(to_jsonb(p) || jsonb_build_object('empresa', e.nombre) order by p.fecha desc, p.creado_at desc), '[]'::jsonb)
                  from (select * from saas.pagos order by fecha desc, creado_at desc limit 200) p join saas.empresas e on e.id = p.empresa_id),
        'eventos', (select coalesce(jsonb_agg(to_jsonb(v) order by v.fecha desc), '[]'::jsonb) from (select * from saas.eventos order by fecha desc limit 100) v)
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_admin_sincronizar()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
begin
    if not saas.es_superadmin() then raise exception 'Solo el administrador de la plataforma' using errcode = 'PT403'; end if;
    return jsonb_build_object('ok', true, 'empresas', saas.sincronizar_todas());
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_empresa(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare e saas.empresas; v_logo text; v_nombre text;
begin
    select * into e from saas.empresas where slug = lower(trim(coalesce(p_slug, ''))) or esquema = lower(trim(coalesce(p_slug, '')));
    if not found or e.estado = 'cancelada' then return jsonb_build_object('ok', false, 'error', 'No encontramos esa empresa. Revisa el código.'); end if;
    begin
        execute format('select coalesce(opciones->>''nombre_comercial'', nombre_negocio), opciones->>''logo'' from %I.configuracion limit 1', e.esquema)
        into v_nombre, v_logo;
    exception when others then null; end;
    return jsonb_build_object('ok', true, 'slug', e.slug, 'esquema', e.esquema, 'nombre', coalesce(v_nombre, e.nombre), 'logo', v_logo,
                              'estado', saas.estado_efectivo(e));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_mi_suscripcion(p_esquema text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare e saas.empresas; pl saas.planes; v_uid uuid; v_tok text := saas.header('x-refrimar-sesion'); n_u int; n_s int; n_p int;
begin
    select * into e from saas.empresas where esquema = coalesce(nullif(p_esquema, ''), 'public');
    if not found then return jsonb_build_object('ok', false); end if;
    execute format('select usuario_id from %I.sesiones where token_hash = %I.refrimar_hash($1) and not revocada and expira_at > now()', e.esquema, e.esquema)
    into v_uid using v_tok;
    if v_uid is null then return jsonb_build_object('ok', false, 'error', 'Vuelve a entrar'); end if;
    select * into pl from saas.planes where id = e.plan_id;
    execute format('select (select count(*) from %1$I.usuarios where activo is not false), (select count(*) from %1$I.sucursales), (select count(*) from %1$I.productos)', e.esquema)
    into n_u, n_s, n_p;
    return jsonb_build_object('ok', true, 'empresa', e.nombre, 'slug', e.slug, 'plan', pl.nombre, 'plan_id', pl.id, 'estado', saas.estado_efectivo(e),
        'prueba_hasta', e.prueba_hasta, 'pagado_hasta', e.pagado_hasta,
        'limites', jsonb_build_object('usuarios', pl.max_usuarios, 'sucursales', pl.max_sucursales, 'productos', pl.max_productos),
        'uso', jsonb_build_object('usuarios', n_u, 'sucursales', n_s, 'productos', n_p),
        'producto', (select producto_nombre from saas.config where id = 1), 'whatsapp', (select whatsapp from saas.config where id = 1));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_pre_request()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare
    v_met text := upper(coalesce(current_setting('request.method', true), 'GET'));
    v_path text := coalesce(current_setting('request.path', true), '');
    v_esq text; e saas.empresas; v_estado text; v_rpc text;
begin
    v_esq := lower(coalesce(saas.header(case when v_met in ('GET', 'HEAD') then 'accept-profile' else 'content-profile' end), 'public'));
    if v_esq = 'public' then
        perform public.refrimar_pre_request();
        return;
    end if;
    select * into e from saas.empresas where esquema = v_esq;
    if not found then return; end if;          -- PostgREST ya rechaza esquemas que no existen
    v_estado := saas.estado_efectivo(e);
    v_rpc := case when v_path like '/rpc/%' then lower(split_part(substr(v_path, 6), '?', 1)) end;
    if v_estado in ('bloqueada', 'cancelada') and coalesce(v_rpc, '') not in ('sesion_cerrar') then
        raise exception using errcode = 'PT402', message = 'El acceso de ' || e.nombre || ' está suspendido. Escríbenos para reactivarlo.';
    end if;
    if v_estado = 'vencida' and v_met not in ('GET', 'HEAD')
       and coalesce(v_rpc, '') not in ('sesion_iniciar_pin', 'sesion_iniciar_google', 'sesion_validar', 'sesion_cerrar', 'login_usuario', 'login_google') then
        raise exception using errcode = 'PT402', message = 'La suscripción de ' || e.nombre || ' venció: puedes consultar pero no registrar operaciones. Renueva para seguir vendiendo.';
    end if;
    execute format('select %I.refrimar_pre_request()', v_esq);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.saas_registrar_empresa(p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'saas'
AS $function$
declare v_ip text; v_servicio boolean := false; r jsonb;
begin
    -- Si llega por el Worker (con la clave de servicio), la IP real del visitante viene en x-cliente-ip
    begin
        v_servicio := saas.header('x-refrimar-servicio') is not null and exists (select 1 from public.seguridad_config
                      where servicio_token_hash is not null and servicio_token_hash = public.refrimar_hash(saas.header('x-refrimar-servicio')));
    exception when others then v_servicio := false; end;
    v_ip := coalesce(case when v_servicio then saas.header('x-cliente-ip') end, nullif(trim(split_part(coalesce(saas.header('x-forwarded-for'), ''), ',', 1)), ''),
                     saas.header('cf-connecting-ip'), 'sin-ip');
    if not (select registro_abierto from saas.config where id = 1) then raise exception 'El registro de empresas nuevas está cerrado por ahora. Escríbenos.'; end if;
    if coalesce(p_datos ->> 'web', '') <> '' then raise exception 'No se pudo registrar'; end if;   -- trampa anti-robots
    if (select count(*) from saas.registro_intentos where ip = v_ip and fecha > now() - interval '1 day') >= 3
       or (select count(*) from saas.registro_intentos where fecha > now() - interval '1 hour') >= 30 then
        raise exception 'Demasiados registros desde esta conexión. Intenta mañana o escríbenos.';
    end if;
    insert into saas.registro_intentos (ip) values (v_ip);
    r := saas.crear_empresa(p_datos, 'registro');
    return r;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.seguridad_estado()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := refrimar_sesion_uid(0);
begin
    if v_uid is null or not refrimar_es_admin(v_uid) then
        return jsonb_build_object('ok', false, 'error', 'Solo el dueño puede ver esto (vuelve a entrar si acabas de correr la migración).');
    end if;
    return jsonb_build_object(
        'ok', true,
        'modo', refrimar_modo(),
        'pre_request', coalesce((select (select setting from unnest(r.rolconfig) as setting where setting like 'pgrst.db_pre_request=%' limit 1)
                                 from pg_roles r where r.rolname = 'authenticator'), ''),
        'sesiones_activas', (select count(*) from sesiones where not revocada and expira_at > now()),
        'eventos_7d', (select count(*) from seguridad_eventos where fecha > now() - interval '7 days'),
        'ultimos', coalesce((select jsonb_agg(e order by e.fecha desc) from (
            select fecha, ruta, motivo, usuario_nombre from seguridad_eventos where fecha > now() - interval '7 days' order by fecha desc limit 40) e), '[]'::jsonb)
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.seguridad_modo(p_modo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := refrimar_sesion_uid(0);
begin
    if v_uid is null or not refrimar_es_admin(v_uid) then raise exception 'Solo el dueño puede cambiar el modo de seguridad'; end if;
    if p_modo not in ('aviso', 'estricto') then raise exception 'Modo inválido'; end if;
    update seguridad_config set modo = p_modo, actualizado_at = now() where id = 1;
    return jsonb_build_object('ok', true, 'modo', p_modo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.seguridad_token_servicio(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if length(coalesce(p_token, '')) < 24 then raise exception 'Usa una clave de al menos 24 caracteres'; end if;
    update seguridad_config set servicio_token_hash = refrimar_hash(p_token), actualizado_at = now() where id = 1;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.servicio_stock_asegurar(p_codigo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_desc text;
begin
    select descripcion into v_desc from productos where codigo = p_codigo;
    update productos set stock = 999999 where codigo = p_codigo;
    insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
    select s.id, p_codigo, v_desc, 999999 from sucursales s
    on conflict (sucursal_id, producto_codigo) do update set stock = 999999, updated_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sesion_cerrar(p_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update sesiones set revocada = true
    where token_hash = refrimar_hash(coalesce(nullif(p_token, ''), refrimar_header('x-refrimar-sesion')));
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sesion_iniciar_google(p_dispositivo text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb;
begin
    r := login_google();
    if coalesce((r ->> 'success')::boolean, false) then
        r := r || jsonb_build_object('token', refrimar_crear_sesion((r ->> 'id')::uuid, 'google', p_dispositivo));
        r := r || jsonb_build_object('sucursales', coalesce((select to_jsonb(sucursales) from usuarios where id = (r ->> 'id')::uuid), '[]'::jsonb),
                                     'avatar_url', (select avatar_url from usuarios where id = (r ->> 'id')::uuid));
    end if;
    return r;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sesion_iniciar_pin(p_nombre text, p_pin text, p_dispositivo text DEFAULT 'web'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_clave text := 'pin:' || lower(trim(coalesce(p_nombre, '')));
    li login_intentos; u record; v_tok text;
begin
    select * into li from login_intentos where clave = v_clave;
    if found and li.bloqueado_hasta is not null and li.bloqueado_hasta > now() then
        return jsonb_build_object('success', false, 'bloqueado', true,
            'error', 'Demasiados intentos. Espera ' || greatest(1, ceil(extract(epoch from (li.bloqueado_hasta - now())) / 60))::int || ' min y vuelve a intentar.');
    end if;

    select * into u from usuarios where nombre = p_nombre and activo = true limit 1;
    if not found or u.pin is null or u.pin <> coalesce(p_pin, '') then
        insert into login_intentos (clave, fallos, actualizado_at) values (v_clave, 1, now())
        on conflict (clave) do update set
            fallos = case when login_intentos.actualizado_at < now() - interval '30 minutes' then 1 else login_intentos.fallos + 1 end,
            actualizado_at = now()
        returning * into li;
        if li.fallos >= 5 and li.fallos % 5 = 0 then
            update login_intentos set bloqueado_hasta = now() + case when li.fallos >= 10 then interval '15 minutes' else interval '2 minutes' end
            where clave = v_clave;
        end if;
        return jsonb_build_object('success', false, 'error', 'PIN incorrecto');
    end if;

    delete from login_intentos where clave = v_clave;
    v_tok := refrimar_crear_sesion(u.id, 'pin', p_dispositivo);
    return jsonb_build_object('success', true, 'token', v_tok, 'id', u.id, 'nombre', u.nombre, 'rol', u.rol,
        'permisos', coalesce(to_jsonb(u.permisos), '[]'::jsonb), 'sucursal_id', u.sucursal_id,
        'sucursales', coalesce(to_jsonb(u.sucursales), '[]'::jsonb), 'email', u.email, 'avatar_url', u.avatar_url);
end;
$function$
;

