 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := refrimar_sesion_uid(0);
begin
    return jsonb_build_object('ok', v_uid is not null, 'usuario_id', v_uid, 'modo', refrimar_modo());
