CREATE OR REPLACE FUNCTION public.sesiones_revocar_usuario(p_usuario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update sesiones set revocada = true where usuario_id = p_usuario_id and not revocada;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.stock_mover(p_codigo text, p_sucursal_id uuid, p_delta numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_desc text;
    v_nuevo numeric;
begin
    if p_sucursal_id is null or p_sucursal_id = '00000000-0000-0000-0000-000000000001' then
        update productos set stock = coalesce(stock, 0) + p_delta where codigo = p_codigo
        returning stock into v_nuevo;
        if not found then raise exception 'Producto % no existe', p_codigo; end if;
    else
        select descripcion into v_desc from productos where codigo = p_codigo;
        insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
        values (p_sucursal_id, p_codigo, coalesce(v_desc, p_codigo), p_delta)
        on conflict (sucursal_id, producto_codigo)
        do update set stock = sucursal_stock.stock + excluded.stock, updated_at = now()
        returning stock into v_nuevo;
    end if;
    return v_nuevo;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sucursal_eliminar(p_id uuid, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_suc record; v_stock numeric; v_prod int; v_turno text;
begin
    if p_id is null or p_id = '00000000-0000-0000-0000-000000000001' then
        raise exception 'La tienda principal no se puede eliminar.';
    end if;
    select * into v_suc from sucursales where id = p_id;
    if not found then raise exception 'Esa tienda ya no existe.'; end if;

    select count(*), coalesce(sum(stock), 0) into v_prod, v_stock from sucursal_stock where sucursal_id = p_id and coalesce(stock, 0) <> 0;
    if v_prod > 0 then
        raise exception 'A "%" le quedan % producto(s) con inventario (% unidades). Pásalos primero a otra tienda con una transferencia.', v_suc.nombre, v_prod, trim(to_char(v_stock, 'FM999999990.##'));
    end if;

    if to_regclass('public.turnos') is not null then
        execute 'select numero from turnos where sucursal_id = $1 and estado = ''activo'' limit 1' into v_turno using p_id;
        if v_turno is not null then
            raise exception 'La tienda "%" tiene la caja % abierta. Ciérrala antes de eliminar la tienda.', v_suc.nombre, v_turno;
        end if;
    end if;

    insert into sucursales_eliminadas (sucursal_id, nombre, datos, eliminado_por)
    values (p_id, v_suc.nombre, to_jsonb(v_suc), p_usuario);

    -- Quien tenía acceso solo a esa tienda queda sin tienda fija (el dueño le asigna otra)
    update usuarios set sucursales = array_remove(sucursales, p_id) where p_id = any(sucursales);
    begin
        execute 'update usuarios set sucursal_id = null where sucursal_id = $1' using p_id;
    exception when undefined_column then null;
    end;

    begin
        delete from sucursales where id = p_id;   -- borra también sus filas de stock en cero
    exception when foreign_key_violation then
        raise exception 'No se pudo eliminar "%": hay registros que dependen de ella (%). Escríbenos y lo revisamos.', v_suc.nombre, sqlerrm;
    end;
    return jsonb_build_object('ok', true, 'nombre', v_suc.nombre);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sucursal_guardar(p_nombre text, p_id uuid DEFAULT NULL::uuid, p_direccion text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    if p_nombre is null or trim(p_nombre) = '' then
        raise exception 'El nombre es obligatorio';
    end if;

    if p_id is null then
        insert into sucursales (nombre, direccion)
        values (trim(p_nombre), p_direccion)
        returning id into v_id;
    else
        update sucursales set nombre = trim(p_nombre), direccion = p_direccion where id = p_id;
        v_id := p_id;
    end if;

    if v_id is null then
        raise exception 'No se pudo guardar la sucursal';
    end if;
    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sucursal_movimiento_eliminar(p_movimiento_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tipo text;
begin
    if p_movimiento_id is null then
        raise exception 'Falta el movimiento';
    end if;

    select tipo into v_tipo from sucursal_movimientos where id = p_movimiento_id;
    if not found then
        raise exception 'Movimiento no encontrado';
    end if;

    if coalesce(v_tipo, '') <> 'abono' then
        raise exception 'Los traspasos se anulan con revertir_traspaso_sucursal';
    end if;

    delete from sucursal_movimientos where id = p_movimiento_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sucursal_movimiento_registrar(p_sucursal_id uuid, p_tipo text, p_monto numeric DEFAULT 0, p_notas text DEFAULT NULL::text, p_usuario_nombre text DEFAULT 'Sistema'::text, p_producto_codigo text DEFAULT NULL::text, p_producto_descripcion text DEFAULT NULL::text, p_cantidad numeric DEFAULT NULL::numeric, p_costo_unitario numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_sucursal_id is null then
        raise exception 'Falta la sucursal';
    end if;
    if p_tipo is null or trim(p_tipo) = '' then
        raise exception 'Falta el tipo de movimiento';
    end if;
    if trim(p_tipo) not in ('abono', 'traspaso') then
        raise exception 'Tipo de movimiento inválido';
    end if;
    if trim(p_tipo) = 'abono' and (p_monto is null or p_monto <= 0) then
        raise exception 'El monto del abono debe ser mayor a 0';
    end if;

    insert into sucursal_movimientos
        (sucursal_id, tipo, monto, notas, usuario_nombre,
         producto_codigo, producto_descripcion, cantidad, costo_unitario)
    values
        (p_sucursal_id, trim(p_tipo), coalesce(p_monto, 0), p_notas,
         coalesce(p_usuario_nombre, 'Sistema'),
         p_producto_codigo, p_producto_descripcion, p_cantidad, p_costo_unitario);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sucursal_stock_servicio()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if exists (select 1 from productos where codigo = new.producto_codigo and tipo_producto = 'servicio')
       and coalesce(new.stock, 0) < 999999 then
        new.stock := 999999;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tasa_registrar_cambio()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.tasa_bcv_manual is not null and (tg_op = 'INSERT' or new.tasa_bcv_manual is distinct from old.tasa_bcv_manual) then
        insert into tasas_historial (tasa, tasa_anterior)
        values (new.tasa_bcv_manual, case when tg_op = 'UPDATE' then old.tasa_bcv_manual else null end);
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.terminal_estado(p_id uuid, p_estado text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_estado not in ('activo', 'inactivo') then raise exception 'Estado inválido'; end if;
    update pos_terminales set estado = p_estado where id = p_id;
    if not found then raise exception 'Terminal no encontrada'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.terminal_ping(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_t record;
begin
    update pos_terminales set ultima_conexion = now() where token = p_token and estado = 'activo'
    returning * into v_t;
    if not found then return jsonb_build_object('ok', false); end if;
    return jsonb_build_object('ok', true, 'id', v_t.id, 'nombre', v_t.nombre, 'sucursal_id', v_t.sucursal_id, 'sucursal_nombre', v_t.sucursal_nombre);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.terminal_registrar(p_nombre text, p_sucursal_id uuid, p_sucursal_nombre text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_token text; v_id uuid;
begin
    if coalesce(trim(p_nombre), '') = '' then raise exception 'Ponle un nombre a esta caja (ej: CAJA 1)'; end if;
    v_token := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 16));
    insert into pos_terminales (nombre, token, sucursal_id, sucursal_nombre, ultima_conexion)
    values (upper(trim(p_nombre)), v_token, p_sucursal_id, coalesce(p_sucursal_nombre, 'Casa Matriz'), now())
    returning id into v_id;
    return jsonb_build_object('ok', true, 'id', v_id, 'token', v_token);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transferencia_cancelar(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t record; it record; v_saldo numeric; v_casa uuid := '00000000-0000-0000-0000-000000000001';
begin
    select * into t from transferencias where id = p_id for update;
    if not found then raise exception 'Transferencia no encontrada'; end if;
    if t.estado = 'borrador' then
        update transferencias set estado = 'cancelada' where id = p_id;
        return jsonb_build_object('ok', true);
    end if;
    if t.estado <> 'en_transito' then raise exception 'Solo se cancela una transferencia en borrador o en tránsito'; end if;
    -- En tránsito: la mercancía vuelve a la tienda de origen
    for it in select * from transferencia_items where transferencia_id = p_id loop
        v_saldo := refrimar_mover_stock(it.producto_codigo, t.origen_id, it.cantidad, it.descripcion);
        insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total, saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
        values (it.producto_codigo, it.descripcion, current_date, 'entrada_traslado', it.cantidad, it.costo_unitario, it.cantidad * it.costo_unitario, v_saldo, it.costo_unitario,
                t.numero || ' cancelada (vuelve a ' || coalesce(t.origen_nombre, 'origen') || ')', 'Sistema', case when t.origen_id = v_casa then null else t.origen_id end);
    end loop;
    update transferencias set estado = 'cancelada' where id = p_id;
    return jsonb_build_object('ok', true, 'devuelto', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transferencia_enviar_base(p_id uuid, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t transferencias; it record; v_saldo numeric; v_casa uuid := '00000000-0000-0000-0000-000000000001';
begin
    select * into t from transferencias where id = p_id for update;
    if not found then raise exception 'Transferencia no encontrada'; end if;
    if t.estado <> 'borrador' then raise exception 'Solo se envía una transferencia en borrador'; end if;
    for it in select * from transferencia_items where transferencia_id = p_id loop
        if stock_en(it.producto_codigo, t.origen_id) < it.cantidad then
            raise exception 'No hay suficiente stock de "%" en %', coalesce(it.descripcion, it.producto_codigo), coalesce(t.origen_nombre, 'el origen');
        end if;
        v_saldo := refrimar_mover_stock(it.producto_codigo, t.origen_id, -it.cantidad, it.descripcion);
        insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total, saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
        values (it.producto_codigo, it.descripcion, current_date, 'salida_traslado', -it.cantidad, it.costo_unitario, it.cantidad * it.costo_unitario, v_saldo, it.costo_unitario,
                t.numero || ' → ' || coalesce(t.destino_nombre, '') || ' (en tránsito)', coalesce(p_usuario, 'Sistema'), case when t.origen_id = v_casa then null else t.origen_id end);
    end loop;
    update transferencias set estado = 'en_transito', enviada_at = now(), enviada_por = p_usuario, fecha_envio = coalesce(fecha_envio, current_date) where id = p_id;
    return jsonb_build_object('ok', true, 'estado', 'en_transito', 'numero', t.numero);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transferencia_guardar_base(p_id uuid, p_datos jsonb, p_items jsonb, p_procesar boolean, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    d jsonb := coalesce(p_datos, '{}'::jsonb);
    v_id uuid := p_id;
    v_numero text;
    v_estado text;
    v_origen uuid := nullif(d->>'origen_id', '')::uuid;
    v_destino uuid := nullif(d->>'destino_id', '')::uuid;
    it jsonb;
    v_cod text; v_cant numeric; v_costo numeric; v_desc text;
    v_n int := 0; v_u numeric := 0; v_c numeric := 0;
    v_casa uuid := '00000000-0000-0000-0000-000000000001';
begin
    if v_origen is null or v_destino is null then raise exception 'Elige la tienda de origen y la de destino'; end if;
    if v_origen = v_destino then raise exception 'El origen y el destino no pueden ser la misma tienda'; end if;
    if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'Agrega al menos un producto'; end if;

    if v_id is null then
        v_numero := 'TR-' || lpad(nextval('seq_transferencia')::text, 6, '0');
        insert into transferencias (numero, origen_id, destino_id) values (v_numero, v_origen, v_destino) returning id into v_id;
    else
        select estado, numero into v_estado, v_numero from transferencias where id = v_id for update;
        if not found then raise exception 'Transferencia no encontrada'; end if;
        if v_estado <> 'borrador' then raise exception 'Solo se puede editar una transferencia en borrador'; end if;
        delete from transferencia_items where transferencia_id = v_id;
    end if;

    for it in select value from jsonb_array_elements(p_items) loop
        v_cod := nullif(trim(coalesce(it->>'codigo', '')), '');
        v_cant := coalesce((it->>'cantidad')::numeric, 0);
        if v_cod is null or v_cant <= 0 then raise exception 'Producto o cantidad inválida'; end if;
        select descripcion, costo into v_desc, v_costo from productos where codigo = v_cod;
        if not found then raise exception 'Producto % no existe', v_cod; end if;
        if v_origen <> v_casa then
            select coalesce(nullif(costo, 0), v_costo) into v_costo from sucursal_stock where sucursal_id = v_origen and producto_codigo = v_cod;
        end if;
        v_costo := coalesce(v_costo, 0);
        insert into transferencia_items (transferencia_id, producto_codigo, descripcion, cantidad, costo_unitario)
        values (v_id, v_cod, v_desc, v_cant, v_costo);
        v_n := v_n + 1; v_u := v_u + v_cant; v_c := v_c + v_cant * v_costo;
    end loop;

    update transferencias set
        origen_id = v_origen, origen_nombre = coalesce(d->>'origen_nombre', origen_nombre),
        destino_id = v_destino, destino_nombre = coalesce(d->>'destino_nombre', destino_nombre),
        fecha_estimada = nullif(d->>'fecha_estimada', '')::date, fecha_envio = nullif(d->>'fecha_envio', '')::date,
        fecha_recepcion = nullif(d->>'fecha_recepcion', '')::date,
        tipo_transporte = nullif(trim(coalesce(d->>'tipo_transporte', '')), ''), empresa_transporte = nullif(trim(coalesce(d->>'empresa_transporte', '')), ''),
        ref_transporte = nullif(trim(coalesce(d->>'ref_transporte', '')), ''), referencia = nullif(trim(coalesce(d->>'referencia', '')), ''),
        observaciones = nullif(trim(coalesce(d->>'observaciones', '')), ''), usuario_nombre = coalesce(p_usuario, usuario_nombre),
        total_items = v_n, total_unidades = v_u, total_costo = round(v_c, 2)
    where id = v_id;

    if p_procesar then
        for it in select to_jsonb(ti) from transferencia_items ti where ti.transferencia_id = v_id loop
            perform transferir_stock_sucursal(it->>'producto_codigo', (it->>'cantidad')::numeric, (it->>'costo_unitario')::numeric, v_origen, v_destino, coalesce(p_usuario, 'Sistema'));
            insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total, saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
            values (it->>'producto_codigo', it->>'descripcion', current_date, 'salida_traslado', -((it->>'cantidad')::numeric), (it->>'costo_unitario')::numeric,
                    (it->>'cantidad')::numeric * (it->>'costo_unitario')::numeric, stock_en(it->>'producto_codigo', v_origen), (it->>'costo_unitario')::numeric,
                    v_numero || ' → ' || coalesce(d->>'destino_nombre', ''), coalesce(p_usuario, 'Sistema'), case when v_origen = v_casa then null else v_origen end),
                   (it->>'producto_codigo', it->>'descripcion', current_date, 'entrada_traslado', (it->>'cantidad')::numeric, (it->>'costo_unitario')::numeric,
                    (it->>'cantidad')::numeric * (it->>'costo_unitario')::numeric, stock_en(it->>'producto_codigo', v_destino), (it->>'costo_unitario')::numeric,
                    v_numero || ' ← ' || coalesce(d->>'origen_nombre', ''), coalesce(p_usuario, 'Sistema'), case when v_destino = v_casa then null else v_destino end);
        end loop;
        update transferencias set estado = 'completada', completada_at = now(),
            fecha_envio = coalesce(fecha_envio, current_date), fecha_recepcion = coalesce(fecha_recepcion, current_date)
        where id = v_id;
    end if;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero, 'estado', case when p_procesar then 'completada' else 'borrador' end);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transferencia_recibir_base(p_id uuid, p_items jsonb, p_usuario text DEFAULT 'Sistema'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t transferencias; it record; v_rec numeric; v_saldo numeric; v_dif jsonb := '[]'::jsonb; v_casa uuid := '00000000-0000-0000-0000-000000000001';
begin
    select * into t from transferencias where id = p_id for update;
    if not found then raise exception 'Transferencia no encontrada'; end if;
    if t.estado <> 'en_transito' then raise exception 'Esta transferencia no está en tránsito'; end if;
    for it in select * from transferencia_items where transferencia_id = p_id loop
        select coalesce(nullif(x->>'recibido', '')::numeric, it.cantidad) into v_rec
        from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) x where x->>'codigo' = it.producto_codigo limit 1;
        v_rec := coalesce(v_rec, it.cantidad);
        if v_rec < 0 then raise exception 'Cantidad recibida inválida en %', it.producto_codigo; end if;
        update transferencia_items set cantidad_recibida = v_rec where id = it.id;
        if v_rec > 0 then
            v_saldo := refrimar_mover_stock(it.producto_codigo, t.destino_id, v_rec, it.descripcion);
            insert into kardex_movimientos (producto_codigo, producto_descripcion, fecha, tipo, cantidad, costo_unitario, costo_total, saldo_cantidad, saldo_costo_promedio, referencia, usuario_nombre, sucursal_id)
            values (it.producto_codigo, it.descripcion, current_date, 'entrada_traslado', v_rec, it.costo_unitario, v_rec * it.costo_unitario, v_saldo, it.costo_unitario,
                    t.numero || ' ← ' || coalesce(t.origen_nombre, ''), coalesce(p_usuario, 'Sistema'), case when t.destino_id = v_casa then null else t.destino_id end);
        end if;
        if v_rec <> it.cantidad then
            v_dif := v_dif || jsonb_build_object('codigo', it.producto_codigo, 'descripcion', it.descripcion, 'enviado', it.cantidad, 'recibido', v_rec, 'diferencia', v_rec - it.cantidad,
                                                 'valor_usd', round((v_rec - it.cantidad) * it.costo_unitario, 2));
        end if;
    end loop;
    update transferencias set estado = case when jsonb_array_length(v_dif) = 0 then 'completada' else 'con_diferencias' end,
        recibida_at = now(), recibida_por = p_usuario, completada_at = now(), fecha_recepcion = current_date,
        diferencias = case when jsonb_array_length(v_dif) = 0 then null else v_dif end
    where id = p_id;
    return jsonb_build_object('ok', true, 'diferencias', v_dif);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transferir_stock_sucursal(p_producto_codigo text, p_cantidad numeric, p_costo_unitario numeric, p_sucursal_origen_id uuid, p_sucursal_destino_id uuid, p_usuario_nombre text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_casa_matriz uuid := '00000000-0000-0000-0000-000000000001';
    v_producto_id uuid;
    v_producto_descripcion text;
    v_stock_origen numeric;
    v_movimiento_id text;
    v_monto numeric;
begin
    if p_cantidad is null or p_cantidad <= 0 then
        raise exception 'La cantidad debe ser mayor a 0';
    end if;
    if p_sucursal_origen_id is null or p_sucursal_destino_id is null then
        raise exception 'Debes indicar sucursal de origen y destino';
    end if;
    if p_sucursal_origen_id = p_sucursal_destino_id then
        raise exception 'La sucursal de origen y destino no pueden ser la misma';
    end if;

    select id, descripcion into v_producto_id, v_producto_descripcion
    from productos
    where codigo = p_producto_codigo
    for update;

    if not found then
        raise exception 'Producto "%" no encontrado en el catálogo', p_producto_codigo;
    end if;

    v_monto := p_cantidad * coalesce(p_costo_unitario, 0);

    -- ---- 1. DESCONTAR del origen ----
    if p_sucursal_origen_id = v_casa_matriz then
        select stock into v_stock_origen from productos where id = v_producto_id for update;
        if v_stock_origen < p_cantidad then
            raise exception 'Stock insuficiente en Casa Matriz (disponible: %)', v_stock_origen;
        end if;
        update productos set stock = stock - p_cantidad where id = v_producto_id;
    else
        select stock into v_stock_origen
        from sucursal_stock
        where sucursal_id = p_sucursal_origen_id and producto_codigo = p_producto_codigo
        for update;

        if not found or v_stock_origen < p_cantidad then
            raise exception 'Stock insuficiente en la sucursal de origen (disponible: %)', coalesce(v_stock_origen, 0);
        end if;

        update sucursal_stock
        set stock = stock - p_cantidad, updated_at = now()
        where sucursal_id = p_sucursal_origen_id and producto_codigo = p_producto_codigo;
    end if;

    -- ---- 2. ACREDITAR al destino ----
    if p_sucursal_destino_id = v_casa_matriz then
        update productos set stock = stock + p_cantidad where id = v_producto_id;
    else
        insert into sucursal_stock (sucursal_id, producto_codigo, producto_descripcion, stock)
        values (p_sucursal_destino_id, p_producto_codigo, v_producto_descripcion, p_cantidad)
        on conflict (sucursal_id, producto_codigo)
        do update set stock = sucursal_stock.stock + excluded.stock, updated_at = now();
    end if;

    -- ---- 3. Registrar el movimiento (kardex de deuda de la sucursal) ----
    if p_sucursal_origen_id = v_casa_matriz then
        insert into sucursal_movimientos
            (sucursal_id, tipo, producto_codigo, producto_descripcion, cantidad, costo_unitario, monto, usuario_nombre)
        values
            (p_sucursal_destino_id, 'traspaso', p_producto_codigo, v_producto_descripcion, p_cantidad, p_costo_unitario, v_monto, p_usuario_nombre)
        returning id into v_movimiento_id;
    elsif p_sucursal_destino_id = v_casa_matriz then
        insert into sucursal_movimientos
            (sucursal_id, tipo, producto_codigo, producto_descripcion, cantidad, costo_unitario, monto, usuario_nombre, notas)
        values
            (p_sucursal_origen_id, 'abono', p_producto_codigo, v_producto_descripcion, p_cantidad, p_costo_unitario, v_monto, p_usuario_nombre, 'Devolución de mercancía a Casa Matriz')
        returning id into v_movimiento_id;
    end if;

    return jsonb_build_object(
        'ok', true,
        'movimiento_id', v_movimiento_id,
        'producto_codigo', p_producto_codigo,
        'cantidad', p_cantidad
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.turno_abrir(p_usuario_id uuid, p_usuario_nombre text, p_sucursal_id uuid, p_sucursal_nombre text, p_terminal text DEFAULT NULL::text, p_fondo_usd numeric DEFAULT 0, p_fondo_bs numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
    v_numero text;
begin
    if coalesce(trim(p_usuario_nombre), '') = '' then raise exception 'Falta el usuario'; end if;
    if exists (select 1 from turnos where usuario_nombre = p_usuario_nombre and estado = 'activo') then
        raise exception 'Ya tienes un turno abierto. Ciérralo antes de abrir otro.';
    end if;
    v_numero := 'T-' || lpad(nextval('seq_turno')::text, 6, '0');
    insert into turnos (numero, usuario_id, usuario_nombre, sucursal_id, sucursal_nombre, terminal, fondo_usd, fondo_bs)
    values (v_numero, p_usuario_id, p_usuario_nombre, p_sucursal_id, coalesce(p_sucursal_nombre, 'Casa Matriz'),
            p_terminal, greatest(coalesce(p_fondo_usd, 0), 0), greatest(coalesce(p_fondo_bs, 0), 0))
    returning id into v_id;
    return jsonb_build_object('ok', true, 'id', v_id, 'numero', v_numero);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.turno_cerrar(p_id uuid, p_contado_usd numeric, p_contado_bs numeric, p_notas text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_t record;
    v_r jsonb;
    v_tasa numeric;
    v_dif numeric;
begin
    select * into v_t from turnos where id = p_id for update;
    if not found then raise exception 'Turno no encontrado'; end if;
    if v_t.estado <> 'activo' then raise exception 'Este turno ya está cerrado'; end if;

    v_r := turno_resumen(p_id);
    select coalesce(tasa_bcv_manual, 0) into v_tasa from configuracion limit 1;
    v_dif := coalesce(p_contado_usd, 0)
             + case when coalesce(v_tasa, 0) > 0 then coalesce(p_contado_bs, 0) / v_tasa else 0 end
             - (v_r->>'esperado_usd')::numeric;

    update turnos set
        estado = 'cerrado', cerrado_at = now(),
        ventas_count = (v_r->>'ventas_count')::int, ventas_usd = (v_r->>'ventas_usd')::numeric,
        esperado_usd = (v_r->>'esperado_usd')::numeric, esperado_bs = (v_r->>'esperado_bs')::numeric,
        contado_usd = coalesce(p_contado_usd, 0), contado_bs = coalesce(p_contado_bs, 0),
        tasa_cierre = v_tasa, diferencia_usd = round(v_dif, 2), resumen = v_r, notas = p_notas
    where id = p_id;
    return jsonb_build_object('ok', true, 'diferencia_usd', round(v_dif, 2), 'resumen', v_r);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.turno_resumen(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_t record;
    v_hasta timestamptz;
    v_casa boolean;
    v_res jsonb;
    v_ef_usd numeric; v_ef_bs numeric; v_ventas int; v_ventas_usd numeric;
begin
    select * into v_t from turnos where id = p_id;
    if not found then raise exception 'Turno no encontrado'; end if;
    v_hasta := coalesce(v_t.cerrado_at, now());
    v_casa := (v_t.sucursal_id is null or v_t.sucursal_id = '00000000-0000-0000-0000-000000000001');

    with movs as (
        select * from caja_movimientos m
        where m.usuario_nombre = v_t.usuario_nombre
          and m.fecha >= v_t.abierto_at and m.fecha <= v_hasta
          and (case when v_casa then (m.sucursal_id is null or m.sucursal_id = '00000000-0000-0000-0000-000000000001')
                    else m.sucursal_id = v_t.sucursal_id end)
          and m.tipo not in ('apertura', 'cierre')
    )
    select
        coalesce(sum(case when (metodo_pago is null or metodo_pago in ('efectivo', 'divisa'))
                          then (case when tipo in ('venta', 'ingreso') then coalesce(monto_usd, 0) else -coalesce(monto_usd, 0) end) else 0 end), 0),
        coalesce(sum(case when (metodo_pago is null or metodo_pago in ('efectivo', 'divisa'))
                          then (case when tipo in ('venta', 'ingreso') then coalesce(monto_bs, 0) else -coalesce(monto_bs, 0) end) else 0 end), 0),
        count(*) filter (where tipo = 'venta'),
        coalesce(sum(monto_usd) filter (where tipo = 'venta'), 0),
        coalesce((select jsonb_agg(jsonb_build_object('metodo', metodo, 'cantidad', n, 'usd', usd) order by usd desc)
                  from (select coalesce(metodo_pago, 'efectivo') metodo, count(*) n, sum(coalesce(monto_usd, 0)) usd
                        from movs where tipo = 'venta' group by 1) x), '[]'::jsonb)
    into v_ef_usd, v_ef_bs, v_ventas, v_ventas_usd, v_res
    from movs;

    return jsonb_build_object(
        'ventas_count', v_ventas, 'ventas_usd', round(v_ventas_usd, 2),
        'efectivo_usd', round(v_ef_usd, 2), 'efectivo_bs', round(v_ef_bs, 2),
        'esperado_usd', round(v_t.fondo_usd + v_ef_usd, 2), 'esperado_bs', round(v_t.fondo_bs + v_ef_bs, 2),
        'por_metodo', v_res);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_asignar_sucursal(p_id uuid, p_sucursal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update usuarios set sucursal_id = p_sucursal_id where id = p_id;
    if not found then raise exception 'Usuario no encontrado'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_cambiar_estado(p_id uuid, p_activo boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_id is null then
        raise exception 'Falta el usuario';
    end if;
    update usuarios set activo = coalesce(p_activo, true) where id = p_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_cambiar_pin(p_id uuid, p_actual text, p_nuevo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_pin text; v_uid uuid := refrimar_sesion_uid(0);
begin
    if (v_uid is not null or refrimar_modo() = 'estricto') and coalesce(v_uid = p_id, false) = false and not refrimar_es_admin(v_uid) then
        raise exception 'Solo puedes cambiar tu propio PIN';
    end if;
    if p_nuevo is null or length(p_nuevo) < 32 then raise exception 'PIN nuevo inválido'; end if;
    select pin into v_pin from usuarios where id = p_id;
    if not found then raise exception 'Usuario no encontrado'; end if;
    if v_pin is not null and v_pin <> coalesce(p_actual, '') then raise exception 'El PIN actual no es correcto'; end if;
    update usuarios set pin = p_nuevo where id = p_id;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_eliminar(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if p_id is null then
        raise exception 'Falta el usuario';
    end if;
    delete from usuarios where id = p_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_email_guardar(p_id uuid, p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
    if v is not null and v !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Correo inválido'; end if;
    if v is not null and exists (select 1 from usuarios where lower(email) = v and id <> p_id) then raise exception 'Ese correo ya está asignado a otro colaborador'; end if;
    update usuarios set email = v where id = p_id;
    if not found then raise exception 'Usuario no encontrado'; end if;
    return jsonb_build_object('ok', true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_guardar(p_nombre text, p_id uuid DEFAULT NULL::uuid, p_pin text DEFAULT NULL::text, p_rol text DEFAULT NULL::text, p_activo boolean DEFAULT true, p_permisos jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    if p_nombre is null or trim(p_nombre) = '' then
        raise exception 'El nombre es obligatorio';
    end if;
    if p_rol is null or trim(p_rol) = '' then
        p_rol := 'cajero';
    end if;
    if p_permisos is null then
        p_permisos := '[]';
    end if;

    if p_id is null then
        if p_pin is null or length(trim(p_pin)) = 0 then
            raise exception 'El PIN es obligatorio para nuevos usuarios';
        end if;
        insert into usuarios (nombre, pin, rol, activo, permisos)
        values (trim(p_nombre), p_pin, p_rol, p_activo, p_permisos)
        returning id into v_id;
    else
        if p_pin is not null and length(trim(p_pin)) > 0 then
            update usuarios
            set nombre = trim(p_nombre), pin = p_pin, rol = p_rol,
                activo = p_activo, permisos = p_permisos
            where id = p_id;
        else
            update usuarios
            set nombre = trim(p_nombre), rol = p_rol,
                activo = p_activo, permisos = p_permisos
            where id = p_id;
        end if;
        v_id := p_id;
    end if;

    if v_id is null then
        raise exception 'No se pudo guardar el usuario';
    end if;
    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.usuario_perfil_guardar(p_id uuid, p_nombres text, p_apellido text, p_telefono text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_nombre text; v_uid uuid := refrimar_sesion_uid(0);
begin
    if (v_uid is not null or refrimar_modo() = 'estricto') and coalesce(v_uid = p_id, false) = false and not refrimar_es_admin(v_uid) then
        raise exception 'Solo puedes editar tu propio perfil';
    end if;
    if nullif(trim(coalesce(p_nombres, '')), '') is null then raise exception 'Escribe tu nombre'; end if;
    v_nombre := trim(trim(p_nombres) || ' ' || coalesce(trim(p_apellido), ''));
    if exists (select 1 from usuarios where lower(nombre) = lower(v_nombre) and id <> p_id) then
        raise exception 'Ya existe un colaborador llamado %', v_nombre;
    end if;
    update usuarios set nombres = trim(p_nombres), apellido = nullif(trim(coalesce(p_apellido, '')), ''),
        nombre = v_nombre, telefono = nullif(trim(coalesce(p_telefono, '')), '')
    where id = p_id;
    if not found then raise exception 'Usuario no encontrado'; end if;
    return jsonb_build_object('ok', true, 'nombre', v_nombre);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ventas_bloquear_anulacion_con_nc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.estado = 'anulada' and coalesce(old.estado, '') <> 'anulada' and coalesce(old.total_devuelto_usd, 0) > 0 then
        raise exception 'Esta factura tiene notas de crédito. Usa otra nota de crédito para devolver el resto.';
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ventas_igtf_calcular()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v numeric;
begin
    if jsonb_typeof(new.pagos) = 'array' then
        select coalesce(sum(nullif(x->>'igtf_usd', '')::numeric), 0) into v from jsonb_array_elements(new.pagos) x;
        new.igtf_usd := round(coalesce(v, 0), 2);
        new.igtf_bs := round(coalesce(v, 0) * coalesce(nullif(new.tasa_bcv, 0), case when coalesce(new.total_usd, 0) > 0 then new.total_bs / new.total_usd else 0 end), 2);
    end if;
    return new;
end;
$function$
;
